-- Proteini.mk: Albanian (al) translations for the 170 products not covered by the proteins batch.
-- Generated 2026-11-17 from the Macedonian text. Only fills empty fields (never overwrites).
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
IF COL_LENGTH('dbo.Products', 'NameAl') IS NULL
    THROW 50000, 'dbo.Products.NameAl is missing; run the translation columns migration first.', 1;
GO

BEGIN TRANSACTION;

-- Product_Id: 1041 (BATTERY CARNITINE 500, 60 капсули)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY CARNITINE 500, 60 kapsula' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>504 mg L-karnitinë tartrat për kapsulë</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><h3>Suplement ushqimor me L-karnitinë, në kapsula.  </h3><p>L-karnitina është një aminoacid që gjendet natyrshëm në trup. Battery Carnitine 500 është suplement ushqimor që përmban 504 mg L-karnitinë tartrat për kapsulë.  Në trup, karnitina vepron si transportues i acideve yndyrore me zinxhir të gjatë drejt mitokondrive, ku ato oksidohen për të prodhuar energji. L-karnitina formohet nga lizina dhe metionina, kryesisht në mëlçi dhe në veshka. Për sintezën e L-karnitinës nevojiten gjithashtu vitamina C, hekuri, vitamina B6 dhe niacina. Në disa rrethana, nevoja për karnitinë mund ta tejkalojë kapacitetin biosintetik të organizmit; atëherë këshillohet të shtohet L-karnitina si suplement ushqimor.  Battery Carnitine 500 është ideal për këdo që kërkon një burim karnitine të lehtë për t''u marrë, i cili mund të përdoret gjatë gjithë ditës.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 kapsulë me një gotë ujë 20 minuta para stërvitjes. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 1041;

-- Product_Id: 1042 (BATTERY CLA, 150 капсули)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY CLA, 150 kapsula' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Acid linoleik i konjuguar </li><li>Nga vaj natyral i shafranit</li><li>400 mg CLA për kapsulë</li><li>37 porcione për paketim</li></ul><h3>Suplement ushqimor me acid linoleik të konjuguar (CLA) në kapsula.</h3><p>CLA, ose acidi linoleik i konjuguar, është një acid yndyror natyral që i përket familjes omega-6.  Kapsulat e buta xhelatinoze Battery CLA janë një formë praktike e acidit yndyror omega-6 të modifikuar, i ashtuquajturi acid linoleik i konjuguar. Çdo kapsulë Battery CLA përmban një dozë prej 400 mg CLA.  CLA gjendet natyrshëm në ushqime si vezët dhe gjalpi, si dhe në mishin e kuq. Fatkeqësisht, përmbajtja e CLA në këto burime mund të jetë mjaft e ulët, prandaj ndonjëherë nevojitet përdorimi i suplementeve ushqimore për të plotësuar nevojat mesatare ditore. CLA në kapsulat Battery vjen nga vaji natyral i shafranit.  Çfarë tjetër e përmirëson efektin e Battery CLA?  Për ta përforcuar edhe më shumë efektin e CLA, rekomandohet përdorimi i djegësve të yndyrës (p.sh. Battery Burner) dhe i shejkëve me përmbajtje të lartë proteinash (p.sh. Battery Whey Protein). Battery Burner rekomandohet para stërvitjes ose vaktit, ndërsa Battery Whey Protein rekomandohet pas stërvitjes ose si zëvendësim vakti gjatë ditës.  Sasia neto: 150 kapsula</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 4 kapsula.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, mundësisht pas vaktit. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, larg nxehtësisë dhe dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 1042;

-- Product_Id: 1043 (BATTERY COLLAGEN VITAL)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY COLLAGEN VITAL' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Pije për vitalitet</p></li><li><p>Mbështetje gjatë ngarkesës së kyçeve për shkak të sportit ose moshës</p></li><li><p>Veprim parandalues dhe mbështetës</p></li><li><p>Për sportistë rekreativë dhe profesionistë</p></li><li><p>Për persona të moshës së mesme dhe të moshuar</p></li></ul><p><strong>Suplement ushqimor me ëmbëlsues. Përzierje e kolagjenit të hidrolizuar, glukozaminës, kondroitinës, MSM-së, shafranit të Indisë dhe vitaminës C për përgatitjen e një pijeje të shijshme.</strong></p><p>Ju prezantojmë pijen tonë premium me kolagjen, të krijuar për të mbështetur vitalitetin e organizmit. Me një kombinim unik të kolagjenit, glicinës, glukozaminës, kondroitinës, MSM-së, shafranit të Indisë dhe vitaminës C, kjo pije është zgjedhje e shkëlqyer për mbështetjen e fleksibilitetit dhe shëndetit të kyçeve, ruajtjen e lëvizshmërisë dhe mirëqenien e përgjithshme.</p><h4><strong>Përbërësit kryesorë:</strong></h4><p><strong>Kolagjen i hidrolizuar (tipi I dhe III)</strong></p><p>Mbështet fortësinë strukturore të kërcit, tendinave dhe ligamenteve. Kontribuon në elasticitetin dhe fortësinë e indit lidhor.</p><p><strong>Glicina</strong></p><p>Glicina ka rol të rëndësishëm në krijimin e kolagjenit dhe rinovimin e indeve. E kombinuar me kolagjenin, ndihmon në forcimin e indit lidhor dhe mbështet rikuperimin e muskujve pas aktivitetit fizik.</p><p><strong>Glukozaminë sulfat</strong></p><p>Ndihmon në ruajtjen e shëndetit të kërcit, mbështet lubrifikimin e kyçeve dhe mund të kontribuojë në ngadalësimin e ndryshimeve të kyçeve që lidhen me moshën.</p><p><strong>Kondroitinë sulfat</strong></p><p>Vepron në sinergji me glukozaminën për të mbështetur elasticitetin e kërcit, për të ulur ngurtësinë dhe për një amortizim më të mirë të kyçeve.</p><p><strong>MSM (metilsulfonilmetan)</strong></p><p>Përbërje natyrale e squfurit, e njohur për rolin e saj në mbështetjen e komoditetit të kyçeve dhe rikuperimit.</p><p><strong>Ekstrakt i shafranit të Indisë</strong></p><p>Shafrani i Indisë është i njohur për vetitë e tij anti-inflamatore. Vepron në sinergji me përbërësit e tjerë dhe ndihmon në mbështetjen e rikuperimit dhe lëvizshmërisë së kyçeve.</p><p><strong>Vitamina C</strong></p><p>Është e domosdoshme për krijimin normal të kolagjenit. Kontribuon në mbrojtjen e qelizave nga stresi oksidativ dhe në funksionin normal të kërcit.</p><h4><strong>Përfitimet kryesore:</strong></h4><ul><li><p><strong>Mbështetje e plotë për kyçet, ligamentet dhe indin lidhor:</strong> Ndihmon në ruajtjen e shëndetit të kyçeve dhe të indeve që mbështesin sistemin muskulo-skeletor.</p></li><li><p><strong>Mbështetje në rast inflamacioni dhe ngurtësie të kyçeve:</strong> E krijuar për të ndihmuar në ruajtjen e lëvizshmërisë dhe komoditetit gjatë lëvizjes.</p></li><li><p><strong>Mbështetje e fortësisë së ligamenteve dhe tendinave dhe e rinovimit të indit lidhor:</strong> Për lëvizshmëri më të mirë të kyçeve dhe rrezik më të ulët lëndimesh.</p></li><li><p><strong>Formulë me biodisponueshmëri të lartë:</strong> E formuluar me kujdes për thithje dhe shfrytëzim optimal të përbërësve aktivë.</p></li><li><p><strong>E lehtë për t''u përfshirë në rutinën e përditshme:</strong> Pije freskuese që përgatitet shpejt dhe lehtë.</p></li></ul><h4><strong>Për kë është e destinuar?</strong></h4><ul><li><p><strong>Sportistët:</strong> Mbështet rikuperimin e indit muskulor dhe lidhor, si dhe shëndetin e kockave.</p></li><li><p><strong>Personat e moshuar:</strong> Mbështet shëndetin e kockave, fleksibilitetin e kyçeve dhe vitalitetin e përgjithshëm.</p></li><li><p><strong>Personat me stil jetese aktiv:</strong> Mbështet shëndetin e përgjithshëm, lëvizshmërinë dhe qëndrueshmërinë.</p></li></ul><h4><strong>Pse të prisni?</strong></h4><p>Përfshijeni Collagen Drink në rutinën tuaj të përditshme dhe shfrytëzoni përfitimet e këtij kombinimi unik. Pavarësisht nëse dëshironi të mbështetni shëndetin e përgjithshëm apo të përqendroheni në nevoja specifike si shqetësimi dhe ngurtësia e kyçeve, Collagen Drink është zgjidhje praktike për të mbështetur një stil jetese më aktiv dhe më vital.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 400 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është ¾ lugë matëse (10 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni në mëngjes me stomak bosh.
PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ushqyerja e ekuilibruar dhe e larmishme dhe stili i shëndetshëm i jetesës janë të rëndësishme. Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion (10 g = ¾ lugë matëse) me 300 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1043;

-- Product_Id: 1044 (BATTERY COMPLETE AMINOS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY COMPLETE AMINOS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>12 aminoacide, përfshirë aminoacidet esenciale dhe BCAA</li><li>I pasuruar me elektrolite (magnez, natrium, klorure)</li><li>Pluhur që tretet shpejt, ideal para ose gjatë stërvitjes</li><li>Freskues dhe i lehtë për t''u pirë</li><li>Prodhuar në kapacitetet tona prodhuese në BE sipas standardeve të larta të cilësisë</li></ul><p><strong>Suplement ushqimor me ëmbëlsues.</strong></p><p>Mbështeteni stërvitjen tuaj me <strong>Battery Complete Aminos</strong>, një suplement ushqimor freskues me aminoacide, i krijuar për të mbështetur performancën dhe rikuperimin. Çdo porcion siguron një <strong>përzierje të ekuilibruar me kujdes prej 12 aminoacidesh</strong>, përfshirë aminoacidet esenciale dhe BCAA (L-leucinë, L-izoleucinë, L-valinë), gjë që e bën <strong>zgjedhje ideale para, gjatë ose pas stërvitjes.</strong></p><p><strong>PSE DO T''JU PËLQEJË</strong></p><ul><li><strong>12 aminoacide në çdo porcion</strong> – përfshirë aminoacidet esenciale dhe BCAA</li><li><strong>Me elektrolite</strong> – magnez, natrium dhe klorure për të mbështetur hidratimin gjatë stërvitjes</li><li><strong>Shije të shijshme</strong> tropikale dhe berry – të lehta, freskuese dhe të këndshme për t''u pirë</li><li><strong>Pluhur që tretet shpejt</strong> – ideal për shishen tuaj të stërvitjes</li><li><strong>Prodhuar në kapacitetet tona prodhuese në BE</strong> sipas standardeve të larta të cilësisë</li></ul><p><strong>SI PËRSHTATET NË RUTINËN TUAJ</strong></p><p>Përzieni me ujë dhe konsumoni <strong>para ose gjatë stërvitjes</strong> si plotësim i stilit aktiv të jetesës.</p><p>Battery Complete Aminos është mënyrë praktike për të <strong>rritur marrjen ditore të aminoacideve</strong> – pa pije me shumë sheqer dhe pa kombinime të ndërlikuara suplementesh.</p><p><strong>PËR KË ËSHTË I DESTINUAR</strong></p><ul><li>Sportistë që stërviten për forcë dhe qëndrueshmëri</li><li>Entuziastë të fitnesit dhe persona aktivë</li><li>Këdo që kërkon një suplement me aminoacide të shijshëm dhe të lehtë për t''u përdorur</li></ul><p>Çojeni ushqyerjen tuaj për stërvitje në një nivel më të lartë me <strong>Battery Complete Aminos</strong> dhe mbajeni performancën në maksimum.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (15 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni para dhe gjatë stërvitjes. Lëreni pijen të qëndrojë pak kohë që pluhuri të tretet sa më mirë. Sasia maksimale ditore është 1 porcion (15 g). PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion (15 g) në 800 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1044;

-- Product_Id: 1046 (BATTERY COMPLETE GAINER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY COMPLETE GAINER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Formulë me përmbajtje të lartë proteinash dhe kalorish</p></li><li><p>E pasuruar me kreatinë për të mbështetur forcën</p></li><li><p>Matricë proteinike me dy faza</p></li><li><p>Formulë e pastër dhe shije e shkëlqyer</p></li><li><p>Përdorim i larmishëm</p></li><li><p>Prodhuar në kapacitetet tona prodhuese në BE</p></li></ul><p><strong>Suplement ushqimor me ëmbëlsues. Përmbajtje e lartë proteinash.</strong></p><p><strong>MBËSHTETENI RRITJEN ME USHQYERJE TË SAKTË</strong></p><p>Battery Complete Gainer është suplement sportiv i formuluar shkencërisht, me përmbajtje të lartë proteinash dhe kalorish, i krijuar për t''ju ndihmuar të rritni masën muskulore dhe forcën dhe të rikuperoheni më shpejt pas stërvitjeve intensive.</p><p>Pavarësisht nëse e keni të vështirë të shtoni peshë, jeni bodibilder apo thjesht dëshironi të merrni më shumë kalori në mënyrën e duhur gjatë fazës së bulk-ut, Battery Complete Gainer i jep trupit atë që i nevojitet – kur i nevojitet më shumë.</p><p><strong>PËRBËRËSIT KRYESORË:</strong></p><ul><li><p>Karbohidrate 67% (maltodekstrinë me cilësi të lartë)</p></li><li><p>Proteina 22% (koncentrat proteine WHEY + koncentrat proteine QUMËSHTI)</p></li><li><p>Kreatinë monohidrat 3 g (përbërës i provuar për mbështetjen e forcës)</p></li></ul><p><strong>PËRFITIMET:</strong></p><ul><li><p><strong>Rritje e optimizuar e muskujve:</strong> I pasur me karbohidrate (maltodekstrinë) që japin energji për stërvitje dhe ndihmojnë në mbështetjen e masës muskulore.</p></li><li><p><strong>Matricë proteinike me cilësi të lartë:</strong> Kombinon proteinën whey që tretet shpejt me proteinën e qumështit që çlirohet më ngadalë, për furnizim të shpejtë dhe të zgjatur me proteina.</p></li><li><p><strong>Mbështetje e performancës:</strong> Përmban 3 g kreatinë monohidrat për porcion për të mbështetur forcën, shpërthimin dhe intensitetin e stërvitjes.</p></li><li><p><strong>Përzierje e lehtë dhe shije e shkëlqyer:</strong> I disponueshëm në shijet Chocolate Cake, Vanilla Ice Cream dhe Cookie &amp; Cream.</p></li><li><p>Pa sheqer të shtuar, pa mbushës të panevojshëm dhe pa shtesa të panevojshme.</p></li><li><p><strong>I sigurt dhe me cilësi të lartë:</strong> Prodhuar në kapacitetet tona prodhuese në BE nga përbërës të kontrolluar, pa aditivë të panevojshëm dhe sipas standardeve të larta të cilësisë dhe sigurisë.</p></li></ul><p><strong>KUR TA PËRDORNI:</strong></p><ul><li><p><strong>Pas stërvitjes:</strong> Për rimbushjen e rezervave të glikogjenit dhe mbështetjen e rikuperimit muskulor.</p></li><li><p><strong>Ndërmjet vakteve:</strong> Për marrje shtesë kalorish dhe proteinash gjatë ditës.</p></li><li><p><strong>Para gjumit:</strong> Për marrje shtesë proteinash me çlirim më të ngadaltë gjatë natës.</p></li><li><p><strong>Në çdo kohë kur ju nevojitet mbështetje për shtimin e masës:</strong> Kalori shtesë kur ju nevojiten më shumë.</p></li></ul><p><strong>PËR KË ËSHTË I DESTINUAR:</strong></p><ul><li><p><strong>Personat që e kanë të vështirë të shtojnë peshë</strong></p></li><li><p><strong>Bodibilderët</strong> dhe <strong>sportistët</strong> në fazën e bulk-ut</p></li><li><p><strong>Entuziastët e fitnesit</strong> që kërkojnë formulë me shumë kalori për të mbështetur masën muskulore</p></li><li><p><strong>Kushdo</strong> që ka nevojë për një formulë të ekuilibruar për rritjen e masës trupore</p></li></ul><p><strong>PRODHUAR NË KAPACITETET TONA PRODHUESE NË BE:</strong></p><ul><li><p>Përbërës me cilësi të lartë dhe të kontrolluar, pa aditivë të panevojshëm.</p></li><li><p>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</p></li></ul><p><strong>Stërvitu fort. Rikuperohu më me mençuri. Rritu më shumë.</strong></p><p><strong>ÇLIRO POTENCIALIN TËND PËR MASË me Battery Complete Gainer!</strong></p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 1000 g / 3000 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 3 lugë matëse (100 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni pas ushtrimeve. Doza maksimale ditore është 1 porcion (100 g). Produkti është i destinuar për të rriturit që kryejnë ushtrime me intensitet të lartë. PARALAJMËRIME: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe një stil të shëndetshëm jetese. Mbajeni larg fëmijëve të vegjël. RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 100 g pluhur (3 lugë matëse) në 500 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1046;

-- Product_Id: 1050 (BATTERY COMPLETE GAINER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY COMPLETE GAINER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Përmbajtje e lartë proteinash dhe kalorish</li><li>Formulë e pasuruar me kreatinë </li><li>Matricë proteinike me dy faza</li><li>E pastër dhe e shijshme </li><li>Përdorim i larmishëm</li><li>Prodhuar në kapacitetin tonë prodhues në BE</li></ul><h3>Suplement ushqimor me ëmbëlsues. Nivel i lartë proteinash.  RRITNI REZULTATET ME USHQYERJE TË SAKTË</h3><p>Battery Complete Gainer është suplement sportiv i formuluar shkencërisht, me shumë proteina dhe kalori, i krijuar për t''ju ndihmuar të fitoni masë muskulore të pastër, të rritni forcën dhe të rikuperoheni më shpejt pas stërvitjeve intensive.  Pavarësisht nëse e keni të vështirë të shtoni peshë, jeni bodibilder apo thjesht dëshironi të shtoni masë në mënyrën e duhur, Battery Complete Gainer i siguron trupit tuaj atë që i nevojitet – kur i nevojitet më shumë.  PËRBËRËSIT KRYESORË:  Karbohidrate 67% (maltodekstrinë me cilësi të lartë) Proteina 22% (koncentrat proteine hirre + koncentrat proteine qumështi) Kreatinë monohidrat 3 g (përforcues i forcës i provuar klinikisht) PËRFITIMET:  Rritje e optimizuar e muskujve: I pasur me karbohidrate komplekse (maltodekstrinë) për t''i dhënë energji stërvitjeve dhe për të parandaluar zbërthimin e muskujve. Matricë proteinike me cilësi të lartë: Kombinon hirrën që tretet shpejt me proteinën e qumështit me çlirim të ngadaltë, për rikuperim të menjëhershëm dhe të qëndrueshëm të muskujve. Rritje e provuar e performancës: I pasuruar me 3 g kreatinë monohidrat për porcion për të rritur forcën, fuqinë dhe intensitetin e stërvitjes. Thithje e shpejtë, shije e shkëlqyer: Përzihet lehtë dhe vjen në shije të shijshme si tortë me çokollatë, akullore me vanilje dhe biskota me krem. Pa sheqer të shtuar, pa mbushës, pa gjëra të panevojshme. I sigurt dhe me cilësi të lartë: Prodhuar në kapacitetin tonë prodhues në BE nga përbërës të kontrolluar, pa aditivë të panevojshëm, sipas standardeve më të larta të cilësisë dhe sigurisë.  KUR TA PËRDORNI:  Pas stërvitjes: Rimbushni rezervat e glikogjenit dhe nisni riparimin e muskujve. Ndërmjet vakteve: Mbajeni gjendjen anabolike aktive gjatë gjithë ditës. Para gjumit: Mbështetni rikuperimin gjatë natës me proteina që treten ngadalë. Mbështetje e masës në çdo kohë: Kalori shtesë kur ju nevojiten më shumë. PËR KË ËSHTË I DESTINUAR:  Personat që e kanë të vështirë të shtojnë peshë. Bodibilderët dhe sportistët gjatë fazës së shtimit të masës muskulore. Entuziastët e fitnesit që duan karburant me shumë kalori për muskujt. Kushdo që ka nevojë për një formulë të ekuilibruar për ndërtimin e masës. PRODHUAR NË KAPACITETIN TONË PRODHUES NË BE:  Përbërës me cilësi të lartë dhe të provuar, pa aditivë të panevojshëm. Prodhuar në BE sipas standardeve më të larta të cilësisë dhe sigurisë. Stërvitu fort. Rikuperohu më me mençuri. Rritu më shumë.  ÇLIRO POTENCIALIN TËND TË MADH me Battery Complete Gainer!  *Ushqyerja e ekuilibruar dhe e larmishme dhe stili i shëndetshëm i jetesës janë të rëndësishme.  Sasia neto: 1000 g / 3000 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 3 lugë matëse (100 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni pas ushtrimeve. Doza maksimale ditore është 1 porcion (100 g). Produkti është i destinuar për të rriturit që kryejnë ushtrime me intensitet të lartë. PARALAJMËRIME: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe një stil të shëndetshëm jetese. Mbajeni larg fëmijëve të vegjël. RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 100 g pluhur (3 lugë matëse) në 500 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1050;

-- Product_Id: 1053 (BATTERY COMPLETE HYDRATION)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY COMPLETE HYDRATION' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Përzierje e plotë elektrolitesh për hidratim efektiv</p></li><li><p>174 mg natrium për porcion për të zëvendësuar humbjet nga djersitja</p></li><li><p>Me magnez citrat për thithje të lartë</p></li><li><p>Pa sheqer dhe me shije freskuese</p></li><li><p>Formulë vegane e përshtatshme për stil jetese aktiv</p></li></ul><p></p><p><strong>Suplement ushqimor me ëmbëlsues.</strong></p><p>Qëndroni mirë të hidratuar dhe mbajeni performancën në nivel të lartë me <strong>Battery Complete Hydration</strong>, një suplement ushqimor me elektrolite pa sheqer, i krijuar për të mbështetur ekuilibrin e lëngjeve gjatë stërvitjes intensive dhe aktivitetit fizik të përditshëm. Me një kombinim të saktë mineralesh esenciale dhe vitaminë C, ndihmon që mineralet e humbura nga djersitja të zëvendësohen shpejt dhe në mënyrë efektive.</p><p><strong>PËRFITIMET KRYESORE</strong></p><ul><li><p><strong>Formulë e avancuar elektrolitesh</strong> me natrium, kalium, kalcium dhe magnez</p></li><li><p><strong>174 mg natrium për porcion</strong> – ideale për hidratim gjatë stërvitjes</p></li><li><p><strong>Përmban magnez citrat</strong> – formë magnezi me biodisponueshmëri të lartë</p></li><li><p><strong>Shije freskuese grejpfrut rozë/limon dhe qershi/manaferra</strong> – të lehta, freskuese dhe ideale për shuarjen e etjes</p></li><li><p><strong>Pa sheqer dhe i përshtatshëm për veganët</strong></p></li><li><p><strong>Prodhuar në BE</strong> sipas standardeve të rrepta të cilësisë</p></li></ul><p><strong>ÇFARË PËRMBAN</strong></p><p>Çdo porcion siguron një kombinim të ekuilibruar elektrolitesh dhe <strong>vitaminë C</strong>, për të mbështetur hidratimin dhe funksionimin normal të muskujve dhe sistemit nervor gjatë aktivitetit fizik.</p><p><strong>MËNYRA E PËRDORIMIT</strong></p><p>Thjesht përzieni me ujë dhe konsumoni para ose gjatë stërvitjes. Ideal për stërvitje në palestër, stërvitje qëndrueshmërie, sporte ekipore ose ditë të nxehta kur hidratimi i duhur është veçanërisht i rëndësishëm.</p><p><strong>PËR KË ËSHTË I DESTINUAR</strong></p><ul><li><p>Sportistë që stërviten për qëndrueshmëri dhe forcë</p></li><li><p>Persona aktivë dhe entuziastë të fitnesit</p></li><li><p>Këdo që kërkon një zgjidhje të pastër hidratimi pa sheqer</p></li></ul><p><strong>Freskohuni, rimbushni elektrolitet dhe mbusheni veten me energji me Battery Complete Hydration.</strong></p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 250 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse e plotë (10 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pini 1 porcion para ose gjatë ushtrimeve. Sasia maksimale ditore është 1 porcion (10 g). Produkti është i destinuar për të rriturit që kryejnë ushtrime me intensitet të lartë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Te personat e ndjeshëm, magnezi në doza mbi 250 mg mund të ketë efekt laksativ.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 500 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1053;

-- Product_Id: 1058 (BATTERY COMPLETE VIT&MIN)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY COMPLETE VIT&MIN' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li><p>Siguron një gamë të gjerë vitaminash dhe mineralesh</p></li><li><p>Për persona fizikisht aktivë dhe me stil jetese dinamik</p></li><li><p>Prodhuar në kapacitetet tona prodhuese në BE</p></li><li><p>Sasi për 90 ditë</p></li></ul><p><strong>Suplement ushqimor.</strong></p><p>Kompleks i plotë multivitaminash dhe multimineralesh në një kapsulë. I formuluar posaçërisht për persona fizikisht aktivë dhe për ata me stil jetese dinamik.</p><p>Ky produkt është një suplement ushqimor gjithëpërfshirës që <strong>mbështet energjinë, funksionin e sistemit imunitar dhe vitalitetin e përgjithshëm.</strong> Dozat e larta të <strong>vitaminave të grupit B</strong> kontribuojnë në metabolizmin normal energjetik, funksionimin normal të sistemit nervor dhe uljen e lodhjes. <strong>Vitaminat C dhe D, zinku dhe seleni</strong> mbështesin funksionimin normal të sistemit imunitar, ndërsa <strong>vitaminat C dhe E dhe koenzima Q10</strong> veprojnë si antioksidantë dhe ndihmojnë në mbrojtjen e qelizave nga stresi oksidativ. <strong>Hekuri, bakri dhe acidi folik</strong> kontribuojnë në formimin normal të qelizave të kuqe të gjakut, ndërsa <strong>vitamina A dhe biotina</strong> kontribuojnë në ruajtjen e lëkurës dhe flokëve të shëndetshëm dhe të shikimit normal. Ekstraktet bimore (xhensen, portokall i hidhur), si dhe përbërjet kolinë dhe inozitol, mbështesin më tej funksionin mendor dhe mirëqenien e përgjithshme.</p><p>Te personat fizikisht aktivë, nevojat për vitamina dhe minerale mund të jenë më të mëdha, dhe mungesa e tyre mund të çojë në dobësim të sistemit imunitar, ulje të forcës dhe motivim më të ulët. Nëse mungesa nuk vërehet për një kohë më të gjatë, mund të ketë pasoja më serioze, si performancë më e dobët, rraskapitje dhe metabolizëm më i ngadaltë.</p><p>Nëse ushqyerja nuk siguron mjaftueshëm vitamina, minerale dhe antioksidantë, suplementet ushqimore mund të ndihmojnë në plotësimin e nevojave për këto mikronutrientë, sidomos kur nuk konsumojmë ushqim mjaftueshëm të larmishëm, fruta, perime dhe burime të tjera ushqyese.</p><p>Battery COMPLETE VIT&amp;MIN është zhvilluar për ta plotësuar ushqyerjen tuaj me vitaminat dhe mineralet esenciale që i nevojiten organizmit për funksionim normal.</p><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li><p>Përbërës të kontrolluar, pa aditivë të panevojshëm.</p></li><li><p>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 90 kapsula</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 kapsulë me një gotë ujë gjatë drekës. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 1058;

-- Product_Id: 1089 (BATTERY CREATINE (со вкус))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY CREATINE (me shije)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Kreatinë me shije</li><li>Rrit performancën fizike</li><li>Një nga suplementet ushqimore më të njohura mes sportistëve</li><li>4 shije të shkëlqyera frutash</li><li><strong>Prodhuar në kapacitetet tona prodhuese në BE</strong></li></ul><p><strong>Kreatinë premium, tani në variante të shijshme frutash!</strong></p><p>Kërkoni një kreatinë që kombinon efikasitetin, cilësinë dhe shijen e shkëlqyer? Battery Creatine është zgjedhje e shkëlqyer për këdo që dëshiron të përmirësojë stërvitjet dhe rezultatet e veta – në mënyrë të sigurt, të besueshme dhe të shijshme!</p><p><strong>PËRFITIMET KRYESORE:</strong></p><ul><li><strong>EFIKASITET I PROVUAR SHKENCËRISHT</strong> – Kreatina rrit performancën fizike në aktivitete të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë* (efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë).</li><li><strong>TANI EDHE NË VERSION ME SHIJE</strong> – shijojeni pijen tuaj pa kompromis.</li><li><strong>TRETSHMËRI E SHKËLQYER</strong> – pa kokrriza dhe pa mundim.</li><li><strong>I BESUESHËM DHE I SIGURT PËR PËRDORIM</strong> – i përshtatshëm si për fillestarët ashtu edhe për sportistët e avancuar.</li><li><strong>100% KREATINË MONOHIDRAT E PASTËR E MIKRONIZUAR</strong> – cilësi e lartë dhe thithje optimale.</li><li><strong>PRODHUAR NË BE</strong> – Kreatina e re prodhohet në kapacitetet tona prodhuese në BE, sipas standardeve të larta të cilësisë dhe sigurisë, nga përbërës të kontrolluar dhe pa aditivë të panevojshëm.</li></ul><p><strong>Dëshironi më shumë energji, më shumë forcë dhe rezultate më të mira?</strong></p><p><strong>Zgjidhni Battery Creatine – mbështetja juaj e sigurt për çdo stërvitje!</strong></p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 g</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse e plotë (4,2 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Marrja e rekomanduar ditore është 1 porcion. Përdorni peshore për sasinë e saktë. Pijeni 20 minuta para stërvitjes. Në ditët kur nuk stërviteni, pijeni në mëngjes me stomak bosh. Sasia maksimale ditore është 1 porcion. Produkti është i destinuar për të rriturit që kryejnë ushtrime me intensitet të lartë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 250 ml ujë të vakët.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1089;

-- Product_Id: 1092 (BATTERY CREATINE, 500g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY CREATINE, 500g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>100% kreatinë e pastër</li><li>Pa shije</li><li>Rrit performancën fizike</li><li>Një nga suplementet ushqimore më të njohura mes sportistëve</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Kreatinë pluhur. Suplement ushqimor. Pa shije.</strong></p><p>Battery Creatine përbëhet nga 100% kreatinë e pastër, një nga suplementet ushqimore më të njohura mes sportistëve. Një nga sfidat më të mëdha me të cilat përballemi gjatë stërvitjes është pakësimi i rezervave tona të energjisë, gjë që mund ta kufizojë performancën. Kreatina rrit performancën fizike në aktivitete të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë (efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë).</p><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të kontrolluar, pa aditivë të panevojshëm.</li><li>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse e plotë (3,4 g). Përdorni peshore për sasinë e saktë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pijeni 20 minuta para stërvitjes. Në ditët kur nuk stërviteni, pijeni në mëngjes me stomak bosh. Sasia maksimale ditore është 1 porcion. Produkti është i destinuar për të rriturit që kryejnë ushtrime me intensitet të lartë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 250 ml ujë të vakët.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1092;

-- Product_Id: 1093 (BATTERY D3 + K2)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY D3 + K2' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Kombinim sinergjik i vitaminës D3 me biodisponueshmëri të lartë dhe vitaminës K2 të qëndrueshme</li><li>Mbështet sistemin imunitar, shëndetin e kockave dhe dhëmbëve, funksionin e muskujve dhe vitalitetin e përgjithshëm</li><li>Me vaj ulliri natyral për thithje më të mirë</li><li>Suplement ideal në periudha me ekspozim më të ulët ndaj diellit</li><li>I përshtatshëm për përdorim të përditshëm afatgjatë</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Suplement ushqimor.</strong></p><p><strong>Vitamina D3 + K2 – kombinim i fuqishëm për kockat, sistemin imunitar dhe mirëqenien e përgjithshme</strong></p><p>Mbështeteni organizmin tuaj me dy vitamina kyçe në një kapsulë!</p><p>Formula jonë kombinon vitaminën D3 me biodisponueshmëri të lartë (2000 IU) dhe një formë natyrale të vitaminës K2 (MK-7, 120 µg) – sinergji ideale për vitalitet të përditshëm.</p><p><strong>Pse vitamina D3?</strong></p><p>Vitamina D3 ka rol të rëndësishëm në:</p><ul><li>funksionimin normal të sistemit imunitar,</li><li>ruajtjen e kockave dhe dhëmbëve të shëndetshëm,</li><li>funksionin normal të muskujve,</li><li>thithjen dhe shfrytëzimin e kalciumit dhe fosforit.</li></ul><p>D3 është forma e vitaminës D që organizmi e njeh dhe e përdor lehtë, prandaj është zgjedhje e shkëlqyer për suplementim të përditshëm – sidomos në vjeshtë dhe dimër, kur ekspozimi ndaj diellit është më i ulët.</p><p><strong>Pse shtuam vitaminën K2?</strong></p><p>Vitamina K2, sidomos në formën MK-7, kontribuon në:</p><ul><li>ruajtjen e kockave normale,</li><li>transportin e duhur të kalciumit në organizëm.</li></ul><p>K2 dhe D3 veprojnë në sinergji – D3 ndihmon në thithjen e kalciumit, ndërsa K2 ndihmon në shpërndarjen e tij të duhur drejt indeve ku organizmit i nevojitet. Të dy vitaminat janë kombinuar në një kapsulë të butë me vaj ulliri, gjë që përmirëson më tej thithjen e vitaminave të tretshme në yndyrë.</p><p><strong>Përparësitë e produktit tonë:</strong></p><ul><li>Dozë e lartë e D3 – 2000 IU për mbështetje optimale ditore</li><li>Formë e qëndrueshme e K2 (menakinon-7) – 120 µg për efikasitet maksimal</li><li>Biodisponueshmëri e lartë</li><li>I përshtatshëm për përdorim të përditshëm</li><li>Pa ngjyrues artificialë dhe aditivë të panevojshëm</li></ul><p><strong>Për kë është i destinuar produkti?</strong></p><p>Vitamina D3 + K2 është zgjedhje e shkëlqyer për këdo që dëshiron të:</p><ul><li>mbështesë sistemin imunitar,</li><li>ruajë kocka të forta dhe dhëmbë të shëndetshëm,</li><li>sigurojë shfrytëzim optimal të kalciumit,</li><li>plotësojë ushqyerjen në periudha me ekspozim më të ulët ndaj diellit,</li><li>zgjedhë një kombinim që vepron në mënyrë sinergjike dhe gjithëpërfshirëse.</li></ul><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të kontrolluar, pa aditivë të panevojshëm.</li><li>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><em>Rekomandohen ushqyerja e larmishme dhe e ekuilibruar dhe stili i shëndetshëm i jetesës.</em></p><p><strong>Sasia neto:</strong> 120 kapsula</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 kapsulë me një gotë ujë pas vaktit. Paralajmërime: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe një stil të shëndetshëm jetese. Mbajeni larg fëmijëve të vegjël.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Ruajtja: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1093;

-- Product_Id: 1094 (BATTERY EXTREME BURN)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY EXTREME BURN' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>&nbsp;Provoni djegësin tonë më të ri të yndyrës!<p>Kjo <strong>formulë e jashtëzakonshme bazohet në L-karnitinë, çaj jeshil, piper kajen, kafeinë dhe niacinë</strong> dhe është krijuar për të mbështetur <strong>mirëqenien tuaj të përgjithshme</strong>, <strong>energjinë</strong> dhe <strong>uljen e peshës trupore.</strong></p><p>Niacina (vitamina B3) kontribuon në metabolizmin normal energjetik dhe në uljen e lodhjes dhe rraskapitjes, ndërsa piperi kajen kontribuon në uljen e peshës trupore.</p><p>Një paketim përmban 60 kapsula, mjaftueshëm për <strong>15 ditë përdorim intensiv.</strong></p><p><strong>MUND TË POROSITNI FURNIZIM MUJOR ME ÇMIM TË ULUR KËTU!</strong></p><p><strong>Suplement ushqimor me ekstrakte bimore dhe niacinë në formë kapsulash.</strong> <em>Përmban kafeinë. Nuk rekomandohet për fëmijë ose gra shtatzëna (përmbajtja e kafeinës: 400 mg/4 kapsula).</em></p><p><strong>PËRFITIMET KRYESORE:</strong></p><ul><li>Ndihmon trupin të përdorë yndyrën si burim energjie, duke mbështetur qëllimet për uljen e peshës trupore.</li><li><strong>Përshpejton metabolizmin:</strong> nxit termogjenezën dhe një metabolizëm më të shpejtë.</li><li><strong>Rrit energjinë:</strong> siguron energji të zgjatur gjatë gjithë ditës, duke kontribuar në më shumë aktivitet dhe vigjilencë.</li><li><strong>Përmirëson përqendrimin:</strong> ndihmon në përmirësimin e përqendrimit mendor gjatë stërvitjeve me intensitet të lartë.</li><li>Mbështet proceset natyrore të trupit për djegien e yndyrës.</li></ul><p><strong>PËRBËRËS TË NJOHUR DHE TË PROVUAR:</strong></p><ul><li><strong>L-karnitinë</strong></li></ul><p>L-karnitina është derivat i një aminoacidi që ka rol të rëndësishëm në metabolizmin e yndyrave, duke ndihmuar në transportin e acideve yndyrore drejt mitokondrive, ku përdoren për prodhimin e energjisë. Ndihmon në djegien e yndyrës, sidomos gjatë aktivitetit fizik, gjë që mund t''ju ndihmojë t''i arrini më shpejt qëllimet për uljen e peshës.</p><ul><li><strong>Ekstrakt i çajit jeshil (përmban EGCG = (-)-epigalokatekinë-3-galat)</strong></li></ul><p>Ekstrakti i çajit jeshil përmban antioksidantë të fuqishëm të quajtur katekina, sidomos epigalokatekinë galat (EGCG), të cilat mund të përshpejtojnë termogjenezën dhe oksidimin e yndyrave. Mbështet djegien e yndyrës dhe uljen e peshës trupore, ndërsa njëkohësisht kontribuon në mirëqenien e përgjithshme falë vetive antioksiduese.</p><ul><li><strong>Kafeinë</strong></li></ul><p>Kafeina është stimulues i fortë që rrit energjinë dhe termogjenezën. Rrit vigjilencën, përmirëson performancën gjatë stërvitjes dhe kështu ndihmon në rritjen e harxhimit të kalorive gjatë ditës.</p><ul><li><strong>Niacinë (vitamina B3)</strong></li></ul><p>Niacina kontribuon në metabolizmin normal energjetik dhe në uljen e lodhjes dhe rraskapitjes.</p><ul><li><strong>MaxiTherm® SD</strong></li></ul><p>MaxiTherm® SD është ekstrakt i piperit kajen (spec djegës), i standardizuar në 2,0% kapsaicinoide, të cilat janë përgjegjëse për djegësinë e frutit. Është i njohur për vetitë termogjene dhe përdoret tradicionalisht për efektin e lidhur me uljen e peshës trupore, si dhe për vetitë antioksiduese dhe anti-inflamatore.</p><p>BATTERY EXTREME BURN përshpejton procesin e djegies së yndyrës në trup duke rritur termogjenezën (prodhimin e nxehtësisë në trup) dhe duke përshpejtuar metabolizmin e yndyrave për prodhimin e energjisë. Me L-karnitinën, trupi është gati të përdorë yndyrën si burim energjie, ndërsa ekstrakti i çajit jeshil dhe kafeina sigurojnë nxitje shtesë energjie për stërvitje. Niacina mbështet funksionimin normal të sistemit nervor dhe funksionin psikologjik, ndërsa njëkohësisht kontribuon në uljen e lodhjes dhe rraskapitjes gjatë procesit të uljes së peshës.</p><p><strong>IDEAL PËR:</strong></p><ul><li>Personat që duan të përshpejtojnë djegien e yndyrës.</li><li>Personat që duan më shumë energji dhe performancë më të mirë në stërvitje.</li><li>Këdo që kërkon një suplement ushqimor natyral për djegien e yndyrës dhe mbështetje në kontrollin e peshës trupore.</li></ul><p><strong>PSE TË ZGJIDHNI BATTERY EXTREME BURN?</strong></p><ul><li><strong>Përbërës natyralë:</strong> pa mbushës artificialë dhe aditivë të panevojshëm. I përshtatshëm për veganë dhe vegjetarianë.</li><li><strong>Përbërës të studiuar shkencërisht:</strong> përdorim përbërës natyralë me cilësi të lartë, të mbështetur nga kërkime shkencore, për të krijuar një formulë të sigurt dhe efektive për djegien e yndyrës.</li><li><strong>Prodhuar në një objekt prodhues të certifikuar GMP.</strong></li><li><strong>I lehtë për t''u përdorur:</strong> forma praktike e kapsulave mundëson përfshirje të lehtë në rutinën e përditshme.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 60 kapsula</p></li></ul>"]' ELSE DescriptionAl END,
    NutritionValuesIngredientsDescriptionAl = CASE WHEN ISNULL(NutritionValuesIngredientsDescriptionAl, N'') = N'' THEN N'.' ELSE NutritionValuesIngredientsDescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 kapsula.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion pas mëngjesit dhe 1 porcion pas drekës, me një gotë ujë. PARALAJMËRIM: Përmban kafeinë. Nuk rekomandohet për fëmijë ose gra shtatzëna (përmbajtja e kafeinës: 400 mg/4 kapsula). Përmban 117–124,8 mg EGCG për dozë ditore (4 kapsula). Nuk duhet të konsumohen 800 mg ose më shumë (-)-epigalokatekinë-3-galat (EGCG) në ditë. Mos e konsumoni nëse konsumoni produkte të tjera që përmbajnë çaj jeshil në të njëjtën ditë. Nuk duhet të konsumohet nga gratë shtatzëna ose që ushqejnë me gji dhe nga fëmijët nën 18 vjeç. Nuk duhet të konsumohet me stomak bosh.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1094;

-- Product_Id: 1095 (BATTERY GLUCOSAMINE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY GLUCOSAMINE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Suplement ushqimor me glukozaminë sulfat</li><li>497,3 mg glukozaminë për porcion</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Kapsula me glukozaminë sulfat. Suplement ushqimor.</strong></p><p>Glukozamina është një amino-sheqer që sintetizohet nga glukoza dhe glutamina. Përdoret në biosintezën e proteoglikaneve dhe glikozaminoglikaneve, të cilat janë përbërës të kërcit. Mungesa e proteoglikaneve mund të çojë në degjenerim të kërcit të kyçeve.</p><ul><li>497,3 mg glukozaminë për porcion</li></ul><p>Te personat më të moshuar, glukozamina rekomandohet për përdorim në osteoartrit dhe artrit reumatoid, ndërsa te personat më të rinj destinohet kryesisht për mbështetjen e kërcit gjatë aktiviteteve sportive ose aktiviteteve të tjera që krijojnë stres më të madh mbi kyçet.</p><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të kontrolluar, pa aditivë të panevojshëm.</li><li>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><strong>Sasia neto:</strong> 90 kapsula</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza e rekomanduar ditore: 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 kapsulë me një gotë ujë gjatë vaktit. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1095;

-- Product_Id: 1096 (BATTERY GLUTAMINE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY GLUTAMINE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>L-glutaminë pluhur</li><li>5000 mg L-glutaminë për porcion</li><li>Me shije</li><li>83 porcione</li></ul><p><strong>L-glutaminë pluhur. Suplement ushqimor me ëmbëlsues. Me shije.</strong></p><p>Glutamina është aminoacidi më i përhapur në organizëm. Ushtrimet intensive mund të ulin nivelet e glutaminës në trup, ndërsa suplementimi me glutaminë mund të ndihmojë në rimbushjen e tyre për performancë fizike optimale.</p><p>L-glutamina është jashtëzakonisht e njohur mes sportistëve, bodibilderëve, personave që stërviten për forcë dhe të gjithë atyre që praktikojnë aktivitete me intensitet të lartë. Bodibilderët tradicionalisht përdorin L-glutaminë gjatë përgatitjes për gara dhe gjatë dietave me marrje të kufizuar kalorish. Sportistët dhe personat që stërviten për forcë e përdorin L-glutaminën edhe si plotësim të një ushqyerjeje të shëndetshme.</p><p>L-glutamina është aminoacid që gjendet në proteinat e të gjithë organizmave të gjallë. Klasifikohet si aminoacid gjysmë-esencial ose me kusht esencial. L-glutamina është aminoacidi më i përhapur në organizëm dhe niveli i saj në plazmë është më i lartë se ai i çdo aminoacidi tjetër.</p><p>L-glutamina sintetizohet dhe ruhet kryesisht në muskujt skeletorë. Aminoacidi L-glutamat metabolizohet në L-glutaminë përmes një reaksioni të katalizuar nga enzima glutamin-sintetazë, për të cilin përveç L-glutamatit nevojiten edhe amoniak, ATP dhe magnez.</p><ul><li>5000 mg L-glutaminë për porcion</li></ul><p><strong>L-glutamina është ideale për:</strong></p><ul><li>Sportistë që marrin pjesë në aktivitete fizikisht të rënda</li><li>Persona që praktikojnë sporte me intensitet të lartë dhe duan të plotësojnë ushqyerjen e pasur me proteina, të fokusuar në ndërtimin e masës muskulore të pastër</li><li>Bodibilderë dhe sportistë që ndjekin një regjim ushqimor me pak kalori</li><li>Të gjithë sportistët që synojnë performancë fizike maksimale</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 g (83 porcione)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 3/4 lugë matëse (6 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Mund të merrni disa porcione në ditë. Përdoreni kryesisht para/gjatë dhe pas stërvitjes, si dhe para gjumit. Mos e tejkaloni dozën e rekomanduar ditore. Suplementi ushqimor nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion në 300 ml ujë ose në ndonjë lëng tjetër të preferuar dhe tundeni fuqishëm! Lëreni të qëndrojë pak kohë që të tretet sa më mirë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1096;

-- Product_Id: 1097 (BATTERY LIMITLESS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY LIMITLESS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Pre-workout me aminoacide, kreatinë, kafeinë, ekstrakte bimore dhe vitaminë B12</li><li>Kombinim i përsosur përbërësish për mbështetje gjatë stërvitjeve intensive dhe të rënda</li><li>Në dy shije të shkëlqyera: Citrus Mix dhe Çaj jeshil - Luleshtrydhe</li><li>Paketim i ri praktik në qeska</li></ul><p><strong>Suplement ushqimor me ëmbëlsues. Pije praktike e çastit në pluhur me aminoacide, kreatinë, kafeinë, ekstrakte bimore dhe vitaminë B12.</strong> <em>Përmban kafeinë (150 mg/9 g; 300 mg/18 g). Nuk rekomandohet për fëmijë ose gra shtatzëna.</em></p><p><strong>FUQI PA KUFI DHE PËRQENDRIM MENDOR</strong></p><p>BATTERY LIMITLESS përmban një kombinim ideal përbërësish që mbulon nevojat e sportistëve gjatë stërvitjeve me intensitet të lartë. Zbuloni fuqinë e produktit që do t''ju ndihmojë të arrini rezultatet e dëshiruara!</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>Përmban L-citrulinë, kreatinë, beta-alaninë, kafeinë, ekstrakt <em>Citrus aurantium</em> dhe vitaminë B12</li><li>Vitamina B12 kontribuon në funksionimin normal të sistemit nervor, uljen e lodhjes dhe rraskapitjes, funksionin normal psikologjik, funksionimin normal të sistemit imunitar dhe formimin normal të qelizave të kuqe të gjakut.</li><li>Produkti është i destinuar për sportistë dhe të rritur të tjerë fizikisht aktivë</li><li>I disponueshëm në dy shije të shkëlqyera: Citrus Mix dhe Çaj jeshil - Luleshtrydhe</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 18 g / 14 x 18 g</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Për personat me peshë trupore deri në 75 kg ose sportistët e ndjeshëm ndaj stimuluesve, madhësia e porcionit është 9 g. Për personat me peshë trupore mbi 75 kg ose sportistët me përvojë, madhësia e porcionit është 18 g.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 30 minuta para stërvitjes. PARALAJMËRIM: Përmban kafeinë (150 mg/9 g; 300 mg/18 g). Nuk rekomandohet për fëmijë ose gra shtatzëna. Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni porcionin prej 9 g në 300 ml ujë dhe porcionin prej 18 g në 600 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1097;

-- Product_Id: 1104 (BATTERY REBEL BCAA ADVANCED)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY REBEL BCAA ADVANCED' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Aminoacide BCAA në raport 2:1:1</li><li>Me L-glutaminë, L-taurinë dhe citrulinë malat të shtuar</li><li>Mbështetje për performancë sportive më të mirë dhe rritje të muskujve</li><li>Më pak dhimbje muskulore dhe lodhje</li><li>Rikuperim më i shpejtë i muskujve</li><li>27 porcione</li></ul><p><strong>Suplement ushqimor me ëmbëlsues. Kompleks aminoacidesh me zinxhir të degëzuar (BCAA) me cilësi të lartë, i pasuruar me L-glutaminë, taurinë dhe citrulinë malat. I formuluar posaçërisht për sportistë dhe persona fizikisht aktivë.</strong></p><p>BCAA janë aminoacidet esenciale leucinë, izoleucinë dhe valinë, të njohura në botën e sportit sepse mund të ndihmojnë në uljen e dhimbjes muskulore dhe lodhjes nga ushtrimet, të shkurtojnë kohën e rikuperimit, të ndihmojnë në parandalimin e zbërthimit të muskujve dhe të mbështesin rritjen e masës muskulore.</p><p>BCAA mund të shërbejnë edhe si burim energjie për muskujt gjatë stërvitjes, gjë që i bën <strong>një suplement ushqimor të shkëlqyer dhe të gjithanshëm.</strong> Nëse qëllimet tuaja të fitnesit janë <strong>ndërtimi i masës muskulore</strong> dhe <strong>përmirësimi i performancës</strong>, ky produkt është <strong>një shtesë e shkëlqyer në rutinën tuaj të stërvitjes.</strong></p><p>REBEL BCAA kombinon raportin e provuar 2:1:1 të aminoacideve me zinxhir të degëzuar (BCAA) me përbërës shtesë kyç për performancën si <strong>L-glutaminë</strong>, <strong>L-taurinë</strong> dhe <strong>citrulinë malat.</strong></p><p>Çdo porcion REBEL BCAA përmban:</p><ul><li>5 g BCAA (L-leucinë, L-izoleucinë dhe L-valinë në raport 2:1:1)</li><li>3 g L-glutaminë</li><li>2 g L-taurinë</li><li>500 mg citrulinë malat</li></ul><p>Mund të konsumohet para, gjatë ose pas aktivitetit fizik për të mbështetur muskujt dhe performancën fizike.</p><p><strong>Sasia neto:</strong> 380 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (14 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pijeni para dhe gjatë ushtrimeve ose gjatë ditës ndërmjet vakteve. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 400–500 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 1104;

-- Product_Id: 2104 (BATTERY LIMITLESS, 360g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY LIMITLESS, 360g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Pre-workout me aminoacide, kreatinë, kafeinë, ekstrakte bimore dhe vitaminë B12</li><li>Kombinim i përsosur përbërësish për mbështetje gjatë stërvitjeve intensive dhe të rënda</li><li>Në dy shije të shkëlqyera: Citrus Mix dhe Çaj jeshil - Luleshtrydhe</li><li>Paketimi përmban deri në 40 porcione</li></ul><p><strong>Suplement ushqimor me ëmbëlsues. Pije e çastit në pluhur me aminoacide, kreatinë, kafeinë, ekstrakte bimore dhe vitaminë B12.</strong> <em>Përmban kafeinë (150 mg/9 g; 300 mg/18 g). Nuk rekomandohet për fëmijë ose gra shtatzëna.</em></p><p><strong>FUQI PA KUFI DHE PËRQENDRIM MENDOR!</strong></p><p>Ju prezantojmë një bombë të re energjie në kategorinë e produkteve pre-workout!</p><p>BATTERY LIMITLESS përmban kombinimin e përsosur të përbërësve që mbulon nevojat e sportistëve gjatë stërvitjeve me intensitet të lartë. Zbuloni fuqinë e produktit që do t''ju ndihmojë të arrini rezultatet e dëshiruara!</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>Përmban L-citrulinë, kreatinë, beta-alaninë, kafeinë, ekstrakt <em>Citrus aurantium</em> dhe vitaminë B12</li><li>Vitamina B12 kontribuon në funksionimin normal të sistemit nervor, uljen e lodhjes dhe rraskapitjes, funksionin normal psikologjik, funksionimin normal të sistemit imunitar dhe formimin normal të qelizave të kuqe të gjakut.</li><li>Produkti është i destinuar për sportistë dhe të rritur të tjerë fizikisht aktivë</li><li>I disponueshëm në dy shije të shkëlqyera: Citrus Mix dhe Çaj jeshil - Luleshtrydhe</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 360 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Për personat me peshë trupore deri në 75 kg ose sportistët e ndjeshëm ndaj stimuluesve, madhësia e porcionit është 9 g (1 lugë matëse e plotë). Për personat me peshë trupore mbi 75 kg ose sportistët me përvojë, madhësia e porcionit është 18 g (2 lugë matëse të plota).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 30 minuta para stërvitjes. PARALAJMËRIM: Përmban kafeinë (150 mg/9 g; 300 mg/18 g). Nuk rekomandohet për fëmijë ose gra shtatzëna. Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni porcionin prej 9 g në 300 ml ujë dhe porcionin prej 18 g në 600 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2104;

-- Product_Id: 2105 (BATTERY MALTODEXTRIN, 2000g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY MALTODEXTRIN, 2000g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Karbohidrate me indeks glikemik (GI) të lartë</li><li>Burim i shkëlqyer energjie</li><li>Rimbush shpejt rezervat e glikogjenit</li><li>I përshtatshëm për veganët</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Maltodekstrinë pluhur. Suplement ushqimor.</strong></p><p>Battery Maltodextrin është i destinuar për sportistë dhe persona aktivë që duan të rrisin marrjen e karbohidrateve. Produkti prodhohet në BE dhe përmban 100% karbohidrate komplekse të pastra me zinxhir të gjatë, pa aditivë dhe mbushës të panevojshëm.</p><p>Maltodekstrina është burim i shkëlqyer energjie të disponueshme shpejt. Edhe pse është karbohidrat kompleks, ka indeks glikemik të lartë (GI 110), që do të thotë se e rrit shpejt nivelin e sheqerit në gjak dhe siguron një rritje të shpejtë energjie.</p><p>Maltodekstrina është ideale kur nevojitet një burim energjie i shpejtë dhe lehtësisht i disponueshëm, duke e ndihmuar organizmin të rimbushë shpejt rezervat e harxhuara të glikogjenit, për shembull pas aktivitetit fizik ose stërvitjes. Pas stërvitjes mund të kombinohet me Battery Complete Whey, Battery Creatine dhe Battery BCAA.</p><p>Maltodekstrina bën pjesë në grupin e polisaharideve dhe më shpesh përftohet nga niseshteja e përpunuar, sidomos nga niseshteja e misrit ose e orizit. Emri i saj vjen nga fakti që përbëhet nga polimere glukoze me gjatësi të ndryshme. Ndryshe nga dekstroza, maltodekstrina nuk ka shije të ëmbël.</p><p>Battery Maltodextrin mund të përdoret si burim efektiv karbohidratesh në pije për shtimin e peshës trupore.</p><p>Përparësia kryesore e maltodekstrinës është se mund të ndihmojë në shtimin e peshës trupore, prandaj përdoret shpesh në formula të ndryshme mass gainer. Edhe pse ka indeks glikemik të lartë, vlera GI i referohet përbërësit të izoluar. Kur kombinohet me proteina dhe yndyrna, përgjigjja glikemike e përgjithshme e vaktit mund të ndryshojë ndjeshëm. Në formulat mass gainer, maltodekstrina shërben si burim praktik karbohidratesh dhe kalorish në kombinim me proteina dhe lëndë të tjera ushqyese.</p><p>Një nga mënyrat më praktike dhe më të leverdishme për të shtuar peshë është të përgatitni vetë weight gainer-in tuaj. Nëse ky është qëllimi juaj, Battery Maltodextrin është zgjedhje e shkëlqyer. Siguron kalori shtesë, thithet shpejt dhe tretet lehtë.</p><p>Falë të gjitha këtyre karakteristikave, Battery Maltodextrin është zgjedhje e shkëlqyer me raport të shkëlqyer çmim-cilësi.</p><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të kontrolluar, pa aditivë të panevojshëm.</li><li>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 2000 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse (40 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pijeni para, gjatë (1 lugë matëse në orë) ose pas stërvitjes, sipas nevojave tuaja ushqyese. Sasia e rekomanduar ditore: 1–3 porcione (40 g – 120 g). Ky produkt është i destinuar për të rritur të stërvitur që kryejnë ushtrime fizike me intensitet të lartë dhe kohëzgjatje të gjatë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni një porcion në 400 ml ujë ose në një shejk proteinik.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2105;

-- Product_Id: 2106 (BATTERY OMEGA 3)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY OMEGA 3' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Vaj peshku shumë i koncentruar</li><li>Mbështetje për shëndetin e zemrës, trurit dhe shikimit</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>BATTERY OMEGA 3</strong></p><p><strong>Kapsula me acide yndyrore omega-3. Suplement ushqimor.</strong></p><p>Battery Omega 3 dallohet për përmbajtjen e lartë të acideve yndyrore omega-3, të pasura me acidet yndyrore esenciale EPA (acid eikozapentaenoik), DHA (acid dokozaheksaenoik) dhe DPA (acid dokozapentaenoik).</p><p>Acidet yndyrore të pangopura EPA, DHA dhe DPA janë acide yndyrore omega-3 që kanë rol të rëndësishëm në mbështetjen e sistemit kardiovaskular, funksionit njohës dhe shikimit, prandaj është e rëndësishme që të jenë rregullisht të pranishme në ushqyerje.</p><p>Acidet yndyrore të shumëpangopura janë esenciale dhe gjenden te peshku. Organizmi nuk mund t''i prodhojë vetë në sasi të mjaftueshme, prandaj duhet të merren përmes ushqyerjes. Shumë njerëz marrin çdo ditë shumë pak acide yndyrore omega-3, për shembull për shkak të konsumit të pamjaftueshëm të peshkut. Në raste të tilla, suplementet ushqimore që përmbajnë këtë lloj acidesh yndyrore mund të jenë zgjedhje praktike.</p><ul><li>EPA dhe DHA kontribuojnë në funksionimin normal të zemrës</li><li>DHA kontribuon në ruajtjen e funksionit normal të trurit dhe të shikimit normal</li></ul><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të kontrolluar, pa aditivë të panevojshëm.</li><li>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 90 kapsula</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza e rekomanduar ditore: 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 kapsulë me një gotë ujë gjatë vaktit. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2106;

-- Product_Id: 2113 (BATTERY REBEL CREATINE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY REBEL CREATINE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Kreatinë monohidrat për rritjen e fuqisë, forcës dhe performancës sportive**</li><li>4,5 g kreatinë për porcion**</li><li>Pa shije</li><li>60 porcione</li></ul><p><strong>Suplement ushqimor. 100% kreatinë monohidrat.</strong></p><p>REBEL CREATINE është suplement ushqimor i sigurt dhe efektiv për <strong>përmirësimin e performancës në ushtrime me intensitet të lartë</strong>, sidomos kur kombinohet me stërvitje me rezistencë, gjë që e bën <strong>një nga suplementet më të njohura</strong> për mbështetjen e stërvitjes.</p><p>Suplementimi me kreatinë rrit rezervat e fosfokreatinës në muskuj gjatë aktiviteteve me intensitet të lartë, duke mundësuar prodhimin e më shumë ATP, gjë që kontribuon në <strong>rritjen e masës muskulore të pastër dhe përmirësimin e fuqisë dhe forcës</strong>.** Fosfokreatina, e njohur edhe si kreatinë fosfat, është një përbërje organike natyrale që ndihmon në tkurrjet muskulore. Gjendet në indin muskulor dhe mundëson shpërthime të shkurtra energjie maksimale që zgjasin rreth 5 deri në 6 sekonda.</p><p>Shumë bodibilderë dhe sportistë përdorin kreatinë për të përmirësuar <strong>performancën sportive</strong>. Suplementimi me kreatinë mund të jetë i dobishëm edhe për personat më të moshuar, te të cilët rezervat e fosfokreatinës ulen me moshën.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë.</strong></p><p><strong>Sasia neto:</strong> 300 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 lugë matëse e plotë (5 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion para stërvitjes. Në ditët kur nuk stërviteni, merrni 1 porcion në mëngjes me stomak bosh. PARALAJMËRIM: Është e mundur rritja e peshës trupore. Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 250 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2113;

-- Product_Id: 2114 (BATTERY REBEL MASS GAINER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY REBEL MASS GAINER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Shejk praktik dhe i shijshëm për marrje kalorish cilësore</li><li>Kombinim proteinash dhe karbohidratesh në raport 1:3</li><li>Vlerë e lartë kalorike për shtim më të shpejtë të masës trupore</li><li>I pasuruar me L-glutaminë dhe kopër greku</li><li>Raport i shkëlqyer çmim / performancë / cilësi</li><li>30 porcione</li></ul><p><strong>Suplement ushqimor me sheqer dhe ëmbëlsues.</strong></p><p>Për ndërtimin e masës muskulore, trupit i nevojiten kalori cilësore që përfshijnë një kombinim karbohidratesh, proteinash dhe yndyrnash. REBEL MASS GAINER është një <strong>përzierje lëndësh ushqyese</strong> e pasur me kalori, e destinuar për sportistë dhe persona të tjerë aktivë me qëllim <strong>rritjen e masës muskulore, përmirësimin e performancës fizike dhe rikuperimin më të shpejtë.</strong> Me një mass gainer mund ta rritni shpejt dhe në mënyrë efektive marrjen ditore të kalorive.</p><p>Formula kombinon <strong>tre burime proteinash me cilësi të lartë</strong> (koncentrat proteine whey, izolat proteine whey dhe kazeinë) dhe <strong>një përzierje prej pesë llojesh karbohidratesh</strong>, të pasuruar me <strong>L-glutaminë</strong> dhe ekstrakt <strong>kopre greku</strong>. Raporti i karbohidrateve me proteinat në REBEL MASS GAINER është 3:1.</p><p><strong>ROLI I LËNDËVE USHQYESE</strong></p><p><strong>Karbohidratet</strong> janë <strong>burimi kryesor i energjisë</strong> për të rriturit aktivë dhe sportistët dhe përfshijnë sheqerna të thjeshta dhe karbohidrate më komplekse. Sheqernat e thjeshta treten lehtë dhe thithen shpejt përmes murit të zorrëve në qarkullimin e gjakut. Karbohidratet komplekse kanë nevojë për më shumë kohë për t''u zbërthyer dhe shfrytëzuar dhe kanë ndikim më të qëndrueshëm në nivelin e glukozës në gjak. Në REBEL MASS GAINER <strong>karbohidratet e thjeshta</strong> vijnë nga <strong>maltodekstrina, dekstroza dhe fruktoza</strong>, ndërsa <strong>karbohidratet komplekse</strong> vijnë nga <strong>palatinoza, niseshteja e misrit dyllor dhe mielli i tërshërës</strong>. Nevojat për karbohidrate në ushqyerjen e përditshme zakonisht variojnë nga 45% deri në 65% të marrjes totale të ushqimit, në varësi të nevojave fizike, madhësisë së trupit dhe karakteristikave të stërvitjes.</p><p><strong>Proteinat</strong> janë të rëndësishme për <strong>rritjen dhe rikuperimin e muskujve</strong> te personat aktivë dhe sportistët. Marrja e mjaftueshme e proteinave ndihmon në ruajtjen e një bilanci pozitiv të azotit në organizëm, gjë që është e rëndësishme për indin muskulor.</p><p>REBEL MASS GAINER siguron përmbajtje të lartë proteinash, të cilat kontribuojnë në rinovimin dhe rritjen e muskujve, së bashku me karbohidratet që shërbejnë si burim kryesor energjie dhe ndihmojnë në procesin e rikuperimit.</p><p>I disponueshëm me shije çokollate.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 3000 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (100 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1–2 porcione në ditë. Merrini para dhe/ose pas stërvitjes. Ky produkt nuk është zëvendësim vakti, përdoreni vetëm si suplement ushqimor. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion në 400 ml ujë, qumësht ose lëng tjetër.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2114;

-- Product_Id: 2115 (BATTERY REBEL PWO)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY REBEL PWO' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Pre-workout pluhur me aminoacide, kafeinë dhe ekstrakte bimore</li><li>Me citrulinë, beta-alaninë, tirozinë dhe kolinë</li><li>Fuqi ekstreme</li><li>Shije ekzotike mango</li></ul><p><strong>Suplement ushqimor me ëmbëlsues. Pije e çastit në pluhur me aminoacide, kafeinë dhe ekstrakte bimore.</strong> <em>Përmban kafeinë (150 mg/7,5 g; 300 mg/15 g). Nuk rekomandohet për fëmijë ose gra shtatzëna.</em></p><p>Çdo porcion prej 15 g përmban:</p><ul><li>5 g citrulinë malat</li><li>3 g beta-alaninë</li><li>1 g tirozinë</li><li>500 mg kolinë bitartrat</li></ul><p><strong>Sasia neto:</strong> 300 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Deri në 75 kg peshë trupore dhe për personat e ndjeshëm ndaj stimuluesve: Madhësia e porcionit është 7,5 g (1/2 lugë matëse). Mbi 75 kg peshë trupore dhe për sportistët me përvojë: Madhësia e porcionit është 15 g (1 lugë matëse).
Konsumoni 15–30 minuta para stërvitjes. Mos e përdorni 4 orë para gjumit.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, larg nxehtësisë dhe dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 7,5 g (1/2 lugë matëse) me 200 ml dhe 15 g (1 lugë matëse) me 400 ml.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2115;

-- Product_Id: 2117 (BATTERY ZINC)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY ZINC' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Rregullon funksionimin e sistemit imunitar</li><li>Merr pjesë në metabolizmin e makronutrientëve</li><li>Mbron qelizat nga stresi oksidativ</li><li>Kontribuon në ruajtjen e lëkurës, flokëve, thonjve dhe kockave të shëndetshme</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Suplement ushqimor me zink në formë tabletash.</strong></p><p>Zinku është mineral esencial që gjendet pothuajse në çdo qelizë të organizmit të njeriut dhe merr pjesë në më shumë se 300 reaksione enzimatike.</p><p>Zinku kontribuon në:</p><ul><li>sintezën normale të ADN-së</li><li>metabolizmin normal të karbohidrateve, lipideve, aminoacideve, acideve yndyrore dhe vitaminës A</li><li>funksionin normal njohës</li><li>pjellorinë dhe riprodhimin normal</li><li>sintezën normale të proteinave</li><li>ruajtjen e nivelit normal të testosteronit në gjak</li><li>ruajtjen e kockave, flokëve, thonjve dhe lëkurës normale</li><li>funksionimin normal të sistemit imunitar</li><li>ruajtjen e shikimit normal</li><li>mbrojtjen e qelizave nga stresi oksidativ</li><li>procesin normal të ndarjes së qelizave</li></ul><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>Mineral esencial në gjurmë</li><li>Kontribuon në ruajtjen e nivelit normal të testosteronit në gjak</li><li>Kontribuon në ruajtjen e lëkurës normale</li><li>Mbështet funksionimin normal të sistemit imunitar</li><li>Kontribuon në mbrojtjen e qelizave nga stresi oksidativ</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 90 kapsula</p><p></p>"]' ELSE DescriptionAl END,
    NutritionValuesIngredientsAl = CASE WHEN ISNULL(NutritionValuesIngredientsAl, N'') = N'' THEN N'PËRBËRËSIT: maltodekstrinë, kapsulë (xhelatinë gjedhi, ngjyrues: oksid hekuri i verdhë), zink bisglicinat.' ELSE NutritionValuesIngredientsAl END,
    NutritionValuesIngredientsDescriptionAl = CASE WHEN ISNULL(NutritionValuesIngredientsDescriptionAl, N'') = N'' THEN N'Prodhuar në një objekt ku prodhohen produkte që përmbajnë qumësht, vezë, gluten dhe soje.' ELSE NutritionValuesIngredientsDescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 kapsulë me një gotë ujë gjatë ditës. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe një stil të shëndetshëm jetese.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Mbajeni larg fëmijëve të vegjël. RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2117;

-- Product_Id: 2118 (BATTERY ZMA)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY ZMA' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Burim i shkëlqyer zinku, magnezi dhe vitamine B6</li><li>Suplement i njohur para gjumit</li><li>Kontribuon në metabolizmin normal të proteinave</li><li>Raport i shkëlqyer çmim-cilësi</li><li>Prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Suplement ushqimor me zink, magnez dhe vitaminë B6 në formë kapsulash.</strong></p><p>Battery ZMA është formulë me cilësi të lartë me zink, magnez dhe vitaminë B6, e krijuar për të mbështetur rritjen dhe rikuperimin e muskujve. Zinku dhe magnezi janë minerale esenciale që marrin pjesë në shumë funksione të rëndësishme në organizëm, përfshirë sintezën e proteinave, funksionin e muskujve, ruajtjen e nivelit normal të testosteronit, funksionimin e sistemit imunitar dhe metabolizmin e yndyrave.</p><p><strong>PËRFITIMET KRYESORE TË BATTERY ZMA:</strong></p><ul><li>Burim i shkëlqyer zinku, magnezi dhe vitamine B6</li><li>Kontribuon në metabolizmin normal të proteinave</li><li>Raport i shkëlqyer çmim-cilësi</li><li>Suplement i njohur për përdorim para gjumit</li></ul><p><strong>KUSH DUHET TA PËRDORË BATTERY ZMA?</strong></p><p>Battery ZMA është i përshtatshëm si suplement para gjumit dhe kontribuon në ruajtjen e nivelit normal të testosteronit në gjak. Është gjithashtu zgjedhje e shkëlqyer për personat që duan të rrisin masën trupore dhe masën muskulore të pastër.</p><p>Përveç kësaj, zinku, magnezi dhe vitamina B6 marrin pjesë në funksione të shumta të rëndësishme në organizëm dhe kontribuojnë në shëndetin dhe mirëqenien e përgjithshme.</p><p><strong>I sigurt dhe me cilësi të lartë – prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të kontrolluar, pa aditivë të panevojshëm.</li><li>Prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 90 kapsula</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza e rekomanduar ditore: 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2118;

-- Product_Id: 2126 (BODY ATTACK BBQ SAUCE, 320ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BODY ATTACK BBQ SAUCE, 320ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Salcë BBQ me pak karbohidrate dhe yndyrë</li><li>0% yndyrë dhe sheqer</li><li>E përshtatshme për veganët</li></ul><p>Salca e shijshme Body Attack BBQ Sauce është ideale për të plotësuar vaktet tuaja BBQ – dhe mund ta shijoni pa ndjenjë faji, sepse nuk përmban sheqer as yndyrë. Me një porcion prej 10 ml merrni vetëm 1 kcal.</p><p><strong>KARAKTERISTIKAT KRYESORE TË PRODUKTIT:</strong></p><ul><li>Me pak yndyrë</li><li>Me pak karbohidrate</li><li>Me pak kalori</li><li>Shije e shkëlqyer</li><li>Me ëmbëlsues (sukralozë)</li><li>Përbërës pa gluten</li><li>E përshtatshme për personat me intolerancë ndaj laktozës</li><li>Produkt vegan</li></ul><p><strong>Çfarë përmban salca e shijshme American BBQ Sauce nga Body Attack?</strong></p><p>Përbërësit kryesorë janë uji, fibrat e bambusë dhe një sasi e vogël ëmbëlsuesi (sukralozë), në mënyrë që salca të mbetet me pak kalori dhe e përshtatshme për personat që kujdesen për ushqyerjen. Falë kësaj, nuk ka nevojë për përbërës të tjerë me shumë kalori si niseshteja e modifikuar dhe sheqeri.</p><p>Përbërësit e tjerë përfshijnë ngjyrues, konservues dhe, më e rëndësishmja, përbërës që përmirësojnë shijen, si uthulla e verës dhe kripa. Te salcat e tyre BBQ dhe me erëza, Body Attack i kushton vëmendje të madhe arritjes së një shijeje të plotë dhe autentike – diçka që shpesh mungon te salcat standarde me pak kalori.</p><p>Të gjithë përbërësit e përdorur janë të përshtatshëm jo vetëm për veganët, por edhe për personat me intolerancë ndaj laktozës dhe/ose glutenit.</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Tundeni mirë para përdorimit. Pas hapjes, ruajeni në frigorifer dhe përdoreni brenda një muaji.' ELSE InstructionsForUseAl END
WHERE Product_Id = 2126;

-- Product_Id: 2127 (BODY ATTACK DRESSING, 320ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BODY ATTACK DRESSING, 320ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Salcë sallate me pak karbohidrate dhe yndyrë</li><li>0% yndyrë dhe sheqer</li><li>E përshtatshme për veganët</li></ul><p>Salca e shijshme Body Attack Dressing është ideale për të pasuruar vakte të ndryshme – dhe mund ta shijoni pa ndjenjë faji, sepse nuk përmban sheqer as yndyrë. Me një porcion prej 10 ml merrni vetëm 1 kcal.</p><p><strong>KARAKTERISTIKAT KRYESORE TË PRODUKTIT:</strong></p><ul><li>Me pak yndyrë</li><li>Me pak karbohidrate</li><li>Me pak kalori</li><li>Shije e shkëlqyer</li><li>Me ëmbëlsues (sukralozë)</li><li>Përbërës pa gluten</li><li>E përshtatshme për personat me intolerancë ndaj laktozës</li><li>Produkt vegan</li></ul><p><strong>Çfarë përmban salca e shijshme Body Attack Dressing?</strong></p><p>Përbërësit kryesorë janë uji, fibrat e bambusë dhe një sasi e vogël ëmbëlsuesi (sukralozë), në mënyrë që salca të mbetet me pak kalori dhe e përshtatshme për personat që kujdesen për ushqyerjen. Falë kësaj, nuk ka nevojë për përbërës të tjerë me shumë kalori si niseshteja e modifikuar dhe sheqeri.</p><p>Përbërësit e tjerë përfshijnë ngjyrues, konservues dhe, më e rëndësishmja, përbërës që kontribuojnë në shije, si uthulla e verës dhe kripa. Te salcat e tyre për sallata, Body Attack i kushton vëmendje të madhe arritjes së një shijeje të plotë dhe të ekuilibruar – diçka që shpesh mungon te salcat standarde me pak kalori.</p><p>Të gjithë përbërësit e përdorur janë të përshtatshëm për personat me intolerancë ndaj laktozës dhe/ose glutenit.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Tundeni mirë para përdorimit. Pas hapjes, ruajeni në frigorifer dhe përdoreni brenda një muaji. E pahapur, ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseAl END
WHERE Product_Id = 2127;

-- Product_Id: 2128 (BODY ATTACK DESSERT SAUCE, 320ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BODY ATTACK DESSERT SAUCE, 320ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Salcë e shijshme për të pasuruar ëmbëlsirat tuaja</li><li>Shije e shkëlqyer</li><li>0% yndyrë dhe sheqer</li><li>Produkt vegan</li></ul><p>Body Attack Dessert Sauce me shije çokollate ose luleshtrydheje është ideale për t''u dhënë shije smoothie-ve, produkteve të qumështit, akullores, petullave, drithërave ose byrekut të ngrohtë me mollë. Përmban më pak se 0,5 g sheqer dhe 0,1 g yndyrë për 100 ml.</p><p><strong>KARAKTERISTIKAT KRYESORE TË PRODUKTIT:</strong></p><ul><li>Për pasurimin e shijes së ëmbëlsirave</li><li>Zgjedhje e shkëlqyer gjatë dietës</li><li>Ideale për ushqyerje me pak kalori, pak sheqer dhe pak yndyrë</li><li>Shije çokollate ose luleshtrydheje</li><li>Ideale për ushqyerje me pak yndyrë dhe karbohidrate</li><li>E përshtatshme për veganët</li><li>32 porcione</li></ul><p><strong>Çfarë përmban salca e shijshme Dessert Sauce nga Body Attack?</strong></p><p>Kjo salcë për ëmbëlsira siguron më së shumti 1 kcal për porcion dhe për këtë arsye ka jashtëzakonisht pak kalori.</p><p>Sportistët dhe personat që kujdesen për figurën e tyre, por duan të përdorin salca mbi produktet e qumështit, drithërat ose vaktet proteinike, mund ta shijojnë këtë salcë pa ndjenjë faji, sepse ka ndikim minimal në marrjen totale të kalorive. Edhe personat që ndjekin një regjim ushqimor shumë të rreptë mund ta përfshijnë këtë salcë në planin e tyre.</p><p>Përparësia e Body Attack Dessert Sauce nuk është vetëm përmbajtja e ulët e karbohidrateve, sheqerit dhe yndyrës, por edhe shija, ngjyra dhe konsistenca e saj. Përbërësit kryesorë janë uji, fibrat e bambusë dhe një sasi e vogël ëmbëlsuesi (sukralozë), me të cilat përmbajtja e sheqerit dhe yndyrës në këtë salcë ulet ndjeshëm.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Pas hapjes, ruajeni në frigorifer dhe përdoreni brenda një muaji.' ELSE InstructionsForUseAl END
WHERE Product_Id = 2128;

-- Product_Id: 2130 (CreGAAtine)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'CreGAAtine' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Kreatinë monohidrat + GAA = CReGAAtine</li><li>Kombinim sinergjik i dy përbërësve aktivë</li><li>Mbështetje për performancën fizike dhe mendore</li><li>Nuk shkakton mbajtje të theksuar të ujit</li><li>Mbështetje për një “pump” dhe performancë më të mirë gjatë stërvitjes</li><li>Më shumë energji dhe përqendrim gjatë gjithë ditës</li></ul><p><strong>Suplement ushqimor me kreatinë monohidrat, acid guanidinoacetik (GAA) dhe vitaminat B6, B9 dhe B12.</strong></p><p><strong>PSE CREGAATINE?</strong></p><p>CReGAAtine është formulë unike e patentuar, e bazuar në kombinimin e kreatinës monohidrat dhe paraardhësit të saj metabolik GAA – acidit guanidinoacetik.</p><p>Kombinimi është zhvilluar për të siguruar efekt sinergjik dhe për të mbështetur nivelet e kreatinës në organizëm, si dhe performancën fizike dhe mendore.</p><p>CReGAAtine është zhvilluar nga Applied Bioenergetic Lab dhe Carnomeda dhe është formulim i krijuar mbi bazën e kërkimeve shkencore.</p><p><strong>FORMULË E BAZUAR NË SHKENCË</strong></p><p>CReGAAtine është suplement ushqimor i formuluar mbi bazën e provave shkencore. Baza shkencore e CReGAAtine mbështetet nga kërkime të shumta mbi GAA dhe metabolizmin e kreatinës.</p><p><strong>FORMULIM I SHPËRBLYER</strong></p><p>CReGAAtine është formulim i sigurt dhe i patentuar dhe nuk përmban substanca dopingu. Studimi mbi efektet e kombinimit të kreatinës me paraardhësin e saj GAA është shpërblyer nga Shoqata Evropiane për Ushqyerjen Klinike dhe Metabolizmin (ESPEN).</p><p><strong>MBËSHTETJE PËR NIVELET E KREATINËS</strong></p><p>CReGAAtine është krijuar për të mbështetur nivelet e kreatinës në muskuj dhe në tru. Kombinimi i kreatinës monohidrat dhe GAA mundëson mbështetje përmes rrugëve të ndryshme metabolike për krijimin dhe shfrytëzimin e kreatinës në organizëm.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>Kreatinë monohidrat në kombinim me GAA</li><li>Mbështetje për forcën, fuqinë dhe performancën fizike</li><li>Mbështetje për energjinë mendore dhe përqendrimin</li><li>Mënyrë praktike për të plotësuar marrjen ditore të kreatinës</li><li>Me vitaminat B6, B9 dhe B12 të shtuara</li></ul></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Të rriturit: 1 qeskë 2 herë në ditë. Përmbajtja e qeskës tretet në ujë të vakët, lëng ose lëng tjetër dhe pihet menjëherë.

Shënim: suplementet ushqimore nuk mund të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar dhe një stil të shëndetshëm jetese. Mbajeni larg fëmijëve.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Paralajmërim: nuk rekomandohet për fëmijë, gra shtatzëna, gra që ushqejnë me gji, persona me insuficiencë renale dhe çrregullime si sindroma nefrotike, si dhe për ata që janë të mbindjeshëm ndaj ndonjërit prej përbërësve të preparatit. Personat në rrezik nga sëmundjet kardiovaskulare dhe renale, ata që kanë një sëmundje të diagnostikuar, që përdorin barna ose suplemente të tjera, duhet të konsultohen me mjekun ose farmacistin para përdorimit. Doza e rekomanduar ditore nuk duhet të tejkalohet.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Ruajtja: ruajeni në temperaturë deri në 25°C, të mbrojtur nga drita dhe lagështia.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2130;

-- Product_Id: 2131 (IRONMAXX 100% EAAS ZERO, 500g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'IRONMAXX 100% EAAS ZERO, 500g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Aminoacide EAA pluhur me të 8 aminoacidet esenciale</li><li>Me histidinë gjysmë-esenciale të shtuar</li><li>Mbështetje për muskujt dhe rikuperimin</li><li>Mbështetje për sistemin imunitar</li><li>Thithje e shpejtë</li><li>Pa sheqer</li></ul><p><strong>Suplement ushqimor për sportistë me aminoacide dhe ëmbëlsues.</strong></p><p><strong>Të gjitha aminoacidet esenciale plus histidinë në një produkt!</strong></p><p><strong>100% EAAs ZERO</strong> pluhur ju siguron të <strong>tetë aminoacidet esenciale + aminoacidin gjysmë-esencial histidinë</strong> në një produkt. <strong>Aminoacidet EAA pluhur</strong> janë zgjedhje e shkëlqyer për periudhat e ndërtimit të masës muskulore. Aminoacidet esenciale kontribuojnë në mbështetjen, ruajtjen dhe rikuperimin e muskujve dhe janë të përshtatshme edhe për bodibilding, stërvitje me pesha, atletikë dhe sporte qëndrueshmërie.</p><p><strong>Aminoacidet e lira proteinogjene</strong> në këtë formulë janë shpejt të disponueshme për organizmin dhe marrin pjesë në procese të rëndësishme metabolike të lidhura me sintezën e proteinave muskulore. 100% EAAs ZERO është produkt i pastër EAA pluhur me cilësinë e lartë të njohur të IronMaxx®.</p><p><strong>AMINOACIDET ESENCIALE – MBËSHTETJE PËR PERFORMANCËN TUAJ</strong></p><p>Aminoacidet EAA nuk janë të rëndësishme vetëm për proceset e lidhura me ndërtimin dhe ruajtjen e masës muskulore. Aminoacidet esenciale marrin pjesë edhe në procese të tjera të shumta metabolike, përfshirë krijimin e enzimave dhe hormoneve dhe funksionimin normal të organizmit.</p><p><strong>BCAA – AMINOACIDET E FUQISHME EAA</strong></p><p>Mes aminoacideve esenciale në këtë formulë janë edhe tre aminoacidet BCAA me zinxhir të degëzuar: L-leucinë, L-valinë dhe L-izoleucinë. Ato janë veçanërisht të njohura mes sportistëve për shkak të rolit të tyre në indin muskulor dhe sintezën e proteinave.</p><p><strong>100% EAAs ZERO</strong> nuk përmban sheqer të shtuar. Në vend të sheqerit, formula është ëmbëlsuar me sukralozë dhe glikozide natyrale steviol me origjinë bimore. Pija e përgatitur është pa sheqer.</p><p><strong>100% EAAs ZERO – MËNYRA E PËRDORIMIT</strong></p><p>Aminoacidet esenciale mund të konsumohen para stërvitjes, gjatë stërvitjes ose menjëherë pas aktivitetit fizik. Përzieni 15 g pluhur me 350 ml ujë për të përgatitur një pije freskuese me aminoacide.</p><p><strong>PËRPARËSITË KRYESORE TË 100% EAAs ZERO:</strong></p><ul><li>Aminoacide EAA pluhur me të 8 aminoacidet esenciale</li><li>Aminoacide esenciale të lira</li><li>Me histidinë gjysmë-esenciale të shtuar</li><li>Thithje e shpejtë</li><li>Mbështetje për muskujt dhe rikuperimin</li><li>Përgatitje e lehtë si shejk</li><li>Mbështetje për sistemin imunitar</li><li>Pa sheqer – i ëmbëlsuar me sukralozë dhe glikozide natyrale steviol</li></ul><p><strong>INFORMACION PËR ALERGJENËT</strong></p><p>Mund të përmbajë gjurmë LUPINE, VEZËSH, GLUTENI, QUMËSHTI dhe SOJE.</p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 lugë gjelle e mbushur (15 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Rekomandohet të përdoret para, gjatë, madje edhe pak pas stërvitjes, si shejk.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 350 ml ujë të ftohtë në shejker dhe tundeni fuqishëm për 20 sekonda.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2131;

-- Product_Id: 2134 (IRONMAXX CARNITINE PRO LIQUID)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'IRONMAXX CARNITINE PRO LIQUID' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>Me 6000 mg L-karnitinë për 100 ml</li><li>Ideal gjatë dietës</li><li>Ideal për përdorim para dhe gjatë stërvitjes</li><li>Pa yndyrë</li><li>Optimal në kombinim me aktivitet fizik të rregullt</li><li>Me vitaminë C për uljen e lodhjes dhe rraskapitjes</li></ul><p><strong>Suplement ushqimor me L-karnitinë dhe vitaminë B6, me ëmbëlsues.</strong></p><p><strong>IronMaxx® Carnitin Pro Liquid – zgjedhje e njohur mes sportistëve të nivelit të lartë!</strong></p><p>Për ata që duan të përmirësojnë formën fizike dhe mirëqenien e përgjithshme, të arrijnë definim më të mirë dhe të ndihen më mirë në trupin e tyre, nevojiten disiplinë, përkushtim dhe vazhdimësi. Carnitin Pro Liquid është suplement ushqimor që prej vitesh është i njohur mes personave që kujdesen për figurën dhe te sportistët profesionistë.</p><p>Karnitina më shpesh ofrohet në formë kapsulash, por IronMaxx® e zgjeroi linjën e saj të suksesshme Carnitin Pro me Carnitin Pro Liquid praktik. Me Carnitin Pro Liquid mund ta përshtatni lehtë marrjen e karnitinës pa pasur nevojë për kapsula ose tableta të mëdha.</p><p>Forma e lëngshme mundëson përdorim praktik dhe të shpejtë, prandaj produkti është veçanërisht i përshtatshëm për konsum pak para ose gjatë aktivitetit fizik. Me 1500 mg karnitinë për porcion, produkti është shumë i koncentruar. Sidomos gjatë dietës dhe periudhave të definimit, marrja e duhur e L-karnitinës mund të jetë e dobishme si pjesë e një regjimi të mirëstrukturuar ushqyerjeje dhe stërvitjeje.</p><p><strong>L-KARNITINA DHE ROLI I SAJ NË ORGANIZËM</strong></p><p>Karnitina ka rol të rëndësishëm në metabolizmin e yndyrave, sepse acidet yndyrore me zinxhir të gjatë transportohen drejt mitokondrive me ndihmën e L-karnitinës, ku mund të përdoren për prodhimin e energjisë.</p><p>Për uljen efektive të yndyrës trupore, është e nevojshme të kombinohet marrja e duhur e kalorive me aktivitet fizik të rregullt. Carnitin Pro Liquid është zgjedhje praktike për përdorim para ose gjatë stërvitjes, sidomos në periudha kur qëllimi është përmirësimi i formës fizike dhe i definimit.</p><p>L-karnitina është përbërje e ngjashme me vitaminat dhe lëndë ushqyese gjysmë-esenciale, dhe krijimi i saj në organizëm varet nga disponueshmëria e disa aminoacideve, vitaminave dhe mineraleve. Mungesa e disa prej këtyre lëndëve ushqyese mund të ndikojë në sintezën e saj. Prandaj, marrja shtesë e L-karnitinës në formë të lirë mund të jetë zgjedhje praktike, sidomos për persona aktivë dhe sportistë.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 ml (20 porcione) / 1000 ml (40 porcione)</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 25 ml.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, idealisht 20 minuta para stërvitjes. Në ditët kur nuk stërviteni, merreni L-karnitinën para vaktit. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2134;

-- Product_Id: 2135 (IRONMAXX COLLAGEN POWDER ZERO, 250g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'IRONMAXX COLLAGEN POWDER ZERO, 250g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije me kolagjen me 83% hidrolizat kolagjeni dhe vitaminë C</li><li>Vitamina C kontribuon në krijimin normal të kolagjenit për funksionin normal të enëve të gjakut, kockave, kërcit, mishrave të dhëmbëve, dhëmbëve dhe lëkurës</li><li>Cilësia më e lartë</li><li>Tretshmëri e lartë</li></ul><p><strong>Pije pluhur me kolagjen (83%) dhe vitaminë C. Suplement ushqimor me përmbajtje të lartë proteinash dhe ëmbëlsues. Pa sheqer.</strong></p><p>Kolagjeni është proteina kryesore strukturore në hapësirën jashtëqelizore të indeve të ndryshme lidhëse në organizëm. Si përbërësi kryesor i indit lidhor, është proteina më e përhapur te gjitarët dhe përbën deri në 35% të sasisë totale të proteinave në organizëm. Gjendet më së shumti në indet fibroze si tendinat, ligamentet dhe lëkura. Është i pranishëm edhe në kornea, enët e gjakut, zorrët, disqet ndërvertebrale dhe dentinën e dhëmbëve.</p><p>Kur hidrolizohet, kolagjeni zbërthehet në peptide më të vogla që mund të merren në formë suplementi ushqimor. Kolagjeni i hidrolizuar ka masë molekulare dukshëm më të ulët krahasuar me kolagjenin natyral ose xhelatinën.</p><p><strong>PËRFITIMET E PROTEINAVE:</strong></p><ul><li>Proteinat kontribuojnë në ruajtjen e kockave normale, si dhe në rritjen dhe ruajtjen e masës muskulore.</li></ul><p><strong>PËRFITIMET E VITAMINËS C, E CILA ËSHTË SHTUAR NË PRODUKT:</strong></p><ul><li>Vitamina C kontribuon në krijimin normal të kolagjenit për funksionin normal të enëve të gjakut, kockave, kërcit, mishrave të dhëmbëve, dhëmbëve dhe lëkurës</li><li>Vitamina C kontribuon në ruajtjen e funksionimit normal të sistemit imunitar gjatë dhe pas aktivitetit fizik intensiv</li><li>Vitamina C kontribuon në metabolizmin normal energjetik, funksionimin normal të sistemit nervor dhe funksionin normal psikologjik</li><li>Vitamina C kontribuon në mbrojtjen e qelizave nga stresi oksidativ</li><li>Vitamina C kontribuon në uljen e lodhjes dhe rraskapitjes</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 250 g (20 porcione)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 12 g.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni një porcion në ditë. Paralajmërim: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve të vegjël. Ruajeni të mbrojtur nga nxehtësia, lagështia dhe drita e diellit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Vendosni 12 g pluhur dhe 300 ml ujë në shejker dhe tundeni fuqishëm për 20 sekonda.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2135;

-- Product_Id: 2136 (IRONMAXX INSTANT RICE PUDDING)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'IRONMAXX INSTANT RICE PUDDING' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>100% oriz i bluar</li><li>42 g karbohidrate për 50 g</li><li>Vakt i shpejtë energjetik</li><li>Me pak yndyrë dhe sheqer</li><li>Burim fibrash</li><li>Përgatitje e lehtë</li></ul><p><strong>Miell orizi i çastit me kokërr të trashë për përgatitjen e pudingut.</strong></p><p>Pavarësisht nëse kërkoni një mëngjes të shpejtë para punës apo doni të rimbushni rezervat e energjisë para ose pas një stërvitjeje intensive, ky puding orizi është zgjedhje e shkëlqyer. Përveç shijes së shkëlqyer, siguron edhe lëndë ushqyese cilësore për organizmin.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>100% oriz i bluar</li><li>42 g karbohidrate për porcion prej 50 g sigurojnë burim të shpejtë energjie</li><li>Zgjedhje e shkëlqyer për mëngjes, si dhe si vakt para ose pas stërvitjes</li><li>Me pak yndyrë dhe sheqer</li><li>Burim fibrash</li><li>I përshtatshëm për mënyra të ndryshme ushqyerjeje, përfshirë atë vegane dhe vegjetariane</li><li>Pa aditivë dhe konservues</li><li>Përgatitje e shpejtë dhe e lehtë</li></ul><p><strong>Sasia neto:</strong> 750 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 50 g.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Ideal për mëngjes ose si vakt para dhe pas stërvitjes. Sugjerim për servirje: pasi të ftohet, mund të shtoni pluhurin tuaj të preferuar të proteinës. Edhe më e shijshme me shtesa sipas zgjedhjes suaj. Ruajeni të mbrojtur nga nxehtësia, lagështia dhe drita e diellit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Thjesht përzieni 50 g oriz të bluar të çastit me 150 ml ujë të nxehtë dhe lëreni të qëndrojë pak. Nëse nxitoni, pudingun mund ta përgatitni edhe në mikrovalë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2136;

-- Product_Id: 2140 (IRONMAXX TT ULTRA STRONG 100% TRIBULUS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'IRONMAXX TT ULTRA STRONG 100% TRIBULUS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><ul><li>1600 mg ekstrakt <em>Tribulus terrestris</em> për tabletë</li><li>15 mg zink për tabletë (150% e MRD)</li><li>Mbështetje për performancën fizike</li><li>90 / 180 porcione</li></ul><p><strong>Tableta me <em>Tribulus terrestris</em> dhe zink. Suplement ushqimor.</strong></p><p><strong>100% <em>TRIBULUS TERRESTRIS</em></strong></p><p>Tabletat TT® Ultra Strong përmbajnë 100% ekstrakt <em>Tribulus terrestris</em> shumë të pastër dhe të certifikuar. Me një përqendrim prej 1600 mg <em>Tribulus terrestris</em> për tabletë, TT® Ultra Strong është ndër produktet Tribulus më të koncentruara. Përveç përmbajtjes së lartë të saponinave (80%), TT® Ultra Strong përmban edhe 19% protodioscinë.</p><p>Formula është e destinuar për periudhat e ndërtimit të masës muskulore, bodibilding dhe stërvitje force, dhe është pasuruar gjithashtu me mineralin esencial në gjurmë – zinkun.</p><p><strong>MBËSHTETJE PËR NIVELIN NORMAL TË TESTOSTERONIT</strong></p><p>Aktiviteti fizik i rregullt ka rol të rëndësishëm në ruajtjen e formës fizike dhe ekuilibrit hormonal. TT® Ultra Strong siguron gjithashtu 15 mg zink për tabletë.</p><p><strong>ZINKU KONTRIBUON NË:</strong></p><ul><li>ruajtjen e nivelit normal të testosteronit në gjak</li><li>sintezën normale të proteinave</li><li>metabolizmin normal të makronutrientëve</li><li>mbrojtjen e qelizave nga stresi oksidativ</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 90 tableta / 180 tableta</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 tabletë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, me një gotë ujë. Paralajmërim: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Ruajeni në vend të thatë dhe të freskët, të mbrojtur nga drita dhe larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Ruajeni të mbrojtur nga nxehtësia, lagështia dhe drita e diellit.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2140;

-- Product_Id: 2143 (NUTREND CARNITINE DRINK, 750ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'NUTREND CARNITINE DRINK, 750ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije freskuese e gatshme për konsum të drejtpërdrejtë</li><li>Pa sheqer</li><li>1000 mg L-karnitinë për porcion</li><li>Me kafeinë dhe taurinë</li></ul><p><strong>Pije joalkoolike e aromatizuar me ëmbëlsues, me L-karnitinë, taurinë dhe kafeinë të shtuar.</strong></p><p><strong>Pije joalkoolike e gazuar dhe e aromatizuar me ëmbëlsues, me L-karnitinë, taurinë dhe kafeinë të shtuar.</strong><br>(shijet: Mjedër, Kola, Mojito, Mango &amp; Kokos, Livando, Luleshtrydhe &amp; Mente)</p><p>Pije freskuese e gatshme pa sheqer që përmban 1000 mg L-karnitinë, me përbërës stimulues të shtuar si kafeina dhe taurina. Pija është zgjedhje e shkëlqyer për mbështetjen e performancës fizike dhe ndihmon në ruajtjen e hidratimit të duhur gjatë stërvitjes. Falë shijes së lehtë dhe freskuese, përshtatet lehtë në rutinën e stërvitjes dhe ju ndihmon të merrni rregullisht lëngje.</p><ul><li>1000 mg L-karnitinë</li><li>1000 mg taurinë</li><li>40 mg kafeinë</li><li>Pa sheqer</li></ul><p><strong>PËRDORIMI I REKOMANDUAR:</strong> 1 shishe në ditë. Konsumoni 20–30 minuta para aktivitetit fizik. Mund të përdoret edhe gjatë stërvitjes.</p><p><strong>PËRDORIMI:</strong> Pas hapjes, produkti duhet të konsumohet brenda 24 orëve.</p><p><strong>I përshtatshëm për sportistë, me ëmbëlsues.</strong> I destinuar për nevoja të veçanta ushqyese. Nuk është i destinuar për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, në temperaturë deri në 25°C dhe të mbrojtur nga drita e drejtpërdrejtë e diellit. Mos e ngrini. Përmban kafeinë. Nuk është i përshtatshëm për sportistë të regjistruar. Prodhuesi nuk mban përgjegjësi për dëmet e shkaktuara nga përdorimi ose ruajtja e gabuar.</p><p><strong>Sasia neto:</strong> 750 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Konsumoni 20–30 minuta para ushtrimeve. Mund të përdoret edhe gjatë ushtrimeve fizike.  Përdorimi: Pas hapjes, konsumojeni produktin brenda 24 orëve.  I përshtatshëm për sportistë, me ëmbëlsues. I destinuar për përdorim të veçantë ushqyes. Nuk është i destinuar për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, në temperaturë jo më të lartë se 25°C dhe larg dritës së drejtpërdrejtë të diellit. Mos e ngrini. Përmban kafeinë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pini 1 shishe NUTREND CARNITINE DRINK në ditë' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2143;

-- Product_Id: 2147 (NUTREND CARNITINE DRINK (CAFFEINE FREE), 750ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'NUTREND CARNITINE DRINK (CAFFEINE FREE), 750ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Hidratim i trupit gjatë aktivitetit fizik</li><li>Përdorim praktik</li></ul><p><strong>Pije joalkoolike e aromatizuar me ëmbëlsues. E formuluar posaçërisht për sportistë.</strong></p><p><strong>LEHTËSI NË ÇDO GLLËNJKË!</strong> Rimbush lëngjet dhe siguron hidratim gjatë aktivitetit fizik. Nuk përmban sheqer as karbohidrate.</p><p>Pija përmban një lloj të veçantë L-karnitine, “Carnipure”, të prodhuar nga kompania zvicerane Lonza.</p><p>Shishja prej 750 ml përmban:</p><ul><li>1000 mg L-karnitinë</li><li>1000 mg taurinë</li><li>17,3 mg vitaminë B3 (108%*MRD)</li><li>0 g sheqer</li></ul><p><em>MRD – Marrja e referencës ditore.</em></p><p><strong>Sasia neto:</strong> 750 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Pini 1 shishe në ditë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Për të mbështetur performancën fizike, filloni ta konsumoni 20–30 minuta para ushtrimeve dhe vazhdoni ta konsumoni edhe gjatë ushtrimeve. Pas hapjes, konsumojeni produktin brenda 24 orëve. Mund të shfaqet sediment, gjë që nuk ndikon në cilësinë dhe sigurinë e produktit. PARALAJMËRIM: I destinuar për përdorim të veçantë ushqyes. Ruajeni në vend të thatë, në temperaturë nën 25°C, të mbrojtur nga drita e drejtpërdrejtë e diellit. Mos e ngrini. Mbajeni larg fëmijëve! Nuk është i përshtatshëm për fëmijë, adoleshentë, gra shtatzëna, gra që ushqejnë me gji dhe persona të ndjeshëm ndaj kafeinës. Prodhuesi nuk mban përgjegjësi për dëmet e shkaktuara nga përdorimi ose ruajtja e gabuar.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2147;

-- Product_Id: 2148 (NUTREND CARNITINE MAGNESIUM DRINK)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'NUTREND CARNITINE MAGNESIUM DRINK' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Pija e njohur me L-karnitinë, tani e pasuruar me magnez dhe vitaminë B6</li><li>Lehtësisht e gazuar</li><li>Pa kripë, sheqer dhe ngjyrues</li></ul><p><strong>Pije joalkoolike e gazuar dhe e aromatizuar me L-karnitinë, magnez dhe vitaminë B6 të shtuar.</strong></p><p>Pija legjendare me karnitinë, e njohur te miliona përdorues në mbarë botën, tani vjen në një version të ri të pasuruar me magnez dhe vitaminë B6. Pija freskuese, lehtësisht e gazuar dhe pa sheqer përmban L-karnitinë dhe një sasi të konsiderueshme magnezi – mineral, marrja e të cilit te një pjesë e madhe e popullsisë shpesh është e pamjaftueshme.</p><p>Magnezi kontribuon në funksionin normal të muskujve, uljen e lodhjes dhe rraskapitjes dhe funksionimin normal të sistemit nervor, si dhe kontribuon në ruajtjen e kockave dhe dhëmbëve normalë. Carnitine Magnesium Activity Drink siguron gjithashtu 100% të marrjes ditore të referencës së vitaminës B6, e cila kontribuon në funksionimin normal të sistemit imunitar dhe krijimin normal të qelizave të kuqe të gjakut.</p><p>Carnitine Magnesium Activity Drink tradicionalisht përmban sasi të lartë L-karnitine cilësore – 1000 mg. L-karnitina është substancë që gjendet natyrshëm në organizëm dhe që trupi mund ta prodhojë në një sasi të caktuar. Sinteza e saj varet nga prania e aminoacideve L-lizinë dhe L-metioninë, si dhe nga vitaminat B3, B6 dhe C dhe hekuri. L-karnitina merr pjesë në transportin e acideve yndyrore me zinxhir të gjatë drejt mitokondrive, ku ato përdoren për prodhimin e energjisë. Është e përshtatshme si pjesë e ushqyerjes si për stërvitje force, ashtu edhe për sporte qëndrueshmërie.</p><ul><li>Shishe ergonomike me kapak “sport lock”</li><li>Pa ngjyrues</li><li>0% kripë</li><li>Përmban L-karnitinë</li><li>Përmban magnez (57%**MRD) dhe vitaminë B6 (100%**MRD)</li><li>Pa sheqer</li><li>Lehtësisht e gazuar</li></ul><p>**MRD – Marrja e referencës ditore.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 750 ml / 8 × 750 ml</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza e rekomanduar: 1 shishe në ditë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pijeni 20–30 minuta para aktivitetit fizik. Mund të përdoret edhe gjatë aktivitetit fizik. Pas hapjes, konsumojeni produktin brenda 24 orëve. Paralajmërim: Nuk është i përshtatshëm për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji. Ruajeni larg nxehtësisë, ngricës, lagështisë dhe dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2148;

-- Product_Id: 2149 (OLIMP ARGI POWER, 120 капсули)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP ARGI POWER, 120 kapsula' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>1500 mg L-arginine HCl me cilësi farmaceutike të nivelit të lartë</li><li>Shtesë e vlefshme për kombinimet me kreatinë, kreatinën dhe format e saj të avancuara</li><li>Një kapsulë përmban: 1500 mg L-arginine HCl</li></ul><p><strong>Suplement ushqimor në kapsula me aminoacidin L-arginine.</strong></p><p>ARGI POWER™ 1500 MEGA CAPS® përmban 1500 mg L-arginine HCl me cilësi të lartë dhe pastërti farmaceutike në 1 kapsulë.</p><p>ARGI POWER™ Mega Caps® është zgjedhje e shkëlqyer si suplement ushqimor më vete, por edhe si shtesë e vlefshme për kombinimet me kreatinë të OLIMP.</p><p><strong>Sasia neto:</strong> 120 kapsula</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, para stërvitjes ose para aktivitetit seksual, me sasi më të madhe uji. PARALAJMËRIM: Nuk është i përshtatshëm për fëmijë dhe të rinj. Mos e tejkaloni dozën e rekomanduar ditore. Suplementi ushqimor nuk duhet të përdoret si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2149;

-- Product_Id: 2150 (OLIMP ASHWAGANDHA 600 SPORT, 60 капсули)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP ASHWAGANDHA 600 SPORT, 60 kapsula' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Ndikon pozitivisht në funksionimin normal të sistemit nervor, riprodhues dhe imunitar</li><li>Veprim antioksidant</li><li>Përmban ekstraktin e patentuar të ashwagandhës KSM-66®</li><li>Një paketim mjafton për një muaj përdorim</li></ul><p><strong>ASHWAGANDHA 600 Sport Edition me ekstrakt të patentuar KSM-66® nga rrënja e ashwagandhës.</strong></p><p>Ashwagandha (<em>Withania somnifera</em>), e njohur edhe si xhensen indian ose qershi dimri, është një nga bimët më të njohura që përdoren tradicionalisht në mjekësinë indiane – Ajurveda.</p><p>Në Ajurveda, ashwagandha përdoret si pjesë e të ashtuquajturës traditë <strong>Rasayana</strong>, qëllimi i së cilës është ruajtja e vitalitetit dhe e mirëqenies fizike dhe mendore. Rasayana përfshin një kombinim bimësh, stili jetese dhe ushqyerjeje.</p><p><strong>ASHWAGANDHA 600 Sport Edition</strong> përmban <strong>ekstrakt të patentuar KSM-66® nga rrënja e ashwagandhës</strong>, me përbërje të standardizuar dhe përqendrim të lartë të përbërësve aktivë.</p><p>Ashwagandha njihet si <strong>adaptogjen</strong> dhe përdoret tradicionalisht për të mbështetur organizmin në periudha stresi fizik dhe psikik. Produkti është i destinuar për persona fizikisht aktivë dhe për të gjithë ata që duan mbështetje shtesë për vitalitetin dhe mirëqenien e përgjithshme.</p><p><strong>PËRFITIMET KRYESORE:</strong></p><ul><li>Mbështet funksionimin normal të sistemit nervor dhe mirëqenien mendore</li><li>Ndihmon në ruajtjen e funksionit normal të sistemit riprodhues</li><li>Mbështet funksionimin normal të sistemit imunitar</li><li>Ka veti antioksiduese</li><li>Ndihmon në ruajtjen e vitalitetit fizik dhe mendor</li><li>Ndihmon organizmin të përshtatet me stresin</li><li>Përmban ekstraktin e patentuar KSM-66® të ashwagandhës</li><li>Një paketim mjafton për një muaj përdorim</li></ul><p></p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2150;

-- Product_Id: 2151 (OLIMP BCAA XPLODE POWDER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP BCAA XPLODE POWDER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>6 g BCAA për porcion</li><li>Formulë e pasuruar me L-glutaminë dhe vitaminë B6</li><li>Për persona fizikisht aktivë dhe sportistë</li><li>Tretshmëri e shkëlqyer</li></ul><p><strong>Suplement ushqimor me aminoacide BCAA, L-glutaminë dhe vitaminë B6. Me ëmbëlsues.</strong></p><p><strong>BCAA DHE L-GLUTAMINË NË NJË PORCION</strong></p><p>Me Olimp BCAA Xplode Powder merrni një kombinim të <strong>aminoacideve BCAA me zinxhir të degëzuar</strong> me cilësi të lartë – L-leucinë, L-valinë dhe L-izoleucinë – të plotësuara me <strong>L-glutaminë dhe vitaminë B6</strong>.</p><p>Produkti është zhvilluar për sportistë dhe persona fizikisht aktivë që duan të plotësojnë thjesht marrjen ditore të aminoacideve BCAA. Çdo porcion siguron <strong>6 g BCAA dhe 1 g L-glutaminë</strong>.</p><p>Formula është <strong>pa sheqer</strong> dhe përmban proteina, të cilat kontribuojnë në rritjen dhe ruajtjen e masës muskulore. Vitamina B6 kontribuon në metabolizmin normal të proteinave dhe glikogjenit, metabolizmin normal energjetik, funksionimin normal të sistemit nervor dhe uljen e lodhjes dhe rraskapitjes.</p><p><strong>ME OLIMP BCAA XPLODE POWDER MERRNI:</strong></p><ul><li>Mbështetje për plotësimin e ushqyerjes ditore me aminoacide BCAA</li><li>Deri në 6 g BCAA të pastra dhe 1 g L-glutaminë për porcion</li><li>Formulë pa sheqer</li><li>Proteina që kontribuojnë në rritjen dhe ruajtjen e masës muskulore</li><li>Vitaminë B6 që kontribuon në metabolizmin normal të proteinave dhe glikogjenit, funksionimin normal të sistemit nervor dhe uljen e lodhjes dhe rraskapitjes</li><li>Shije të shkëlqyera</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 280 g / 500 g / 1000 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse (10 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1–2 porcione në ditë – para vaktit ose stërvitjes dhe pas stërvitjes ose para gjumit. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Mbajeni larg fëmijëve. Shënim: Mund të shfaqet sediment, gjë që nuk ndikon në cilësinë dhe efektin e produktit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 200 ml ujë. Konsumojeni menjëherë pas përgatitjes.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2151;

-- Product_Id: 2152 (OLIMP BETA ALANINE CARNO RUSH, 80 таблети)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP BETA ALANINE CARNO RUSH, 80 tableta' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Rekomandohet gjatë stërvitjeve më intensive</li><li>Përmban beta-alaninë dhe L-histidinë</li><li>Ndihmon në vonimin e shfaqjes së lodhjes dhe zgjatjen e kohëzgjatjes së stërvitjes</li></ul><p><strong>NDJENI FUQINË E VËRTETË TË STËRVITJES!</strong></p><p>Beta-Alanine Carno Rush Mega Tabs® është suplement ushqimor i destinuar për personat që praktikojnë sporte force dhe qëndrueshmërie, stërvitje me intensitet të lartë dhe sporte që kërkojnë ruajtjen e një niveli të lartë të përgatitjes fizike për një periudhë më të gjatë kohore.</p><p><strong>Beta-Alanine Carno Rush Mega Tabs®</strong> ndihmon në zgjatjen e kohës deri në shfaqjen e lodhjes, gjë që mundëson stërvitje më të gjata dhe më intensive.</p><p><strong>BETA-ALANINE CARNO RUSH MEGA TABS® – KOMBINIM I KRIJUAR POSAÇËRISHT NGA BETA-ALANINË, L-HISTIDINË DHE VITAMINË B6!</strong></p><p>Beta-alanina dhe L-histidina janë dy substanca të nevojshme për sintezën e karnozinës. Karnozina ka veti antioksiduese dhe luan rol të rëndësishëm në indin muskulor, sidomos gjatë aktivitetit fizik intensiv.</p><p>Marrja e njëkohshme e beta-alaninës dhe L-histidinës siguron prekursorët e nevojshëm për krijimin e karnozinës dhe ndihmon në shmangien e marrjes së tyre të pamjaftueshme përmes ushqyerjes.</p><p><strong>Beta-Alanine Carno Rush Mega Tabs®</strong> është formuluar për mbështetje gjatë stërvitjeve intensive dhe mund të ndihmojë në ruajtjen e performancës gjatë përpjekjeve fizike të zgjatura.</p><p><strong>BETA-ALANINE CARNO RUSH MEGA TABS® – SA GJATË MUND TË DURONI PËRPJEKJE EKSTREME?</strong></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 3–4 tableta.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë me vakt ose para stërvitjes, me sasi të madhe uji. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Paralajmërim: nuk rekomandohet për fëmijë, të rinj, gra shtatzëna dhe gra që ushqejnë me gji ose në rast mbindjeshmërie ndaj ndonjë prej përbërësve të produktit. Disa persona mund të ndiejnë thumbim ose mpirje pas konsumimit. Ky është efekt i përkohshëm që i atribuohet veprimit të fortë të beta-alaninës. Nuk ndikon në shëndet. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2152;

-- Product_Id: 2153 (OLIMP BETA-ALANINE XPLODE POWDER, 250g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP BETA-ALANINE XPLODE POWDER, 250g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>1600 mg beta-alaninë me cilësi të lartë për porcion (3,2 g)</li><li>Rekomandohet gjatë stërvitjeve më intensive</li><li>Kontribuon në uljen e ndjesisë së lodhjes dhe rraskapitjes (vitamina B6)</li><li>Shije freskuese portokalli</li></ul><p><strong>Suplement ushqimor pluhur me beta-alaninë, vitaminë B6, L-histidinë dhe natrium. Me ëmbëlsues.</strong></p><p>Nëse lodhja dhe qëndrueshmëria e pamjaftueshme ju pengojnë të nxirrni maksimumin nga stërvitja, <strong>Beta-Alanine Xplode Powder</strong> është formulë e krijuar për plotësimin e ushqyerjes me beta-alaninë me cilësi të lartë, të plotësuar me vitaminë B6 dhe L-histidinë.</p><p>Produkti është pjesë e serisë <strong>Xplode</strong> të Olimp Sport Nutrition, e njohur për tretshmërinë e shkëlqyer, biodisponueshmërinë e lartë të përbërësve aktivë, shijen e shkëlqyer dhe cilësinë e kontrolluar me kujdes të lëndëve të para. <strong>Beta-Alanine Xplode Powder</strong> prodhohet me teknologji moderne dhe sipas standardeve të larta të cilësisë dhe sigurisë.</p><p><strong>BETA-ALANINE XPLODE POWDER SIGURON:</strong></p><ul><li>Tretshmëri të shkëlqyer dhe shije freskuese portokalli</li><li>1600 mg beta-alaninë me cilësi të lartë për porcion prej 3,2 g</li><li>Vitaminë B6, e cila kontribuon në uljen e lodhjes dhe rraskapitjes</li><li>Vitaminë B6, e cila kontribuon në metabolizmin normal energjetik dhe metabolizmin normal të proteinave dhe glikogjenit</li><li>Vitaminë B6, e cila kontribuon në funksionimin normal të sistemit nervor</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 250 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 lugë matëse (3,2 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion 3 herë në ditë me vakt ose para stërvitjes. Konsumojeni menjëherë pas përgatitjes. PARALAJMËRIM: Nuk rekomandohet për fëmijë, të rinj, gra shtatzëna dhe gra që ushqejnë me gji, as për persona të mbindjeshëm ndaj ndonjë prej përbërësve të produktit. Te disa persona pas konsumimit mund të shfaqet ndjesi thumbimi ose mpirjeje. Ky është efekt i përkohshëm i lidhur me veprimin e beta-alaninës dhe nuk paraqet rrezik për shëndetin. Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion (3,2 g) në 100 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2153;

-- Product_Id: 2154 (OLIMP CHELA-MAG B6 FORTE SHOT (NEW))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP CHELA-MAG B6 FORTE SHOT (NEW)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Magnez në formë të kelatit aminoacidik Albion® me cilësi të lartë</li><li>Dozë e lartë prej 375 mg magnez për ampulë</li><li>Mbështet funksionimin normal të muskujve dhe sistemit nervor</li><li>Thithje e shkëlqyer</li><li>Për persona me nevojë të shtuar për magnez</li><li>I përshtatshëm për veganë</li></ul><p><strong>Suplement ushqimor me magnez shumë të thithshëm në formë të lëngshme, i pasuruar me vitaminë B6. Me ëmbëlsues.</strong></p><p><strong>GJENERATA E RE E MAGNEZIT</strong></p><p>Chela-Mag B6® Forte SHOT përmban formë të lëngshme shumë të thithshme të magnezit në trajtën e kelatit aminoacidik Albion®. Një ampulë përmban <strong>375 mg magnez</strong>, të pasuruar me vitaminë B6, dhe siguron <strong>100% të marrjes ditore të referencës së magnezit</strong>.</p><p>Përdorimi i formulës inovative <strong>Liquid Technology</strong> mundëson disponueshmëri të shpejtë të përbërësve aktivë në formë të lëngshme, pa pasur nevojë për tretje si te tabletat ose kapsulat. E gjithë kjo është paketuar në një ampulë praktike prej 25 ml, që mundëson përdorim të thjeshtë dhe të rehatshëm në çdo kohë.</p><p><strong>MAGNEZI KONTRIBUON NË:</strong></p><ul><li>Funksionimin normal të muskujve</li><li>Funksionimin normal të sistemit nervor</li><li>Uljen e lodhjes dhe rraskapitjes</li><li>Ruajtjen e funksionit normal psikologjik</li><li>Ruajtjen e kockave dhe dhëmbëve normalë</li><li>Ruajtjen e ekuilibrit të elektroliteve</li><li>Metabolizmin normal energjetik</li><li>Sintezën normale të proteinave</li><li>Procesin normal të ndarjes qelizore</li></ul><p>Vitamina B6 kontribuon gjithashtu në funksionimin normal të sistemit nervor, funksionin normal psikologjik dhe uljen e lodhjes dhe rraskapitjes.</p><p>Magnezi në produkt është në formë të <strong>kelatit aminoacidik Albion®</strong> me cilësi të lartë, i karakterizuar nga biodisponueshmëri e lartë dhe thithje e mirë nga trakti gastrointestinal.</p><p>Kelati aminoacidik i magnezit Albion® është plotësisht hipoalergjik sipas patentës US 7,838,042, gjë që kontribuon në sigurinë gjatë përdorimit.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 25 ml / 9 × 25 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 ampulë (25 ml).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pini 1 porcion (25 ml) në ditë pas vaktit. Tundeni para përdorimit. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Sedimenti dhe kristalizimi që mund të shfaqen janë natyrale dhe nuk ndikojnë në cilësinë e produktit. Produkti është i përshtatshëm për veganë. Të pahapur, ruajeni në vend të thatë, nën 25°C. Ruajeni larg dritës së diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2154;

-- Product_Id: 2155 (OLIMP CITRULLINE MALATE, 200g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP CITRULLINE MALATE, 200g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Citrulinë malat dhe vitaminë B6</li><li>8,1 g citrulinë malat për porcion</li><li>Kontribuon në uljen e lodhjes dhe rraskapitjes (vitamina B6)</li><li>Shije freskuese</li></ul><p><strong>Suplement ushqimor pluhur me citrulinë malat dhe vitaminë B6. Me ëmbëlsues.</strong></p><p>L-citrulina është aminoacid jo-esencial që në organizëm mund të shndërrohet në L-argininë dhe kështu të marrë pjesë në krijimin e oksidit të azotit (NO).</p><p><strong>VITAMINA B6 KONTRIBUON NË:</strong></p><ul><li>Metabolizmin normal energjetik</li><li>Funksionimin normal të sistemit nervor</li><li>Metabolizmin normal të proteinave dhe glikogjenit</li><li>Funksionin normal psikologjik</li><li>Krijimin normal të qelizave të kuqe të gjakut</li><li>Funksionimin normal të sistemit imunitar</li><li>Uljen e lodhjes dhe rraskapitjes</li><li>Rregullimin e aktivitetit hormonal</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 200 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 3 lugë matëse (9 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, rreth 30 minuta para stërvitjes. Konsumojeni menjëherë pas përgatitjes. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Mbajeni larg fëmijëve! Mos e përdorni te fëmijët, gratë shtatzëna ose ato që ushqejnë me gji dhe në rast mbindjeshmërie ndaj ndonjë prej përbërësve.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 300 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2155;

-- Product_Id: 2156 (OLIMP CREATINE MONOHYDRATE POWDER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP CREATINE MONOHYDRATE POWDER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Koncentrat kreatine pluhur</li><li>Rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë</li></ul><p><strong>Suplement ushqimor me kreatinë, në formë pluhuri.</strong></p><p>Kreatina monohidrat është një nga format më të njohura dhe më të përdorura të kreatinës mes sportistëve.</p><p>Konsumimi i kreatinës rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Efekti i dobishëm arrihet me marrje ditore prej <strong>3 g kreatinë</strong>.</p><p>Produkti është i destinuar për të rritur fizikisht aktivë që kryejnë stërvitje me intensitet të lartë.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 250 g / 550 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1,5 lugë matëse (3,4 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë – gjatë ditëve të stërvitjes ose garës. Mund të ndodhë rritje e peshës trupore. Nuk është i përshtatshëm për fëmijë dhe të rinj. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 200–250 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2156;

-- Product_Id: 2157 (OLIMP CREATINE XPLODE POWDER, 500g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP CREATINE XPLODE POWDER, 500g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>Formulë me cilësi të lartë me <strong>6 forma kreatine</strong></li><li><strong>4,5 g kreatinë për porcion</strong></li><li>Tretshmëri e shkëlqyer</li><li>E destinuar për stërvitje me intensitet të lartë</li><li>Kreatina kontribuon në rritjen e performancës fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë</li><li>Zgjedhje e shkëlqyer për sportistë dhe persona fizikisht aktivë</li></ul><h3><strong>Suplement ushqimor pluhur me ëmbëlsues.</strong></h3><p><strong>CREATINE XPLODE – FORMULË E AVANCUAR ME 6 FORMA KREATINE</strong></p><p>Creatine Xplode është formulë e avancuar e zhvilluar nga ekspertët e <strong>Olimp Laboratories</strong> me zbatimin e teknologjisë moderne të prodhimit. Kontrolli i kujdesshëm i pastërtisë së lëndëve të para, testimi për praninë e metaleve të rënda dhe respektimi i standardeve të larta të prodhimit sigurojnë produkt me cilësi të lartë dhe siguri gjatë përdorimit.</p><p>Produkti është i destinuar për <strong>të rritur fizikisht aktivë që kryejnë stërvitje me intensitet të lartë</strong>.</p><p><strong>6 FORMA TË NDRYSHME KREATINE</strong></p><p>Creatine Xplode përmban një kombinim prej <strong>6 formash të ndryshme kreatine</strong>, të kombinuara me kujdes në një formulë. Çdo porcion siguron <strong>4,5 g kreatinë</strong>.</p><p>Kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Efekti i dobishëm arrihet me marrje ditore prej <strong>3 g kreatinë</strong>.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është gjysmë luge matëse (5,8 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë – para mëngjesit ose pas stërvitjes.  PARALAJMËRIM: Mund të ndodhë rritje e peshës trupore. Nuk është i përshtatshëm për fëmijë dhe të rinj. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Lejohet ngjitja e produktit në gunga dhe sedimenti pas tretjes në ujë, gjë që nuk ndikon në cilësinë e produktit. Të pahapur, ruajeni në vend të thatë dhe të freskët. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 125 ml ujë. Konsumojeni menjëherë pas përgatitjes.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2157;

-- Product_Id: 2158 (OLIMP GLUTAMINE XPLODE POWDER, 500g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP GLUTAMINE XPLODE POWDER, 500g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Për persona fizikisht aktivë dhe sportistë</li><li><strong>5,5 g L-glutaminë për porcion</strong></li><li>I pasuruar me vitaminë C dhe vitamina të grupit B</li><li>100% L-glutaminë e pastër në formë kristalore</li><li>Vitaminat B6 dhe B12 kontribuojnë në uljen e lodhjes dhe rraskapitjes</li></ul><h3><strong>Suplement ushqimor pluhur me L-glutaminë.</strong></h3><p><strong>L-GLUTAMINË E PASTËR E PASURUAR ME VITAMINA</strong></p><p>L-glutamina është aminoacid proteinogjen, pra aminoacid që merr pjesë në krijimin e proteinave. Kryesisht sintetizohet dhe ruhet në muskujt skeletorë. Nevoja për glutaminë mund të rritet në periudha stresi të shtuar fiziologjik dhe gjatë nivelit të lartë të aktivitetit fizik.</p><p>Produkti e plotëson ushqyerjen e përditshme me <strong>L-glutaminë në formë 100% të pastër, kristalore</strong>, dhe është pasuruar gjithashtu me vitaminat <strong>B6, B12 dhe C</strong>.</p><p>Vitaminat <strong>B6 dhe B12 kontribuojnë në uljen e lodhjes dhe rraskapitjes</strong>, ndërsa vitamina C kontribuon në funksionimin normal të sistemit imunitar gjatë dhe pas aktivitetit fizik intensiv. Efekti i dobishëm arrihet me marrje shtesë ditore prej 200 mg vitaminë C mbi marrjen e rekomanduar ditore.</p><p>Produkti është i destinuar për <strong>persona fizikisht aktivë dhe sportistë</strong>.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është ½ lugë matëse ose 1 lugë (10 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merreni një herë në ditë – para mëngjesit, pas stërvitjes ose para gjumit. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Mbajeni larg fëmijëve. Shënim: Mund të shfaqet sediment, gjë që nuk ndikon në cilësinë dhe efektin e produktit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 200 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2158;

-- Product_Id: 2159 (OLIMP KOLAGEN ACTIV PLUS, 80 таблети)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP KOLAGEN ACTIV PLUS, 80 tableta' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Suplement ushqimor me kolagjen të hidrolizuar</li><li>Për mbështetjen e kockave, nyjeve dhe indit lidhor</li><li>Për mbështetjen e lëkurës, thonjve dhe flokëve</li><li>Tableta për përtypje me shije të këndshme agrumesh</li></ul><h3><strong>Suplement ushqimor me kolagjen, vitamina dhe minerale – tableta për përtypje me shije agrumesh dhe ëmbëlsues.</strong></h3><p>Formula siguron <strong>kolagjen të hidrolizuar</strong> dhe është pasuruar gjithashtu me vitamina dhe minerale të rëndësishme.</p><p>Përmban <strong>kalcium dhe magnez</strong>, të cilët kontribuojnë në ruajtjen e kockave normale.</p><p>Përveç kësaj, <strong>vitamina C kontribuon në krijimin normal të kolagjenit</strong> për funksionin normal të kockave, kërcit dhe lëkurës.</p><p>Forma praktike e <strong>tabletave për përtypje me shije agrumesh</strong> mundëson përdorim të thjeshtë dhe të rehatshëm të përditshëm.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 4 tableta për përtypje.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion 2 herë në ditë ndërmjet vakteve. Paralajmërim: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve. Konsumimi i tepërt mund të ketë efekt laksativ. Të pahapur, ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2159;

-- Product_Id: 2160 (OLIMP L-GLUTAMINE POWDER, 250g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP L-GLUTAMINE POWDER, 250g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>100% L-glutaminë pluhur</li><li>Mbështetje për rigjenerimin pas aktivitetit fizik</li><li>Mbështet funksionimin normal të sistemit imunitar</li><li>I destinuar për të gjithë personat fizikisht aktivë</li></ul><p><strong>OLIMP L-GLUTAMINE POWDER</strong> është produkt që përmban 100% L-glutaminë të pastër, me cilësi farmaceutike dhe të mikronizuar – aminoacid që gjendet natyrshëm në përqendrime të larta në muskuj dhe në plazmën e gjakut.</p><p>Glutamina është një nga aminoacidet më të përhapura në indin muskulor dhe merr pjesë në procese të shumta metabolike të lidhura me metabolizmin e proteinave dhe transportin e azotit në organizëm.</p><p><strong>L-glutamina</strong> e mikronizuar dallohet për tretshmëri të shkëlqyer dhe është e përshtatshme për plotësimin e ushqyerjes te personat fizikisht aktivë dhe sportistët me nevoja të shtuara.</p><p><strong>OLIMP L-GLUTAMINE POWDER</strong> është i destinuar për sportistë që merren me stërvitje force dhe qëndrueshmërie, sidomos në periudha stërvitjesh intensive dhe ngarkese fizike të shtuar.</p><p><strong>PËRDORIMI I REKOMANDUAR:</strong> Merrni 4 g pluhur 2–3 herë në ditë – para mëngjesit, pas stërvitjes dhe para gjumit. Tretni 4 g (1½ lugë matëse) në 100 ml ujë.</p><p><strong>PARALAJMËRIM:</strong> Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Nuk është i përshtatshëm për fëmijë dhe të rinj. Mbajeni larg fëmijëve!</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1,5 lugë matëse (4 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion 2–3 herë në ditë – para mëngjesit, pas stërvitjes dhe para gjumit. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Nuk është i përshtatshëm për fëmijë dhe të rinj. Mbajeni larg fëmijëve. Ruajeni në vend të thatë dhe të freskët.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 100 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2160;

-- Product_Id: 2162 (OLIMP R-WEILER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP R-WEILER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Deri në 80 porcione për paketim</li><li>Veprim sinergjik i përbërësve aktivë të kombinuar me kujdes</li><li>3 komplekse të fuqishme me AAKG, citrulinë, beta-alaninë, kreatinë, L-tirozinë dhe kafeinë</li></ul><h3><strong>Suplement ushqimor pluhur me ëmbëlsues.</strong></h3><p><strong>OLIMP REDWEILER – LEGJENDË MES FORMULAVE PRE-WORKOUT</strong></p><p>Redweiler është formulë komplekse pre-workout e destinuar për persona fizikisht aktivë dhe sportistë që kërkojnë mbështetje gjatë stërvitjeve intensive dhe të rënda.</p><p>Formula kombinon <strong>L-argininë, L-citrulinë, beta-alaninë, kreatinë, L-tirozinë dhe kafeinë</strong>, të plotësuara me vitamina, minerale dhe ekstrakte bimore nga speci kajen dhe piperi i zi.</p><p><strong>14 PËRBËRËS AKTIVË NË 3 KOMPLEKSE TË KRIJUARA POSAÇËRISHT</strong></p><p><strong>Armageddon Pump Formula</strong> – kombinim i AAKG dhe L-citrulinës, i plotësuar me natrium dhe vitaminë B6.</p><p><strong>Berserker''s Performance Blend</strong> – kombinim i beta-alaninës dhe dy formave të kreatinës, i plotësuar me vitamina dhe minerale.</p><p><strong>Red Fury Matrix</strong> – kombinim i L-tirozinës dhe kafeinës me ekstrakte të shtuara nga speci kajen dhe piperi i zi.</p><p>Vitaminat <strong>B6, niacina dhe tiamina</strong> kontribuojnë në metabolizmin normal energjetik dhe funksionimin normal të sistemit nervor. Vitamina B6 dhe niacina kontribuojnë gjithashtu në uljen e lodhjes dhe rraskapitjes dhe në funksionin normal psikologjik.</p><p><strong>Përmban kafeinë.</strong> Nuk rekomandohet për fëmijë ose gra shtatzëna. Përmbajtja e kafeinës: <strong>200 mg në 12 g / 300 mg në 18 g</strong>.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Në varësi të peshës trupore, rekomandohet dozimi i mëposhtëm: - nën 75 kg: porcion prej 6 g (1/2 lugë matëse) - 75–90 kg: porcion prej 12 g (1 lugë matëse) - mbi 90 kg: porcion prej 18 g (1 e 1/2 lugë matëse)' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, 30 minuta para stërvitjes. Paralajmërim: Mund të ndodhë rritje e peshës trupore. Nuk është i përshtatshëm për fëmijë dhe të rinj. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve. Përmban kafeinë. Nuk rekomandohet për fëmijë ose gra shtatzëna (përmbajtja e kafeinës: 100 mg/6 g, 200 mg/12 g, 300 mg/18 g). Produkti nuk është i destinuar për gra që ushqejnë me gji, janë shtatzëna ose planifikojnë shtatzëni, në rast sëmundjesh të sistemit të qarkullimit të gjakut (p.sh. hipertension) ose në rast mbindjeshmërie ndaj ndonjë përbërësi të formulës. Mos e konsumoni në të njëjtën kohë ose në të njëjtën ditë me produkte të tjera që përmbajnë kafeinë (p.sh. suplemente të tjera ushqimore, kafe). Mos e tejkaloni marrjen ditore prej 400 mg kafeinë nga të gjitha burimet. Mos e përdorni para gjumit ose në orët menjëherë para gjumit. Mos e përdorni në kombinim me alkool. Disa persona mund të ndiejnë thumbim ose mpirje pas konsumimit. Ky është efekt i përkohshëm që i atribuohet veprimit të fortë të beta-alaninës. Nuk ndikon në shëndet. Përdorni një porcion të produktit (6 g) për të parandaluar simptomat. Në rast shfaqjeje të simptomave serioze, sidomos dobësi, shqetësim ose palpitacione, të cilat mund të shfaqen gjatë marrjes së porcioneve që përmbajnë 300 mg kafeinë (18 g produkt), përdorimi duhet të ndërpritet. Ngjitja e lejuar e produktit në gunga nuk ndikon në cilësinë e produktit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni porcionin prej 6 g në 100 ml ujë, porcionin prej 12 g në 200 ml ujë, porcionin prej 18 g në 300 ml ujë. Konsumojeni menjëherë pas përgatitjes.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2162;

-- Product_Id: 2163 (OLIMP R-WEILER FOCUS DRINK ZERO)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP R-WEILER FOCUS DRINK ZERO' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije energjike e gazuar me ekstrakt çaji jeshil Matcha, taurinë, kafeinë, vitaminë B6 dhe magnez</li><li>Për persona që kryejnë punë mendërisht të lodhshme që kërkon përqendrim dhe fokus</li><li>Pa sheqer, yndyrë dhe kripë, me vlerë të ulët kalorike</li><li>E përshtatshme për veganë</li></ul><p><strong>Pije energjike e gazuar me ekstrakt çaji jeshil – Matcha, taurinë, kafeinë natyrale, vitaminë B6 dhe magnez. Me ëmbëlsues. E pasterizuar.</strong></p><p><strong>Përmbajtje e lartë kafeine (30,3 mg/100 ml). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</strong></p><ul><li>Ideale për persona që studiojnë, kryejnë punë mendërisht të lodhshme, punonjës zyre, programues, lojtarë që kërkojnë përqendrim të lartë dhe sportistë</li><li>Përbërës me cilësi të lartë, të zgjedhur me kujdes në sasi të duhura</li><li>Pa sheqer, yndyrë dhe kripë</li><li>E përshtatshme për vegjetarianë dhe veganë</li><li>Pije energjike e shijshme dhe freskuese</li></ul><p><strong>VITAMINA B6 DHE MAGNEZI KONTRIBUOJNË NË:</strong></p><ul><li>Funksionimin normal të sistemit nervor (B6, Mg)</li><li>Metabolizmin normal energjetik (B6, Mg)</li><li>Uljen e lodhjes dhe rraskapitjes (B6)</li><li>Funksionin normal psikologjik (B6, Mg)</li></ul><p><strong>QËNDRONI TË FOKUSUAR DHE TREGONI POTENCIALIN TUAJ!</strong></p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 330 ml / 24 × 330 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kanaçe (330 ml).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Doza e rekomanduar ditore është 1 kanaçe. Servireni të ftohtë. Produkti është i destinuar për të rritur. Rekomandohet veçanërisht për persona me punë mendërisht të lodhshme, studentë, shoferë, lojtarë, sportistë amatorë dhe profesionistë, veganë dhe vegjetarianë.  PARALAJMËRIM: Përmban kafeinë. Nuk rekomandohet për fëmijë dhe gra shtatzëna [përmbajtja e kafeinës: 100 mg / dozë ditore (330 ml)]. Gjithashtu, produkti nuk duhet të përdoret gjatë ushqyerjes me gji dhe në rast intolerance ndaj ndonjë përbërësi. Nuk rekomandohet përdorimi i njëkohshëm i produkteve që përmbajnë kafeinë (p.sh. suplemente të tjera ushqimore, pije energjike, kafe). Mos e tejkaloni dozën ditore prej 400 mg kafeinë nga të gjitha burimet dhe 200 mg për marrje. Mos e konsumoni produktin menjëherë para gjumit. Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2163;

-- Product_Id: 2164 (OLIMP R-WEILER FOCUS, 300g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP R-WEILER FOCUS, 300g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Formulë pre-workout me kreatinë, kafeinë, aminoacide dhe ekstrakte bimore</li><li>Për rritjen e performancës fizike</li><li>25 porcione</li></ul><p><strong>Suplement ushqimor pluhur me ëmbëlsues. Përmban kafeinë. Nuk rekomandohet për fëmijë ose gra shtatzëna (150 mg/12 g).</strong></p><p>Nëse shpesh ndieni rënie energjie, vështirësi me përqendrimin ose fokusin në momente kyçe, <strong>R-Weiler Focus</strong> është formulë inovative e krijuar nga ekspertët e Olimp Laboratories për mbështetjen e performancës fizike dhe fokusit mendor.</p><p>Si pjesë e linjës unike <strong>Health Brain</strong>, R-Weiler Focus kombinon aminoacide si <strong>L-citrulina, L-arginina dhe taurina</strong>, kreatinë monohidrat, ekstrakte bimore nga <strong>Rhodiola rosea, Bacopa monnieri dhe Schisandra chinensis</strong>, të plotësuara me <strong>N-acetil-L-tirozinë, kafeinë dhe beta-alaninë</strong>.</p><p>Kombinimi i përbërësve të zgjedhur me kujdes dhe dozat e tyre të larta e bëjnë produktin të përshtatshëm për sportistë, persona fizikisht aktivë, persona që kryejnë punë intelektualisht të lodhshme, si dhe lojtarë dhe persona të tjerë për të cilët përqendrimi dhe marrja e shpejtë e vendimeve kanë rol të rëndësishëm.</p><p>R-Weiler Focus është zhvilluar me fokus në cilësinë dhe sigurinë. Përbërësit testohen për pastërti mikrobiologjike dhe praninë e metaleve të rënda në përputhje me standardet e Olimp Laboratories. Forma pluhur siguron tretshmëri të shkëlqyer dhe përgatitje të shpejtë.</p><p>R-Weiler Focus siguron:</p><ul><li><strong>3 g kreatinë</strong></li><li>L-argininë</li><li>L-citrulinë</li><li>N-acetil-L-tirozinë</li><li>Ekstrakt Rhodiola rosea</li><li>Ekstrakt Bacopa monnieri</li><li>Ekstrakt Schisandra chinensis</li><li>Kafeinë</li><li>Taurinë</li><li>Beta-alaninë</li></ul><p><em>Kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë.</em></p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 300 g (25 porcione)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse (12 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, rreth 30–60 minuta para stërvitjes. Konsumojeni menjëherë pas përgatitjes. Konsultohuni me mjekun tuaj para përdorimit. Paralajmërim: Përmban kafeinë. Nuk rekomandohet për fëmijë ose gra shtatzëna (përmbajtja e kafeinës: 150 mg/1 porcion). Përveç kësaj, produkti nuk duhet të përdoret gjatë ushqyerjes me gji, në rast sëmundjesh të sistemit të qarkullimit të gjakut ose në rast mbindjeshmërie ndaj ndonjë prej përbërësve të preparatit. Produkti nuk rekomandohet për persona me probleme me tensionin e gjakut. Mos e përdorni me barna, sidomos me barna që ndikojnë në sistemin kardiovaskular. Mos konsumoni njëkohësisht produkte të tjera që përmbajnë kafeinë (p.sh. suplemente të tjera ushqimore, pije energjike, kafe). Mos e tejkaloni marrjen ditore prej 400 mg kafeinë nga të gjitha burimet dhe 200 mg kafeinë në një dozë të vetme. Ngjitja e lejuar e produktit në gunga nuk ndikon në cilësinë e produktit. Mos e përdorni në kombinim me alkool. Mos e përdorni para gjumit ose në orët menjëherë para gjumit. Disa persona mund të ndiejnë thumbim ose mpirje pas konsumimit. Ky është efekt i përkohshëm që i atribuohet veprimit të fortë të beta-alaninës. Nuk ndikon në shëndet.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 250 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2164;

-- Product_Id: 2165 (OLIMP R-WEILER SHOT (NEW))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP R-WEILER SHOT (NEW)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pre-workout në shot praktik dhe të lehtë për përdorim</li><li>Tani në paketim qelqi ekologjik dhe të riciklueshëm</li><li>Për përqendrim, vigjilencë të shtuar dhe termogjenezë</li><li>Mbështetje e organizmit gjatë stërvitjeve intensive</li><li><strong>Përmbajtje e lartë kafeine (193 mg/20 ml)</strong></li><li>Pa konservues</li></ul><p><strong>Suplement ushqimor me beta-alaninë, taurinë, kafeinë, L-tirozinë dhe ekstrakt speci kajen. Me ëmbëlsues.</strong></p><p><strong>Përmban kafeinë (967 mg/100 ml; 193 mg në dozën ditore = 20 ml (2 × 10 ml)). Nuk rekomandohet për fëmijë ose gra shtatzëna.</strong></p><p>Ndonjëherë lodhja, rraskapitja dhe përqendrimi i ulët mund ta vështirësojnë kryerjen e një stërvitjeje të plotë dhe cilësore. Për situata të tilla, <strong>R-WEILER Shot</strong> ofron formulë të koncentruar pre-workout në formë praktike të lëngshme – tani në ampulë të re qelqi, ekologjike dhe të riciklueshme.</p><p><strong>R-WEILER Shot</strong> është suplement pre-workout në ampulë të vogël dhe praktike. Çdo ampulë përmban një kombinim të koncentruar përbërësish aktivë të njohur në sasi të zgjedhura me kujdes nga ekspertët e Olimp Laboratories.</p><p>Paketimi i ri prej qelqi ofron më shumë përparësi. Qelqi është <strong>i riciklueshëm, i papërshkueshëm dhe rezistent</strong>, ndërsa qelqi i errët ndihmon në mbrojtjen e përbërësve aktivë nga drita UV dhe kontribuon në ruajtjen e cilësisë së tyre.</p><p>Formula përmban <strong>beta-alaninë, taurinë, kafeinë, L-tirozinë dhe ekstrakt speci kajen</strong> dhe është zhvilluar për të rritur fizikisht aktivë, si për rekreativë ashtu edhe për sportistë që kërkojnë mbështetje shtesë gjatë stërvitjeve intensive.</p><p>Me <strong>R-WEILER® Shot</strong> merrni:</p><ul><li>Suplement praktik pre-workout në formë shot-i</li><li>Mbështetje për qëndrueshmërinë gjatë stërvitjes</li><li>Mbështetje për përqendrimin</li><li>Vigjilencë të shtuar</li><li>Mbështetje për termogjenezën</li></ul><p><strong>PËRPARËSITË E OLIMP R-WEILER® SHOT:</strong></p><ul><li><strong>Paketim qelqi</strong> – opsion ekologjik dhe i riciklueshëm me dizajn tërheqës, që ndihmon në ruajtjen e cilësisë së përbërësve aktivë</li><li><strong>Përdorim praktik</strong> – gati për konsum të drejtpërdrejtë; tundni ampulën, hapeni, matni porcionin dhe pijeni</li><li><strong>Formë e lëngshme</strong> për përdorim të shpejtë dhe praktik</li><li>Shije e shijshme dhe freskuese</li><li>Paketim kompakt që mbahet lehtë në çantën sportive ose në xhep</li><li>Lëndë të para me cilësi të lartë të testuara për pastërti mikrobiologjike dhe praninë e metaleve të rënda</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 60 ml / 9 × 60 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 10 ml.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Porcioni ditor i rekomanduar: 10 ml produkt 2 herë në ditë, afërsisht 30 minuta para stërvitjes. Përdorni gotën matëse që vjen me produktin për të matur një porcion (10 ml). Tundeni para përdorimit. 1 shishe përmban 6 porcione për 3 ditë përdorim. Pas hapjes, ruajeni në frigorifer në enë të mbyllur mirë dhe konsumojeni brenda 48 orëve. Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Rekomandohet ushqyerje e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve! PARALAJMËRIM: Përmban kafeinë; nuk rekomandohet për fëmijë ose gra shtatzëna (përmbajtja e kafeinës: 967 mg/100 ml; 193 mg/dozë ditore = 20 ml (2x10 ml); 97 mg/porcion i vetëm = 10 ml). PARALAJMËRIM: Nuk rekomandohet për gra që ushqejnë me gji, persona me sëmundje kardiovaskulare (sidomos sëmundje të zemrës), hipertension ose në rast mbindjeshmërie ndaj ndonjë prej përbërësve të produktit. Mos e konsumoni me produkte të tjera që përmbajnë kafeinë ose përbërës të tjerë me efekte të ngjashme (p.sh. suplemente të tjera ushqimore, pije energjike, kafe). Mos e tejkaloni marrjen prej 400 mg kafeinë në ditë dhe 200 mg kafeinë njëherësh nga të gjitha burimet. Mos e përdorni menjëherë para gjumit ose në disa orët para gjumit. Gëlltitja e produktit mund të shkaktojë thumbim ose mpirje të lehtë. Ky është simptomë e përkohshme e lidhur me efektet e forta të përbërësit beta-alaninë. Nuk ndikon në shëndet. Ndërprisni përdorimin në rast simptomash të tjera shqetësuese (sidomos nga sistemi kardiovaskular ose ngërçe muskulore), si dhe shqetësimi ose dobësie. Sedimenti dhe kristalizimi që mund të shfaqen janë dukuri natyrale dhe nuk ndikojnë në cilësinë e produktit. Ruajeni në vend të thatë, në temperaturë dhome, në paketim të mbyllur mirë. Mbrojeni nga drita e diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2165;

-- Product_Id: 2166 (OLIMP TAURINE MEGA CAPS 1500, 120 caps)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP TAURINE MEGA CAPS 1500, 120 caps' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>3000 mg taurinë në dozën ditore (2 kapsula)</li><li>Për të rritur fizikisht aktivë</li><li>60 ose 120 doza ditore</li></ul><p><strong>Suplement ushqimor me taurinë, në kapsula.</strong></p><p>OLIMP TAURINE Mega Caps siguron <strong>3000 mg taurinë në dozën ditore prej 2 kapsulash</strong>.</p><p>Produkti është i destinuar për <strong>të rritur fizikisht aktivë</strong>.</p><p><strong>Sasia neto:</strong> 120 kapsula</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1–2 kapsula, në varësi të intensitetit të përpjekjes.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, me sasi të madhe uji. PARALAJMËRIM: Gratë shtatzëna ose ato që ushqejnë me gji nuk duhet ta përdorin këtë produkt. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Produkti rekomandohet për të rritur si suplement ushqimor. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2166;

-- Product_Id: 2167 (OLIMP TRIBUSTERON 90, 120 caps)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP TRIBUSTERON 90, 120 caps' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Mbështet prodhimin natyral të testosteronit</li><li>Përmban 90% saponina</li><li>Mbështet forcën dhe kohë më të shkurtër rikuperimi</li><li>Mbështetje për funksionin seksual</li></ul><p><strong>Tribusteron 90</strong> përmban ekstrakt ujor pluhur nga Tribulus terrestris (<em>Tribulus terrestris L.</em>), të standardizuar me përmbajtje të lartë saponinash.</p><p>Tribulus terrestris përdoret tradicionalisht për mbështetjen e <strong>vitalitetit, tonusit muskulor dhe nivelit të energjisë</strong>. Përdoret gjithashtu si mbështetje për dëshirën seksuale dhe funksionin seksual.</p><p><strong>Tribusteron 90</strong> është i destinuar për persona fizikisht aktivë dhe sportistë që duan mbështetje shtesë për performancën fizike, vitalitetin dhe funksionin seksual.</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1–2 kapsula.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, më mirë në stomak bosh ose pas konsultimit me nutricionistin ose mjekun tuaj. Paralajmërim: Produkti rekomandohet për të rritur si suplement ushqimor. Mbajeni larg fëmijëve. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2167;

-- Product_Id: 2170 (OPTIMUM CREATINE POWDER, 317g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OPTIMUM CREATINE POWDER, 317g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Kreatinë monohidrat e mikronizuar me cilësi të lartë</li><li>Tretshmëri e shkëlqyer</li><li>Mbështet rritjen e forcës dhe performancës fizike</li><li>Pa aroma dhe shtesa</li><li>93 porcione</li></ul><p><strong>Suplement ushqimor me kreatinë monohidrat pluhur.</strong></p><p>Kreatinë monohidrat për mbështetjen e forcës, energjisë dhe performancës fizike gjatë stërvitjes.</p><p><strong>PËRFITIMET:</strong></p><ul><li>100% kreatinë monohidrat</li><li>Formë e mikronizuar</li><li>Tretshmëri e shkëlqyer në pije të ndryshme</li><li>Kreatina kontribuon në rritjen e performancës fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë</li><li>Pa aroma, mbushës dhe shtesa të tjera</li></ul><p>Efekti i dobishëm i kreatinës arrihet me marrje ditore prej <strong>3 g kreatinë</strong>.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 317 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse e rrafshët (3,4 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë. Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 240 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2170;

-- Product_Id: 2174 (PROTEINI.SI 100% PURE BIOTICS PRO, 30 caps)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI 100% PURE BIOTICS PRO, 30 caps' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>Suplement ushqimor me kultura mikrobiologjike</li><li>Në formë mikrokapsulash</li><li>Kombinim unik i 22 llojeve të ndryshme bakteriale</li><li>Çdo kapsulë përmban deri në <strong>18 miliardë kultura mikrobiologjike</strong></li></ul><p><strong>100% Pure Biotics Pro</strong> është suplement ushqimor në formë kapsulash që përmban 100% kultura mikrobiologjike të pastra.</p><p><strong>100% Pure Biotics Pro</strong> bazohet në një kombinim të <strong>22 llojeve të ndryshme të kulturave mikrobiologjike</strong>, kryesisht nga gjinitë Lactobacillus dhe Bifidobacterium:</p><p><em>Lactobacillus acidophilus, Lactobacillus bulgaricus, Lactobacillus casei, Lactobacillus plantarum, Lactobacillus brevis, Lactobacillus paracasei, Lactobacillus rhamnosus, Bifidobacterium breve, Bifidobacterium lactis, Bifidobacterium longum, Lactococcus lactis, Streptococcus thermophilus, Lactobacillus reuteri, Lactobacillus salivarius, Lactobacillus helveticus, Lactobacillus gasseri, Lactobacillus crispatus, Lactobacillus fermentum, Bifidobacterium infantis, Bifidobacterium bifidum, Bifidobacterium animalis, Pediococcus acidilactici.</em></p><p>Një kapsulë përmban deri në <strong>18 miliardë (18 × 10⁹ CFU) kultura mikrobiologjike</strong>. CFU (Colony Forming Units) tregon sasinë e mikroorganizmave të gjallë të aftë për të formuar koloni.</p><p>Në formulë janë shtuar edhe <strong>fruktooligosakaride dhe inulinë bimore</strong>, përbërës që nuk zbërthehen plotësisht në sistemin tretës dhe shërbejnë si ushqim për bakteret e dobishme në zorrën e trashë.</p><p><strong>KARAKTERISTIKAT SHTESË TË 100% PURE BIOTICS PRO:</strong></p><ul><li>Procesi i mikrokapsulimit kontribuon në mbrojtje më të mirë dhe mbijetesë të mikroorganizmave përgjatë traktit gastrointestinal</li><li>Produkt i qëndrueshëm dhe rezistent edhe kur ruhet në temperaturë dhome</li><li>I përshtatshëm për vegjetarianë dhe veganë</li><li>Pa OMGJ, SOJË, QUMËSHT dhe GLUTEN</li></ul><p><strong>RËNDËSIA E MIKROFLORËS SË SHËNDETSHME DHE FUNKSIONALE TË ZORRËVE</strong></p><p>Mikroflora e zorrëve është një bashkësi komplekse e një numri të madh mikroorganizmash, mes të cilëve edhe bakteret e acidit laktik si <em>Lactobacillus acidophilus</em> dhe <em>Bifidobacterium bifidum</em>.</p><p>Mikroflora e ekuilibruar e zorrëve ka rol të rëndësishëm në sistemin tretës dhe në zbërthimin e ushqimit. Bakteret e dobishme marrin pjesë në procese të ndryshme metabolike dhe kontribuojnë në ruajtjen e funksionit normal të traktit tretës.</p><p>Ekuilibri i mikroflorës së zorrëve mund të prishet nga faktorë të ndryshëm, si <strong>stresi, ushqyerja e paekuilibruar, ndryshimet në aktivitetin fizik dhe përdorimi i disa barnave</strong>, përfshirë antibiotikët.</p><p>Mikroorganizmat e zorrëve kanë rol të rëndësishëm edhe në krijimin e disa substancave në organizëm, përfshirë disa vitamina të grupit B dhe vitaminën K.</p><p>Kujdesi i rregullt për një ushqyerje të larmishme dhe të ekuilibruar, së bashku me ruajtjen e një mikroflore të shëndetshme të zorrëve, mund të jetë pjesë e rëndësishme e kujdesit të përgjithshëm për shëndetin tretës dhe mirëqenien.</p><p><strong>Sasia neto:</strong> 15 g (30 kapsula)</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, me ujë, lëng frutash ose lëng tjetër. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Suplementi ushqimor nuk është zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve! Ruajeni produktin në vend të thatë dhe të freskët dhe mos e ekspozoni ndaj dritës ose nxehtësisë së drejtpërdrejtë.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Pas hapjes, ruajeni në frigorifer dhe përdoreni brenda tre muajve.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2174;

-- Product_Id: 2175 (PROTEINI.SI 100% PURE CREATINE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI 100% PURE CREATINE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>100% kreatinë monohidrat</li><li>Për përmirësimin e performancës fizike</li><li>Rekomandohet veçanërisht gjatë aktivitetit fizik me intensitet të lartë</li></ul><p><strong>Kreatinë pluhur. Suplement ushqimor.</strong></p><p>Kreatina monohidrat është një nga format më të njohura dhe më të përdorura të kreatinës mes sportistëve.</p><p>Kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Efekti i dobishëm arrihet me marrje ditore prej <strong>3 g kreatinë</strong>.</p><p>Produkti është i destinuar për të rritur fizikisht aktivë që kryejnë stërvitje me intensitet të lartë.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 200 g (58 porcione)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 3,4 g (1 lugë matëse e plotë).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pini 1 porcion 20 minuta para stërvitjes. Në ditët kur nuk stërviteni, pijeni në mëngjes me stomak bosh. Doza maksimale ditore është 1 porcion (3,4 g). Produkti është i destinuar për të rritur që kryejnë ushtrime me intensitet të lartë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! RUAJTJA: Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 250 ml ujë të vakët.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2175;

-- Product_Id: 2176 (PROTEINI.SI 100% PURE GLUTAMINE, 200g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI 100% PURE GLUTAMINE, 200g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>100% L-glutaminë pluhur</li><li>5000 mg L-glutaminë për porcion</li><li>40 porcione</li></ul><p><strong>Suplement ushqimor me L-glutaminë, në formë pluhuri.</strong></p><p>L-glutamina është aminoacid proteinogjen, pra aminoacid që merr pjesë në krijimin e proteinave. Kryesisht sintetizohet dhe ruhet në muskujt skeletorë.</p><p>Nevoja për glutaminë mund të rritet në periudha stresi të shtuar fiziologjik, si dhe gjatë aktivitetit fizik intensiv.</p><p>Çdo porcion siguron:</p><ul><li><strong>5000 mg L-glutaminë</strong></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 200 g (40 porcione)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 5 g (1 lugë matëse).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion 2–3 herë në ditë – para mëngjesit, pas stërvitjes dhe para gjumit. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Suplementi ushqimor nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2176;

-- Product_Id: 2177 (PROTEINI.SI CREMRISO)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI CREMRISO' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>CremRiso – kënaqësi e re kremoze nga orizi!</strong></p><ul><li><strong>Natyrshëm i ëmbël</strong> – përmban vetëm sheqerna të pranishëm natyrshëm, pa sheqer të shtuar</li><li><strong>Burim energjie</strong> – mbi 85% karbohidrate dhe të paktën 8% proteina</li><li><strong>Përgatitje e shpejtë</strong> – vakt kremoz gati për vetëm pak minuta, pa gatim</li><li><strong>Zgjedhje e lehtë</strong> – me pak yndyrë, i përshtatshëm për veganë dhe natyrshëm pa laktozë</li><li><strong>Prodhuar në BE</strong> – zhvilluar dhe prodhuar në kapacitetet prodhuese të vetë Proteini.si</li></ul><p><strong>Shijoni një vakt të ngrohtë dhe kremoz për vetëm pak minuta!</strong></p><p><strong>CremRiso – vakt kremoz pluhur</strong></p><p><strong>Natyrshëm i ëmbël, pa sheqer të shtuar. Me ëmbëlsues.</strong></p><p>Shijoni një vakt të ngrohtë, kremoz dhe të shijshëm – pa sheqer të shtuar!</p><p>Ky vakt kremoz pluhur përgatitet shpejt dhe thjesht dhe është zgjedhje e shkëlqyer për <strong>mëngjes të shpejtë, vakt të lehtë ose rostiçeri praktike</strong>. Ka teksturë të butë dhe kremoze, përmban vetëm sheqerna të pranishëm natyrshëm dhe është ëmbëlsuar gjithashtu me sukralozë.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li><strong>Burim energjie</strong> – të paktën 85% karbohidrate dhe të paktën 8% proteina</li><li><strong>Pa sheqer të shtuar</strong> – përmban vetëm sheqerna të pranishëm natyrshëm, më pak se 1 g për 100 g</li><li><strong>Me pak yndyrë</strong> – më pak se 1 g</li><li><strong>Përgatitje e përshtatshme</strong> – mund të përzihet me ujë, qumësht ose pije bimore</li><li><strong>Gati për pak minuta</strong> – pa nevojë për gatim</li><li><strong>I përshtatshëm për veganë</strong></li><li><strong>Natyrshëm pa laktozë</strong></li><li><strong>Prodhuar në BE</strong> – zhvilluar dhe prodhuar në kapacitetet prodhuese të vetë Proteini.si</li></ul><p>CremRiso është <strong>krijuar duke marrë parasysh komentet tuaja</strong> nga ekspertët e Proteini.si dhe është prodhuar në kapacitetet tona prodhuese. Rezultati është <strong>produkt me cilësi të nivelit të lartë dhe raport të shkëlqyer çmim-cilësi</strong>.</p><p><strong>IDEAL PËR:</strong></p><ul><li>Mëngjes të shpejtë</li><li>Vakt të lehtë</li><li>Rostiçeri praktike në lëvizje</li><li>Ushqyerje me marrje të kontrolluar të sheqernave</li></ul><p>Kënaqni dëshirën për diçka kremoze dhe të shijshme në mënyrë të thjeshtë me <strong>CremRiso</strong>!</p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2–3 lugë (30–50 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni gjatë ditës. Ruajeni në vend të errët dhe të thatë në temperaturë nën 25°C.
Përzieni 30–50 g (2–3 lugë) pluhur në 200 ml ujë të ftohtë ose të ngrohtë, qumësht ose qumësht me origjinë bimore.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni (1–2 minuta) derisa të trashet.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2177;

-- Product_Id: 2178 (PROTEINI.SI ENERGY + ISOTONIC, 432g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ENERGY + ISOTONIC, 432g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije izotonike freskuese</li><li>Me elektrolite dhe vitaminë C</li><li>Nga përbërës me cilësi të lartë (Palatinose™, Aquamin™ Mg)</li><li>Pa ëmbëlsues dhe aroma artificiale</li><li>E disponueshme në 3 shije frutash me lëng</li><li>12 porcione</li></ul><p><strong>Suplement ushqimor pluhur për përgatitjen e pijes izotonike me karbohidrate lehtësisht të tretshme dhe elektrolite, i pasuruar me vitaminë C.</strong></p><p>Pijet izotonike janë zgjedhje e shkëlqyer për rimbushjen e shpejtë të lëngjeve të humbura gjatë aktivitetit fizik. Ato sigurojnë elektrolite që humbasin përmes djersitjes, si dhe karbohidrate që shërbejnë si burim energjie. Prandaj janë veçanërisht të dobishme për sportistë dhe persona fizikisht aktivë.</p><p><strong>PËRBËRJA:</strong></p><ul><li>Me elektrolite: magnez, kalcium, natrium dhe kalium, si dhe vitaminë C</li><li>Me karbohidrate me shpejtësi të ndryshme thithjeje dhe indeks glicemik – glukozë, maltodekstrinë dhe izomaltulozë (Palatinose™) – që sigurojnë energji edhe gjatë aktivitetit fizik të zgjatur</li><li>Izomaltuloza në formën e <strong>Palatinose™</strong> siguron të njëjtën vlerë energjetike si saharoza (4 kcal/g), por falë lidhjes specifike ndërmjet glukozës dhe fruktozës, energjia lirohet gradualisht dhe për një kohë më të gjatë</li><li>Me magnez shumë të biodisponueshëm nga algat e kuqe (<strong>Aquamin™ Mg</strong>)</li><li>Pa ëmbëlsues dhe aroma artificiale</li></ul><p><strong>PËRDORIMI:</strong></p><ul><li>Gjatë aktivitetit fizik të zgjatur dhe djersitjes intensive</li><li>Për persona fizikisht aktivë që duan të kujdesen për hidratimin dhe ekuilibrin e lëngjeve në organizëm</li><li>Për rimbushjen e ujit, energjisë dhe elektroliteve</li><li>Rekomandohet veçanërisht për sporte qëndrueshmërie</li><li>Përdorimi i rekomanduar: <strong>PARA dhe GJATË aktivitetit fizik</strong></li></ul><p><strong>PËRFITIMET:</strong></p><ul><li>Ndihmon në uljen e rrezikut të shfaqjes së ngërçeve muskulore</li><li>Magnezi kontribuon në ekuilibrin e elektroliteve</li><li>Kaliumi, kalciumi dhe magnezi kontribuojnë në funksionin normal të muskujve</li><li>Vitamina C kontribuon në funksionimin normal të sistemit imunitar dhe në uljen e lodhjes dhe rraskapitjes</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 432 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 36 g (2 lugë matëse të rrafshëta).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Përdoreni para dhe gjatë aktivitetit sportiv. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 500–600 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2178;

-- Product_Id: 2179 (PROTEINI.SI ENERGY+ JELLY BAR)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ENERGY+ JELLY BAR' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Burim i shpejtë energjie: 23 g karbohidrate për porcion</li><li>Rimbushje e elektroliteve: mbështetje për hidratimin dhe funksionin normal të muskujve</li><li>Formë praktike jelly bar: pa derdhje, pa rrëmujë dhe e lehtë për t’u konsumuar</li><li>Përdorim i larmishëm: ideale për stil jetese aktiv</li></ul><p><strong>Bar energjik jelly me elektrolite.</strong></p><p><strong>Proteini.si Energy+Jelly Bar</strong> kombinon praktikësinë e një rostiçerie të lëvizshme me përfitimet funksionale të karbohidrateve dhe elektroliteve. Me kombinimin e karbohidrateve dhe elektroliteve, bari është krijuar për rimbushje praktike të energjisë dhe lëngjeve gjatë një dite aktive ose aktiviteti fizik.</p><p><strong>ENERGJI E SHPEJTË DHE HIDRATIM</strong></p><ul><li><strong>Thithje e shpejtë:</strong> Forma jelly mundëson disponueshmëri të shpejtë të karbohidrateve dhe elektroliteve, gjë që e bën të përshtatshme për përdorim gjatë aktivitetit fizik intensiv ose pas përpjekjeve të zgjatura.</li><li><strong>Ekuilibër i elektroliteve:</strong> Ndihmon në rimbushjen e elektroliteve dhe lëngjeve të humbura gjatë aktivitetit fizik dhe djersitjes.</li></ul><p><strong>IDEALE NË LËVIZJE</strong></p><ul><li><strong>Formë praktike:</strong> Ndryshe nga pijet klasike sportive, bari jelly mbahet lehtë, nuk derdhet dhe nuk kërkon përgatitje.</li><li><strong>Kompakt dhe pa rrëmujë:</strong> Ndryshe nga xhelet e lëngshme, nuk kërkon shishe ose gotë dhe është praktik për t’u mbajtur gjatë stërvitjes, vrapimit, çiklizmit ose udhëtimit.</li></ul><p><strong>I SHIJSHËM DHE I LEHTË PËR T’U KONSUMUAR</strong></p><ul><li><strong>Teksturë e këndshme:</strong> Bari jelly ka teksturë të butë dhe elastike që ofron një mënyrë ndryshe dhe më interesante për marrjen e karbohidrateve dhe elektroliteve krahasuar me pijet dhe pluhurat klasikë.</li></ul><p><strong>IDEAL PËR STIL JETESE AKTIV</strong></p><ul><li><strong>Para, gjatë ose pas aktivitetit fizik:</strong> Forma praktike mundëson përdorim para stërvitjes, gjatë aktiviteteve më të gjata si vrapimi ose çiklizmi, ose pas aktivitetit fizik.</li><li><strong>Mbështetje për qëndrueshmërinë dhe performancën:</strong> Siguron elektrolite të rëndësishme si natriumi, kaliumi, magnezi dhe kalciumi, të cilët kanë rol të rëndësishëm në funksionin normal të muskujve dhe ruajtjen e ekuilibrit të elektroliteve.</li></ul><p><strong>PËRDORIM I LARMISHËM</strong></p><ul><li>I përshtatshëm për sportistë dhe persona fizikisht aktivë</li><li>Praktik për vrapues, çiklistë, triatlonistë, entuziastë të fitnesit, alpinistë dhe persona të tjerë me stil jetese aktiv</li><li>Mund të përdoret si burim energjie para stërvitjes, gjatë aktivitetit fizik më të gjatë, pas stërvitjes ose si rostiçeri praktike gjatë udhëtimit</li><li>I përshtatshëm edhe për situata kur nevojitet rimbushje e shpejtë e energjisë dhe elektroliteve</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 30 g / 20 × 30 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 bar jelly (30 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni para dhe gjatë aktivitetit fizik sipas nevojave tuaja energjetike. Produkti është i destinuar për përdorim të menjëhershëm pas hapjes.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Ruajeni në vend të thatë, larg nxehtësisë dhe dritës së drejtpërdrejtë të diellit.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2179;

-- Product_Id: 2180 (PROTEINI.SI ENERGY BAR)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ENERGY BAR' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Bar tërshëre me përmbajtje të lartë fibrash, fruta dhe fruta të thata</li><li>Rostiçeri e shkëlqyer për të gjithë me stil jetese aktiv</li><li>Burim energjie afatgjatë</li><li>Lehtësisht i tretshëm</li><li>PA GLUTEN</li><li>Bar prej 60 g</li></ul><p><strong>Bar tërshëre me përmbajtje të lartë fibrash. Pa gluten.</strong></p><p><strong>PROTEINI.SI ENERGY BAR</strong> është bar tërshëre i butë dhe me lëng, me fruta dhe fruta të thata të zgjedhura me kujdes. Është i disponueshëm në dy shije të shijshme dhe është i veshur me çokollatë qumështi ose glazurë jogurti.</p><p>Përbën burim praktik energjie për të gjithë ata që duan të ruajnë nivelin e energjisë gjatë aktivitetit fizik. Është ideal për çiklistë, vrapues, triatlonistë, alpinistë, futbollistë dhe të gjithë sportistët e tjerë që kanë nevojë për burim praktik energjie gjatë aktivitetit.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li>Burim karbohidratesh komplekse me lirim gradual</li><li>Siguron energji afatgjatë nga tërshëra dhe yndyrat</li><li>Zgjedhje e shkëlqyer para stërvitjes ose si rostiçeri energjike gjatë ditës</li><li>Zgjedhje e shkëlqyer për rimbushjen e rezervave të energjisë gjatë aktiviteteve më të gjata të qëndrueshmërisë</li><li>Përmbajtja e lartë e fibrave kontribuon në tretje më të mirë</li><li>Pa gluten</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 60 g / 20 × 60 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Nuk është i destinuar për fëmijë nën 3 vjeç. Pas hapjes, produkti është i destinuar për përdorim të menjëhershëm. Ruajeni larg nxehtësisë, ngricës dhe lagështisë.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2180;

-- Product_Id: 2181 (PROTEINI.SI ENERGY+ SUPERCHARGED ENERGY DRINK)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ENERGY+ SUPERCHARGED ENERGY DRINK' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije shumë e koncentruar me karbohidrate dhe elektrolite</li><li>88 g karbohidrate për porcion</li><li>Raporti maltodekstrinë : fruktozë = 1 : 0,8</li><li>Kombinim i avancuar i elektroliteve</li><li>Mbështetje për performancën fizike dhe rikuperimin</li><li>15 porcione</li></ul><p><strong>Suplement ushqimor me sheqerna për përgatitjen e pijes me bazë karbohidratesh dhe elektrolitesh.</strong></p><p><strong>Supercharged Energy Drink Powder</strong> është pluhur për përgatitjen e pijes, i destinuar për rimbushjen e shpejtë të rezervave energjetike dhe elektroliteve të humbura gjatë aktivitetit fizik.</p><p>Formula bazohet në <strong>maltodekstrinë dhe fruktozë në raport 1 : 0,8</strong>, kombinim që mundëson marrje efikase të karbohidrateve gjatë aktiviteteve sportive të zgjatura.</p><p><strong>PËRPARËSITË E RAPORTIT 1 : 0,8 MALTODEKSTRINË : FRUKTOZË</strong></p><p><strong>Thithje më efikase e karbohidrateve</strong></p><p>Maltodekstrina thithet përmes SGLT1 – transportues i varur nga natriumi, ndërsa fruktoza thithet përmes GLUT5. Kombinimi në raport 1 : 0,8 mundëson përdorimin e njëkohshëm të të dy mekanizmave të transportit dhe marrje më të madhe totale të karbohidrateve gjatë aktivitetit fizik të zgjatur.</p><p><strong>Tolerancë më e mirë gastrointestinale</strong></p><p>Marrja e tepërt e glukozës ose maltodekstrinës pa fruktozë mund ta mbingarkojë transportuesin SGLT1. Shtimi i fruktozës në sasi të duhur mundëson që një pjesë e karbohidrateve të thithet përmes një mekanizmi tjetër transporti.</p><p><strong>Furnizim i shpejtë dhe i zgjatur me energji</strong></p><p>Kombinimi i burimeve të ndryshme të karbohidrateve siguron furnizim të shpejtë dhe të zgjatur me energji gjatë aktivitetit fizik.</p><p><strong>Rimbushja e rezervave të glikogjenit</strong></p><p>Fruktoza kontribuon kryesisht në rimbushjen e glikogjenit në mëlçi, ndërsa glukoza e përftuar nga maltodekstrina është e rëndësishme për rimbushjen e glikogjenit muskulor.</p><p><strong>Hidratimi dhe thithja e lëngjeve</strong></p><p>Maltodekstrina ka osmolalitet relativisht të ulët, gjë që e bën të përshtatshme për përdorim në pijet sportive. Në kombinim me sasinë e duhur të fruktozës, formula është e destinuar për furnizim efikas me lëngje, karbohidrate dhe elektrolite.</p><p><strong>ELEKTROLITE TË SHTUARA</strong></p><p><strong>Mbështetje e hidratimit</strong></p><p>Elektrolitet si <strong>natriumi, kaliumi, magnezi dhe kalciumi</strong> kanë rol të rëndësishëm në ruajtjen e ekuilibrit të lëngjeve në organizëm, sidomos gjatë aktivitetit fizik të zgjatur dhe djersitjes intensive.</p><p>Natriumi ndihmon në mbajtjen e lëngjeve, kaliumi kontribuon në funksionimin normal të muskujve dhe sistemit nervor, ndërsa magnezi dhe kalciumi marrin pjesë në funksionin normal muskulor.</p><p><strong>Mbështetje për qëndrueshmërinë dhe performancën fizike</strong></p><p>Karbohidratet sigurojnë energji gjatë aktivitetit fizik, ndërsa elektrolitet kontribuojnë në funksionin normal të muskujve dhe sistemit nervor.</p><p><strong>Mbështetje gjatë aktivitetit fizik të zgjatur</strong></p><p>Duke rimbushur karbohidratet dhe elektrolitet, pija është e përshtatshme për përdorim gjatë stërvitjeve më të gjata dhe sporteve të qëndrueshmërisë.</p><p><strong>Rimbushja e natriumit dhe lëngjeve</strong></p><p>Gjatë aktivitetit fizik afatgjatë dhe djersitjes së bollshme, marrja vetëm e ujit mund të mos jetë e mjaftueshme për rimbushjen e elektroliteve të humbura. Formula siguron edhe natrium dhe minerale të tjera të rëndësishme.</p><p><strong>Mbështetje për përqendrimin gjatë stërvitjes</strong></p><p>Ruajtja e hidratimit të duhur dhe e ekuilibrit të elektroliteve është e rëndësishme edhe për funksionimin normal të sistemit nervor dhe përqendrimin.</p><p><strong>Mbështetje për rikuperimin</strong></p><p>Pas aktivitetit fizik, kombinimi i karbohidrateve dhe elektroliteve ndihmon në rimbushjen e rezervave energjetike dhe lëngjeve të humbura gjatë stërvitjes.</p><p><strong>PËRDORIMI</strong></p><p>Pija rekomandohet veçanërisht për sporte qëndrueshmërie si <strong>çiklizmi, vrapimi, triatloni dhe aktivitete të tjera fizike të zgjatura</strong>, ku është e rëndësishme rimbushja e rregullt e karbohidrateve, lëngjeve dhe elektroliteve.</p><ul><li><strong>Gjatë aktivitetit fizik të zgjatur (&gt;1,5 orë):</strong> ndihmon në ruajtjen e rezervave energjetike. Në sportet e qëndrueshmërisë shpesh përdoret marrja e 60–90 g karbohidrateve në orë, me afërsisht 55% maltodekstrinë dhe 45% fruktozë.</li><li><strong>Pas aktivitetit fizik:</strong> mund të përdoret për rimbushjen e rezervave të glikogjenit dhe elektroliteve, sidomos kur kryhen disa stërvitje në një periudhë të shkurtër kohore.</li></ul><p><em>Rekomandohet ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</em></p><p><strong>E rëndësishme:</strong> Produkti dhe sasia e konsumuar duhet të testohen fillimisht gjatë stërvitjes, jo për herë të parë në garë, sepse toleranca individuale ndaj fruktozës mund të ndryshojë.</p><p><strong>Sasia neto:</strong> 1500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 100 g (3 lugë matëse).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni para dhe gjatë aktivitetit sportiv intensiv. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, larg nxehtësisë dhe dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 500–600 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2181;

-- Product_Id: 2182 (PROTEINI.SI MAGNESIUM)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI MAGNESIUM' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije e çastit pluhur me vitamina dhe minerale</li><li>Magnez + Kalium + Vitaminë C + Vitaminë B6</li><li>Paketim praktik për përdorim të vetëm, ideal në lëvizje</li><li>Për sportistë, persona fizikisht aktivë dhe persona me ushqyerje të paekuilibruar</li></ul><p><strong>Pije e çastit pluhur me magnez, kalium, vitaminë C dhe vitaminë B6. Suplement ushqimor me sheqerna dhe ëmbëlsues.</strong></p><p>Magnezi në formë pluhuri për përgatitjen e një pijeje freskuese është mënyrë e shpejtë dhe praktike për plotësimin e marrjes ditore të magnezit.</p><p>Magnezi është mineral esencial që në organizëm gjendet kryesisht në kocka, qelizat muskulore dhe gjak. Është veçanërisht i rëndësishëm për sportistë dhe persona fizikisht aktivë, dhe mund të jetë i dobishëm edhe për persona me ushqyerje të paekuilibruar.</p><p>Magnezi në <strong>PROTEINI.SI MAGNESIUM</strong> është në formë të <strong>citratit të magnezit</strong>. Kjo është formë organike e magnezit që tolerohet mirë dhe është lehtësisht e disponueshme për organizmin.</p><p>Pluhuri është paketuar në qeskë praktike për përdorim të vetëm, ideale në lëvizje ose gjatë udhëtimit.</p><p>Një qeskë prej 15 g <strong>PROTEINI.SI MAGNESIUM</strong> siguron:</p><ul><li>50% të marrjes ditore të referencës së magnezit (Mg)</li><li>100% të marrjes ditore të referencës së vitaminës C</li><li>50% të marrjes ditore të referencës së vitaminës B6</li><li>15% të marrjes ditore të referencës së kaliumit (K)</li></ul><p><strong>MAGNEZI KONTRIBUON NË:</strong></p><ul><li>Uljen e lodhjes dhe rraskapitjes</li><li>Ekuilibrin e elektroliteve</li><li>Metabolizmin normal energjetik</li><li>Funksionimin normal të sistemit nervor</li><li>Funksionin normal të muskujve</li><li>Funksionin normal psikologjik</li><li>Ruajtjen e kockave dhe dhëmbëve normalë</li><li>Sintezën normale të proteinave</li><li>Procesin normal të ndarjes qelizore</li></ul><p><strong>VITAMINA C KONTRIBUON NË:</strong></p><ul><li>Krijimin normal të kolagjenit për funksionin normal të kockave, kërcit, lëkurës, dhëmbëve, mishrave të dhëmbëve dhe enëve të gjakut</li><li>Funksionimin normal të sistemit imunitar</li><li>Mbrojtjen e qelizave nga stresi oksidativ</li></ul><p><strong>VITAMINA B6 KONTRIBUON NË:</strong></p><ul><li>Metabolizmin normal të proteinave dhe glikogjenit</li><li>Krijimin normal të qelizave të kuqe të gjakut</li><li>Rregullimin e aktivitetit hormonal</li></ul><p><strong>KALIUMI KONTRIBUON NË:</strong></p><ul><li>Funksionimin normal të sistemit nervor</li><li>Funksionin normal të muskujve</li><li>Ruajtjen e tensionit normal të gjakut</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 10 × 15 g / 15 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 15 g (1 qeskë).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Doza maksimale ditore është 15 g. Doza e rekomanduar ditore nuk duhet të tejkalohet. PARALAJMËRIM: Nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe stil jetese të shëndetshëm. Produkti nuk është i përshtatshëm për fëmijë deri në 12 vjeç. Mbajeni larg fëmijëve! Ruajeni produktin larg nxehtësisë, ngricës dhe lagështisë.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni porcionin me 250 ml ujë. Konsumojeni menjëherë pas përgatitjes.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2182;

-- Product_Id: 2183 (PROTEINI.SI MUFFIN)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI MUFFIN' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Mafin me proteina</li><li>Rostiçeri e shijshme që mund ta shijoni pa brejtje ndërgjegjeje, në çdo kohë dhe kudo</li><li>13 g proteina për 100 g</li><li>I disponueshëm në dy shije të parezistueshme</li></ul><p><strong>Mafin me proteina me sheqer dhe ëmbëlsues. Me përmbajtje të ulët sheqernash. Burim proteinash.</strong></p><p>Provoni një kënaqësi të ëmbël e të shijshme me <strong>burim të ekuilibruar proteinash dhe fibrash</strong>, ideale si rostiçeri e shpejtë dhe praktike që mund ta keni gjithmonë pranë.</p><p>Përshtatet shkëlqyeshëm në një stil jetese aktiv dhe të ekuilibruar, sepse përmban <strong>më pak sheqerna dhe më shumë proteina krahasuar me një mafin tradicional</strong>, gjë që e bën zgjedhje praktike për çdo ditë.</p><p><strong>Sasia neto:</strong> 50 g / 7 × 50 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Paralajmërim: Konsumimi i tepërt mund të shkaktojë efekte laksative.' ELSE InstructionsForUseAl END
WHERE Product_Id = 2183;

-- Product_Id: 2184 (PROTEINI.SI NATURAL BCAA, 200g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI NATURAL BCAA, 200g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Aminoacide natyrale BCAA në raport 2:1:1</li><li>Pa aroma artificiale, ngjyrues dhe përforcues shijeje</li><li>E ëmbëlsuar me ëmbëlsues nga bima stevia dhe sukralozë</li></ul><p><strong>Aminoacide BCAA pluhur, me ëmbëlsues.</strong></p><p><strong>AMINOACIDE NATYRALE BCAA ME SHIJE FREKSUESE FRUTASH</strong></p><p><strong>PROTEINI.SI NATURAL BCAA</strong> përmban kompleks aminoacidesh me zinxhir të degëzuar – <strong>L-leucinë, L-valinë dhe L-izoleucinë – në raport 2:1:1</strong>. Produkti është i destinuar mbi të gjitha për sportistë dhe persona fizikisht aktivë që praktikojnë aktivitete të ndryshme sportive dhe rekreative.</p><p>Formula dallohet për përdorimin e përbërësve natyralë – janë shtuar vetëm aroma natyrale, pa ngjyrues të shtuar. Prandaj, kur përzihet me ujë, pija mbetet e tejdukshme.</p><p><strong>PËRFITIMET:</strong></p><ul><li>Pa aroma artificiale</li><li>Pa ngjyrues</li><li>Pa gluten</li><li>E ëmbëlsuar me ëmbëlsues nga bima stevia dhe sukralozë</li><li>E përshtatshme për vegjetarianë</li><li>Paketim praktik prej 200 g</li></ul><p>E disponueshme në <strong>tri shije frutash të shijshme dhe freskuese</strong>.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 200 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 6,5 g (1/2 lugë matëse).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1–3 porcione në ditë – para vaktit ose stërvitjes dhe pas stërvitjes ose para gjumit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 300 ml ujë dhe tundeni fuqishëm.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2184;

-- Product_Id: 2186 (PROTEINI.SI OAT CAKE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI OAT CAKE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p>&nbsp;Energjia jote gjithmonë pranë</p><p>Ndiej energjinë natyrale të tërshërës integrale – e pasur me <strong>karbohidrate me lirim gradual për energji të qëndrueshme dhe afatgjatë</strong>, që të mbetesh i fokusuar dhe gati për çdo sfidë.</p>Energji kur të duhet më shumë!<p>Fibra natyrale, shije të shkëlqyera dhe burim praktik energjie për çdo pjesë të ditës – qoftë për një <strong>fillim energjik të ditës</strong>, një <strong>rostiçeri pasditeje</strong> apo <strong>energji për stërvitje</strong>. Merre me vete dhe shijoje kudo dhe kurdo që të duash!</p>Shije e shkëlqyer për të gjithë që janë vazhdimisht në lëvizje!<p>Zgjidh një nga katër shijet e parezistueshme: <strong>Çokollatë &amp; Banane</strong>, <strong>Jogurt Kremoz</strong>, <strong>Toffee Karamel</strong> dhe <strong>Dubai Choco</strong>.</p><p><strong>OAT CAKE</strong> është bar tërshëre i shijshëm që ndihmon të ndiheni të ngopur dhe siguron burim energjie më afatgjatë.</p><p>Është ideal si rostiçeri ndërmjet vakteve ose gjatë aktiviteteve sportive.</p><p>Dallohet për shijen e shkëlqyer dhe përmbajtjen e pasur me karbohidrate, gjë që e bën zgjedhje praktike edhe gjatë aktivitetit fizik.</p><p>Është i disponueshëm në katër variante të shijshme – <strong>çokollatë &amp; banane</strong> klasike, <strong>jogurt</strong> freskues, <strong>karamel</strong> i ëmbël dhe <strong>Dubai Choco</strong> mbresëlënës.</p><ul><li>Rostiçeri e shijshme e bërë nga thekon tërshëre integrale</li><li>Rostiçeri praktike për çdo pjesë të ditës</li><li>Burim fibrash dhe karbohidratesh komplekse</li><li>Rostiçeri ushqyese dhe ngopëse</li><li>Për energji më afatgjatë</li><li>I disponueshëm në katër shije</li></ul><p><strong>Sasia neto:</strong> 60 g / 20 × 60 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Produkti është i destinuar për përdorim të menjëhershëm pas hapjes. Nuk është i destinuar për fëmijë nën 3 vjeç. Ruajeni në vend të thatë në temperaturë dhome, larg lagështisë, dritës së drejtpërdrejtë të diellit dhe nxehtësisë.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2186;

-- Product_Id: 2187 (PROTEINI.SI OMEGA-3)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI OMEGA-3' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Përmban vaj peshku MEG-3® me cilësi të lartë, të pastër dhe të përftuar në mënyrë të qëndrueshme</li><li>MEG-3® është burim i sigurt i acideve yndyrore Omega-3 (EPA + DHA)</li><li>EPA dhe DHA kontribuojnë në funksionin normal të zemrës, ndërsa DHA kontribuon në ruajtjen e funksionit normal të trurit dhe shikimit</li><li>Kapsula të buta nga xhelatinë viçi</li><li>120 porcione</li></ul><p><strong>Suplement ushqimor. Acide yndyrore Omega-3 nga vaj peshku MEG-3® me cilësi të lartë.</strong></p><p><strong>MEG-3®</strong> siguron vaj peshku me cilësi të lartë, të pastër dhe të përftuar në mënyrë të qëndrueshme, me përmbajtje të standardizuar të acideve yndyrore Omega-3, ndër të cilat më të rëndësishmet janë DHA (acidi dokozaheksaenoik) dhe EPA (acidi eikozapentaenoik).</p><p><strong>MEG-3®</strong> është burim i besueshëm i acideve yndyrore Omega-3 shumë të koncentruara nga vaji i peshkut. Peshqit që përdoren për prodhimin e MEG-3® sigurohen nga zona peshkimi të rregulluara, ku zbatohen praktika dhe procedura të përshtatshme për mbrojtjen e burimeve të peshkut. Mbetjet nga përpunimi i vajit të peshkut përdoren gjithashtu për prodhimin e biokarburantit.</p><p>Vaji i peshkut MEG-3® përftohet nga peshq të vegjël oqeanikë nga rajone të ndryshme të botës. Vaji pastrohet me qëllim uljen e nivelit tashmë të ulët të ndotësve të mundshëm mjedisorë, dhe më pas koncentrohet për të siguruar përmbajtje të lartë të <strong>EPA dhe DHA</strong>. Falë procesit të pastrimit, MEG-3® siguron përfitimet e vajit të peshkut pa erë ose shije të theksuar peshku.</p><ul><li><strong>DHA kontribuon në ruajtjen e funksionit normal të trurit dhe shikimit normal.</strong> Efekti i dobishëm arrihet me marrje ditore prej 250 mg DHA.</li><li><strong>EPA dhe DHA kontribuojnë në funksionin normal të zemrës.</strong> Efekti i dobishëm arrihet me marrje ditore prej 250 mg EPA dhe DHA.</li></ul><p>Acidet yndyrore Omega-3 konsiderohen acide yndyrore esenciale, që do të thotë se organizmi nuk mund t’i prodhojë vetë në sasi të mjaftueshme, prandaj duhet të merren përmes ushqyerjes.</p><p>Burimet natyrale më të pasura me Omega-3 janë peshqit e yndyrshëm si toni, salmoni, skumbri, trofta dhe sardelet. Nëse marrja përmes ushqyerjes është e pamjaftueshme, <strong>PROTEINI.SI OMEGA-3</strong> përbën mënyrë praktike për plotësimin e marrjes ditore të acideve yndyrore Omega-3.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 205,47 g (120 kapsula të buta)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kapsulë e butë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë me shumë ujë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Mbajeni larg fëmijëve! Ruajeni në enë të mbyllur në temperaturë dhome dhe larg dritës së drejtpërdrejtë të diellit.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2187;

-- Product_Id: 2188 (PROTEINI.SI PEANUT BUTTER (NEW))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PEANUT BUTTER (NEW)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Krem kikiriku i bërë nga 100% kikirikë të pjekur</li><li>Burim proteinash</li><li>Përmbajtje e lartë fibrash</li><li>Pa vaj palme dhe sheqerna të shtuar</li><li>Pa konservues të shtuar</li><li>Tani me teksturë edhe më krokante</li></ul><p><strong>Gjalpë kikiriku. Tani edhe më krokant dhe më i shijshëm! Në paketim të ri me kapak me vidë.</strong></p><p><strong>Proteini.si Peanut Butter</strong> është bërë nga 100% kikirikë të pjekur, të cilët janë burim natyral i acideve yndyrore të pangopura.</p><p>Gjalpi i kikirikut është ushqim ushqyes që siguron energji dhe është i përshtatshëm për të gjithë ata që duan të ruajnë një ushqyerje të ekuilibruar dhe stil jetese të shëndetshëm. Zëvendësimi i yndyrave të ngopura me yndyra të pangopura në ushqyerje kontribuon në ruajtjen e nivelit normal të kolesterolit në gjak, ndërsa ulja e marrjes së natriumit kontribuon në ruajtjen e tensionit normal të gjakut.</p><p><strong>Proteini.si Peanut Butter</strong> dallohet për shijen e shkëlqyer dhe teksturën krokante. Mund të përdoret si krem për lyerje, të shtohet në fruta, shejk proteinik para ose pas stërvitjes, ose thjesht të hahet drejtpërdrejt nga kavanozi.</p><p>Proteini.si Peanut Butter përmban <strong>26 g proteina për 100 g</strong>. Proteinat kontribuojnë në rritjen dhe ruajtjen e masës muskulore.</p><p><strong>PËRFITIMET:</strong></p><ul><li>100% kikirikë të pjekur</li><li>Burim proteinash – 26 g për 100 g</li><li>Përmbajtje e lartë fibrash</li><li>Pa vaj palme të shtuar</li><li>Pa sheqer të shtuar (**përmban sheqerna të pranishëm natyrshëm)</li><li>Teksturë krokante</li><li>Pa konservues të shtuar</li><li>I përshtatshëm për vegjetarianë dhe veganë</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 1000 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'PARALAJMËRIM: Shtresa e vajit në sipërfaqe të produktit është e natyrshme te gjalpi i kikirikut. Përzieni para përdorimit. Ruajeni në temperaturë deri në 25°C. Ruajeni në vend të thatë, larg dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2188;

-- Product_Id: 2189 (PROTEINI.SI PEANUT BUTTER (NEW), 300g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PEANUT BUTTER (NEW), 300g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Krem kikiriku i bërë nga 100% kikirikë të pjekur</li><li>Burim proteinash</li><li>Përmbajtje e lartë fibrash</li><li>Pa vaj palme dhe sheqerna të shtuar</li><li>Pa konservues të shtuar</li><li>Tani me teksturë edhe më krokante</li><li>Në paketim më të vogël qelqi</li></ul><p><strong>Gjalpë kikiriku. Tani edhe më krokant dhe më i shijshëm, i disponueshëm në kavanoz qelqi prej 300 g!</strong></p><p><strong>Proteini.si Peanut Butter</strong> është bërë nga 100% kikirikë të pjekur, të cilët janë burim natyral i acideve yndyrore të pangopura.</p><p>Gjalpi i kikirikut është ushqim ushqyes që siguron energji dhe është i përshtatshëm për të gjithë ata që duan të ruajnë një ushqyerje të ekuilibruar dhe stil jetese të shëndetshëm. Zëvendësimi i yndyrave të ngopura me yndyra të pangopura në ushqyerje kontribuon në ruajtjen e nivelit normal të kolesterolit në gjak, ndërsa ulja e marrjes së natriumit kontribuon në ruajtjen e tensionit normal të gjakut.</p><p><strong>Proteini.si Peanut Butter</strong> dallohet për shijen e shkëlqyer dhe teksturën krokante. Mund të përdoret si krem për lyerje, të shtohet në fruta, shejk proteinik para ose pas stërvitjes, ose thjesht të hahet drejtpërdrejt nga kavanozi.</p><p>Proteini.si Peanut Butter përmban <strong>26 g proteina për 100 g</strong>. Proteinat kontribuojnë në rritjen dhe ruajtjen e masës muskulore.</p><p><strong>PËRFITIMET:</strong></p><ul><li>100% kikirikë të pjekur</li><li>Burim proteinash – 26 g për 100 g</li><li>Përmbajtje e lartë fibrash</li><li>Pa vaj palme të shtuar</li><li>Pa sheqer të shtuar (**përmban sheqerna të pranishëm natyrshëm)</li><li>Plotësisht natyral</li><li>Teksturë krokante</li><li>Pa konservues të shtuar</li><li>I përshtatshëm për vegjetarianë dhe veganë</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 300 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'PARALAJMËRIM: Shtresa e vajit në sipërfaqe të produktit është e natyrshme te gjalpi i kikirikut. Përzieni para përdorimit. Ruajeni në temperaturë deri në 25°C. Ruajeni në vend të thatë, larg dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2189;

-- Product_Id: 2190 (PROTEINI.SI ENERGY+ ENERGY GEL)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ENERGY+ ENERGY GEL' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Xhel energjik me lirim gradual</li><li>Energji afatgjatë për qëndrueshmëri më të madhe</li><li>Lehtësisht i tretshëm</li><li>I pasuruar me vitamina</li><li>Nuk nevojitet ujë shtesë</li><li>Me kafeinë (shija Cola) ose pa kafeinë (shijet Citrus dhe Raspberry)</li></ul><p><strong>Suplement ushqimor me sheqer dhe ëmbëlsues, i pasuruar me vitamina.</strong></p><p>Xheli energjik është burim i koncentruar energjie që mundëson rimbushje praktike të energjisë së humbur gjatë stërvitjes ose garës.</p><p><strong>PROTEINI.SI ENERGY+ ENERGY GEL</strong> është xhel energjik me lirim gradual, që mundëson furnizim më afatgjatë me energji. Struktura e tij e lëngshme mundëson konsumim të lehtë pa ujë shtesë.</p><p>Formula bazohet në <strong>maltodekstrinë</strong>, burim karbohidratesh që mundëson furnizim të shpejtë dhe praktik me energji gjatë aktivitetit fizik.</p><p><strong>PËRBËRJA:</strong></p><ul><li>Burim i koncentruar energjie në formë karbohidrati kompleks – maltodekstrinë (38%)</li><li>I pasuruar me vitamina të grupit B dhe vitaminat C dhe E</li><li>Shija Cola përmban kafeinë (75 mg/60 g)</li></ul><p><strong>PËRDORIMI:</strong></p><ul><li>Gjatë aktivitetit fizik të zgjatur</li><li>Për rimbushjen e energjisë së humbur</li><li>Rekomandohet veçanërisht për sporte qëndrueshmërie</li><li>Përdorimi i rekomanduar: <strong>PARA dhe GJATË aktivitetit fizik</strong></li></ul><p><strong>PËRFITIMET:</strong></p><ul><li>Ndihmon në rimbushjen e energjisë së humbur gjatë aktivitetit fizik të zgjatur dhe intensiv</li><li>Lirim gradual i energjisë</li><li>Vitamina C kontribuon në funksionimin normal të sistemit imunitar, ndërsa vitaminat e grupit B dhe vitamina C kontribuojnë në uljen e lodhjes dhe rraskapitjes</li><li>Vitaminat C dhe E kontribuojnë në mbrojtjen e qelizave nga stresi oksidativ</li><li>Nuk nevojitet ujë shtesë</li><li>I butë për stomakun</li><li>Shije e shkëlqyer</li></ul><p><strong>Sasia neto:</strong> 60 g / 18 × 60 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 60 g (1 xhel).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni para dhe gjatë aktivitetit fizik, në varësi të nevojave tuaja energjetike. Pas hapjes, produkti është i destinuar për përdorim të menjëhershëm.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2190;

-- Product_Id: 2193 (PROTEINI.SI PROTEIN CHOCOTELLA, 450g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PROTEIN CHOCOTELLA, 450g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Krem kremoz me kakao dhe kikirikë</li><li>Pa kripë të shtuar dhe pa sheqer të shtuar</li><li>Shije e shkëlqyer</li><li>Burim proteinash</li></ul><p><strong>Gjalpë kikiriku me kakao, me ëmbëlsues.</strong></p><ul><li>Pa sheqer të shtuar. Përmban sheqerna të pranishëm natyrshëm.</li><li>Pa kripë të shtuar.</li><li>I ëmbëlsuar me glikozide steviole dhe ksilitol.</li></ul><p><strong>Chocotella</strong> është bërë nga kikirikë me cilësi të lartë që zgjidhen me kujdes, piqen dhe kombinohen me kakao pluhur të shijshme. Për ëmbëlsi shtesë janë shtuar ksilitol dhe glikozide steviole nga stevia.</p><p>Përveç shijes së shkëlqyer, <strong>Chocotella</strong> ka edhe përbërje të pasur ushqyese. Përmban <strong>21 g yndyra të mononangopura për 100 g</strong>, si dhe <strong>17 g proteina</strong> dhe <strong>6,5 g fibra për 100 g</strong>. Kikirikët natyrshëm përmbajnë yndyra të mononangopura, si dhe vitamina dhe minerale të ndryshme.</p><p><strong>PËRFITIMET:</strong></p><ul><li>E bërë nga përbërës natyralë</li><li>E pasur me yndyra të mononangopura</li><li>Ushqyese</li><li>Burim proteinash – 17 g proteina për 100 g</li><li>Përmbajtje e lartë fibrash – 6,5 g për 100 g</li><li>8,9 g sheqerna për 100 g</li><li>Përmbajtje shumë e ulët kripe – 0,02 g për 100 g</li><li>Pa konservues dhe aroma të shtuara</li><li>Pa vaj palme të shtuar</li></ul><p><strong>Chocotella</strong> mund të konsumohet gjatë ditës, por për shkak të vlerës më të lartë energjetike rekomandohet përdorim i moderuar.</p><p>Është e shkëlqyer për të gjithë adhuruesit e kombinimit të kikirikëve me kakaon. Mund të përdoret si krem për lyerje mbi bukë të thekur, petulla, vafle, mafina, kroasanë ose të shtohet në qull tërshëre.</p><p><strong>Sasia neto:</strong> 450 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Mund të ndodhë ndarja e vajit; përzieni para përdorimit.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Ruajeni në vend të freskët dhe të thatë. Nxehtësia dhe drita e diellit mund ta dëmtojnë paketimin!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2193;

-- Product_Id: 2195 (PROTEINI.SI PROTEIN DONUT)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PROTEIN DONUT' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Donati i ri dhe edhe më i shijshëm me proteina Proteini.si</li><li>Pa vaj palme dhe yndyra trans</li><li>Përmbajtje e ulët sheqernash</li><li>13 g proteina për 100 g</li><li>3 shije</li></ul><p><strong>Donat me proteina me sheqerna dhe ëmbëlsues.</strong></p><p><strong>Donati me proteina Proteini.si</strong>, edhe më i shijshëm, i butë dhe me lëng, i bashkohet familjes së rostiçerive Proteini.si pa brejtje ndërgjegjeje.</p><p>Donatët me proteina po bëhen gjithnjë e më të popullarizuar te personat fizikisht aktivë, sportistët dhe njerëzit që ndjekin ushqyerje me marrje të kufizuar të karbohidrateve dhe sheqernave.</p><p>I bërë me të bardhë veze dhe miell gruri e tërshëre, donati Proteini.si është rostiçeri praktike dhe ushqyese, e përshtatshme si për mëngjes ashtu edhe si rostiçeri e ëmbël gjatë ditës.</p><p>Nuk përmban vaj palme, yndyra trans dhe kolesterol, dhe njëkohësisht është burim proteinash, të cilat kontribuojnë në rritjen dhe ruajtjen e masës muskulore.</p><ul><li>218/239 kcal për porcion (1 donat)</li><li>13% proteina</li><li>Përmbajtje e ulët sheqernash</li><li>0% yndyra trans dhe kolesterol</li><li>Pa vaj palme</li><li>I disponueshëm në 3 variante të shijshme: <strong>Black Cookie &amp; Speculoos Cream, Dark Chocolate &amp; Hazelnut Cream dhe Triple Chocolate</strong></li></ul><p><strong>Sasia neto:</strong> 60 g / 15 × 60 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'I pahapur, ruajeni në vend të freskët dhe të thatë, larg nxehtësisë dhe dritës së drejtpërdrejtë të diellit. Konsumojeni menjëherë pas hapjes.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2195;

-- Product_Id: 2196 (PROTEINI.SI PROTEIN MUESLI, 250g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PROTEIN MUESLI, 250g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Musli me përmbajtje të lartë proteinash dhe fibrash</li><li>Proteina nga burime bimore (bizele, grurë)</li><li>22 g proteina për 100 g</li><li>8,8 g fibra për 100 g</li></ul><p><strong>Musli me përmbajtje të lartë proteinash dhe fibrash.</strong></p><p>Musli me proteina Proteini.si përmban <strong>22% proteina me origjinë bimore</strong> (izolat proteine bizeleje dhe koncentrat proteine gruri) dhe përbën <strong>burim të shkëlqyer proteinash.</strong></p><p>Sipas marrjes së referencës (<strong>MRD</strong>) për një të rritur mesatar (8400 kJ/2000 kcal), <strong>100 g produkt sigurojnë deri në 45% të marrjes së referencës së proteinave</strong> (si dhe 18% karbohidrate, 17% yndyrë dhe 12% sheqerna). Produkti ka gjithashtu <strong>përmbajtje të lartë fibrash</strong> – 8,8 g për 100 g produkt.</p><ul><li>Proteinat kontribuojnë në ruajtjen dhe rritjen e masës muskulore dhe në ruajtjen e kockave normale.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p>E disponueshme në variantet e shijshme <strong>çokollatë-karamel</strong> dhe <strong>çokollatë e bardhë-mjedër</strong>.</p><p>Musli mund ta shijoni në çdo kohë të ditës – për mëngjes, si rostiçeri ose si vakt i shpejtë. Mund ta konsumoni me qumësht, pije bimore ose në kombinim tjetër sipas dëshirës dhe shijes suaj.</p><p><strong>Sasia neto:</strong> 250 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Përzieni me qumësht, pije me origjinë bimore ose produkte qumështi dhe hani për mëngjes etj.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2196;

-- Product_Id: 2206 (PROTEINI.SI PROTEIN PANCAKES)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PROTEIN PANCAKES' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Petulla me përmbajtje të lartë proteinash</li><li>Përgatitje e shpejtë dhe e thjeshtë</li><li>Ushqyese dhe të shijshme</li><li>Me copa të vërteta luleshtrydheje</li><li>8 porcione</li></ul><p><strong>Përzierje për petulla me përmbajtje të lartë proteinash. Suplement ushqimor me ëmbëlsues.</strong></p><p>Ju prezantojmë petullat tona me proteina me shije luleshtrydheje dhe çokollate të bardhë!</p><p>Filloni ditën me shije me petullat tona me përmbajtje të lartë proteinash, të krijuara për shije të shkëlqyer dhe përdorim praktik.</p><p><strong>PSE TË ZGJIDHNI PETULLAT TONA ME PROTEINA?</strong></p><ul><li><strong>30% proteina:</strong> Çdo porcion përmban 30% proteina, të përshtatshme për marrje shtesë të proteinave gjatë ditës.</li><li><strong>Copa të vërteta luleshtrydheje:</strong> Shijoni copa të vërteta luleshtrydheje në çdo kafshatë, që japin ëmbëlsi natyrale dhe teksturë të shkëlqyer.</li><li><strong>Shije luleshtrydheje dhe çokollate të bardhë:</strong> Kombinimi i përsosur i luleshtrydhes me lëng dhe çokollatës së bardhë kremoze.</li><li><strong>Përgatitje e shpejtë dhe praktike:</strong> Gati për vetëm pak minuta – ideale për mëngjeset e ngarkuara, pas stërvitjes ose si rostiçeri e shijshme dhe ushqyese.</li><li><strong>Të bëra nga përbërës të zgjedhur me kujdes:</strong> Pa aroma artificiale dhe pa mbushës të panevojshëm.</li></ul><p><strong>IDEALE PËR:</strong></p><ul><li>Persona fizikisht aktivë që duan të rrisin marrjen e proteinave</li><li>Njerëz të zënë që kanë nevojë për vakt të shpejtë dhe ushqyes</li><li>Këdo që dëshiron mëngjes ose rostiçeri të shijshme me përbërje të mirë ushqyese</li></ul><p><strong>MËNYRA E PËRGATITJES:</strong></p><p>Thjesht përzieni masën, piqeni në tigan të nxehur dhe shërbejeni me shtesat tuaja të preferuara – fruta të freskëta, jogurt, pak mjaltë ose gjalpë frutash të thata.</p><p><strong>Sasia neto:</strong> 300 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 37 g (1 lugë matëse).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, larg burimeve të nxehtësisë dhe dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 1/2 lugë matëse ujë ose qumësht, përzieni mirë dhe piqeni në tigan të nxehur derisa petullat të marrin ngjyrë të artë-kafe.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2206;

-- Product_Id: 2207 (PROTEINI.SI PROTEIN PORRIDGE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PROTEIN PORRIDGE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Qull tërshëre me përmbajtje të lartë proteinash dhe fibrash</li><li>Rostiçeri e shkëlqyer gati për vetëm 2 minuta</li><li>15 g proteina për porcion</li><li>Me vitamina D dhe K të shtuara</li><li>PA GLUTEN</li></ul><p><strong>Qull me proteina me mjedra të liofilizuara dhe fara chia (<em>Salvia hispanica</em>), me vitamina të shtuara.</strong></p><p>Qulli i shijshëm me proteina përmban deri në <strong>30% proteina</strong> (izolat proteine qumështi), është i pasur me fibra dhe nuk përmban gluten. Për më tepër, është i pasuruar me dy vitamina të rëndësishme – <strong>vitaminën K dhe vitaminën D</strong>.</p><p>I shpejtë dhe i thjeshtë për t’u përgatitur, është ideal si mëngjes i pasur me proteina, rostiçeri e shijshme ndërmjet vakteve ose si vakt pas stërvitjes. Mjafton të shtoni ujë dhe qulli është gati për vetëm <strong>2 minuta</strong>. Sipas dëshirës, mund ta përgatitni edhe me qumësht, jogurt, pije tërshëre, bajameje ose soje.</p><p>I disponueshëm në 2 variante të shijshme: <strong>mjedër dhe çokollatë</strong>.</p><p><strong>PROTEINAT</strong></p><ul><li>Përmbajtje e lartë proteinash – 30% proteina (izolat proteine qumështi)</li><li>Proteinat kontribuojnë në rritjen dhe ruajtjen e masës muskulore</li></ul><p><strong>VITAMINA D</strong></p><ul><li>Kontribuon në ruajtjen e kockave dhe dhëmbëve normalë</li><li>Kontribuon në thithjen normale të kalciumit dhe fosforit</li><li>Kontribuon në funksionin normal të muskujve</li><li>Kontribuon në ruajtjen e nivelit normal të kalciumit në gjak</li></ul><p><strong>VITAMINA K</strong></p><ul><li>Kontribuon në mpiksjen normale të gjakut</li><li>Kontribuon në ruajtjen e kockave normale</li></ul><p><strong>KALCIUMI</strong></p><ul><li>Nevojitet për ruajtjen e kockave dhe dhëmbëve normalë</li><li>Kontribuon në funksionin normal të muskujve</li></ul><p><strong>FIBRAT</strong></p><ul><li>Përmbajtje e lartë fibrash – 10 g për 100 g</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 50 g / 5 × 50 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 50 g (1 qeskë).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Hajeni për mëngjes, si rostiçeri gjatë ditës ose pas aktivitetit fizik. Pas hapjes, produkti është i destinuar për konsumim të menjëhershëm. Rekomandohet të konsumohen maksimumi 2 porcione në ditë. PARALAJMËRIM: Nuk është i destinuar për fëmijë nën 3 vjeç. Mbajeni larg fëmijëve! Ruajeni në vend të thatë dhe larg dritës së drejtpërdrejtë të diellit dhe nxehtësisë. Mos e ngrini.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Vendosni përmbajtjen e qeskës në një enë servirjeje, shtoni 100 ml ujë të ngrohtë (jo të vluar) dhe përzieni mirë. Për përgatitje mund të përdorni edhe ujë të ftohtë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2207;

-- Product_Id: 2214 (PROTEINI.SI VIT. C (1000mg) + VIT. D3, 60 таблети за џвакање)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI VIT. C (1000mg) + VIT. D3, 60 tableta për përtypje' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><p></p><p></p><p></p><ul><li><p></p><p></p><p>Vitaminë C + vitaminë D3 + ekstrakt trëndafili të egër</p><p></p><p></p></li><li><p></p><p></p><p>Përbërësit aktivë kontribuojnë në funksionin normal të sistemit imunitar dhe në ruajtjen e kockave dhe dhëmbëve të shëndetshëm</p><p></p><p></p></li><li><p></p><p></p><p>Tableta për përtypje me shije portokalli</p><p></p><p></p></li><li><p></p><p></p><p>Pa ngjyrues dhe aroma artificiale</p><p></p><p></p></li><li><p></p><p></p><p>60 porcione</p><p></p><p></p></li></ul><p>Suplement ushqimor me vitaminë C, i pasuruar me vitaminë D3 dhe ekstrakt trëndafili të egër, me ëmbëlsues. Me shije portokalli. Pa ngjyrues dhe aroma artificiale.</p><p>Ky suplement ushqimor në formë tabletash për përtypje me shije portokalli përmban kombinim të dozave të larta të vitaminave C dhe D3 dhe ekstrakt trëndafili të egër. Këta përbërës veprojnë në mënyrë sinergjike dhe kanë ndikim pozitiv në sistemin imunitar dhe shëndetin e kockave dhe dhëmbëve.</p><p>PROTEINI.SI VIT. C (1000MG) + VIT. D3 përmban:</p><ul><li><p></p><p></p><p>1000 mg vitaminë C</p><p></p><p></p></li><li><p></p><p></p><p>50 μg (2000 IU) vitaminë D3</p><p></p><p></p></li><li><p></p><p></p><p>25 mg ekstrakt trëndafili të egër</p><p></p><p></p></li></ul><p>Vitamina C kontribuon në:</p><ul><li><p></p><p></p><p>Ruajtjen e funksionit normal të sistemit imunitar gjatë dhe pas aktivitetit fizik intensiv. Efekti i dobishëm arrihet me marrje ditore prej 200 mg, përveç marrjes ditore të rekomanduar të vitaminës C.</p><p></p><p></p></li><li><p></p><p></p><p>Krijimin normal të kolagjenit për funksionin normal të enëve të gjakut, kockave, kërcit, mishrave të dhëmbëve, lëkurës dhe dhëmbëve.</p><p></p><p></p></li><li><p></p><p></p><p>Funksionin normal të sistemit imunitar.</p><p></p><p></p></li><li><p></p><p></p><p>Mbrojtjen e qelizave nga stresi oksidativ.</p><p></p><p></p></li><li><p></p><p></p><p>Metabolizmin normal për prodhimin e energjisë.</p><p></p><p></p></li><li><p></p><p></p><p>Funksionin normal të sistemit nervor.</p><p></p><p></p></li><li><p></p><p></p><p>Funksionin normal psikologjik.</p><p></p><p></p></li><li><p></p><p></p><p>Uljen e lodhjes dhe rraskapitjes.</p><p></p><p></p></li></ul><p>Vitamina D kontribuon në:</p><ul><li><p></p><p></p><p>Funksionin normal të sistemit imunitar.</p><p></p><p></p></li><li><p></p><p></p><p>Ruajtjen e funksionit normal të muskujve.</p><p></p><p></p></li><li><p></p><p></p><p>Ruajtjen e kockave dhe dhëmbëve të shëndetshëm.</p><p></p><p></p></li></ul><p>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</p><p>Sasia neto: 60 tableta për përtypje (126,6 g)</p><p></p><p></p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 tabletë për përtypje.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'MËNYRA E PËRDORIMIT:

- Madhësia e dozës: 1 tabletë për përtypje.
- Merrni 1 tabletë për përtypje në ditë.
- Përtypeni mirë tabletën para se ta gëlltisni.

PARALAJMËRIM:

Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni produktin si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!

Përdorimi i tepërt mund të ketë efekt laksativ për shkak të përmbajtjes së sorbitolit.

Produkti nuk rekomandohet në rast tensioni të lartë të gjakut, përqendrimi të rritur të kalciumit në urinë ose gurëve në veshka.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2214;

-- Product_Id: 2215 (PROTEINI.SI VITAMIN D3 (2000IU), 100 меки капсули)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI VITAMIN D3 (2000IU), 100 kapsula të buta' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>2000 IU vitaminë D për kapsulë</p></li><li><p>Vitamina D3 kontribuon në ruajtjen e kockave dhe dhëmbëve të shëndetshëm dhe në funksionin normal të sistemit imunitar</p></li><li><p>Rekomandohet veçanërisht gjatë vjeshtës dhe dimrit</p></li><li><p>100 porcione</p></li></ul><p><strong>Suplement ushqimor me vitaminë D3 në kapsula të buta.</strong></p><p>Vitamina D është vitaminë e tretshme në yndyrë, që luan rol të rëndësishëm në zhvillimin e kockave dhe dhëmbëve, si dhe në funksionimin e sistemit imunitar. PROTEINI.SI VITAMIN D3 në kapsula të buta siguron 50 μg (2000 IU) vitaminë D3 për kapsulë.</p><p>Vitamina D krijohet në lëkurë gjatë ekspozimit ndaj dritës së diellit ose mund të merret përmes ushqyerjes. Megjithatë, meqë përmbajtja e vitaminës D në ushqim është relativisht e vogël, dhe gjithnjë e më shumë njerëz e shmangin ekspozimin ndaj diellit, rekomandohet marrje shtesë e vitaminës D në formë suplementesh ushqimore. Kjo është veçanërisht e rëndësishme gjatë vjeshtës dhe dimrit, kur sinteza e vitaminës D në lëkurë nuk është mjaftueshëm efikase.</p><p>Vitamina D kontribuon në:</p><ul><li><p>thithjen dhe shfrytëzimin normal të kalciumit dhe fosforit</p></li><li><p>nivelin normal të kalciumit në gjak</p></li><li><p>ruajtjen e kockave normale</p></li><li><p>ruajtjen e funksionit normal të muskujve</p></li><li><p>ruajtjen e dhëmbëve normalë</p></li><li><p>funksionin normal të sistemit imunitar</p></li><li><p>procesin e ndarjes qelizore</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 100 kapsula të buta (46 g)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 kapsulë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'MËNYRA E PËRDORIMIT:

- Madhësia e dozës: 1 kapsulë.
- Merrni 1 dozë në ditë me vakt.

PARALAJMËRIM:

Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni produktin si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!

Produkti nuk rekomandohet në rast tensioni të lartë të gjakut, përqendrimi të rritur të kalciumit në urinë ose gurëve në veshka.

Gjatë përdorimit të këtij suplementi ushqimor, duhet të merret parasysh edhe marrja e vitaminës D nga burime të tjera.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2215;

-- Product_Id: 2216 (PROTEINI.SI VITAMINS, MINERALS & OMEGA 3, 30 tabs + 30 caps)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI VITAMINS, MINERALS & OMEGA 3, 30 tableta + 30 kapsula' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Kombinim i shkëlqyer vitaminash dhe mineralesh</p></li><li><p>Vaj peshku shumë i koncentruar</p></li><li><p>Për persona fizikisht aktivë dhe të gjithë me stil jetese të shpejtë</p></li><li><p>Ndikim pozitiv në zemër dhe sistemin e qarkullimit të gjakut</p></li></ul><p><strong>Vitamina dhe minerale në tableta (30 tableta) dhe vaj peshku omega-3 në kapsula (30 kapsula). Suplement ushqimor.</strong></p><p><strong>PROTEINI.SI VITAMINS, MINERALS &amp; OMEGA 3</strong> ofron kombinim kompleks vitaminash, mineralesh dhe acidesh yndyrore omega-3. Këta përbërës të zgjedhur me kujdes i sigurojnë trupit mikronutrientët esencialë më të rëndësishëm, të cilët ndihmojnë në ruajtjen e rezistencës së organizmit dhe kontribuojnë në gjendje më të mirë fizike, mirëqenie dhe vitalitet.</p><p>Acidet yndyrore EPA dhe DHA janë acide yndyrore omega-3 që kanë ndikim pozitiv në shëndetin e sistemit kardiovaskular dhe të qarkullimit të gjakut, funksionet njohëse dhe shikimin. Prandaj është e rëndësishme që të merren rregullisht përmes ushqyerjes.</p><ul><li><p>Vitaminat A, C, D, B6 dhe B12 dhe mineralet bakër, zink, folat, selen dhe hekur kontribuojnë në funksionin normal të sistemit imunitar.</p></li><li><p>Vitaminat C, E dhe B2 dhe mineralet bakër, zink, mangan dhe selen kontribuojnë në mbrojtjen e qelizave nga stresi oksidativ.</p></li><li><p>Vitaminat C, B2, B6, B12, folati dhe niacina, si dhe mineralet magnez dhe hekur, kontribuojnë në uljen e lodhjes dhe rraskapitjes.</p></li><li><p>Acidi eikozapentaenoik (EPA) dhe acidi dokozaheksaenoik (DHA) kontribuojnë në funksionin normal të zemrës. Efekti i dobishëm arrihet me marrje ditore prej 250 mg EPA dhe DHA.</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 99,5 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza e rekomanduar ditore: 1 kapsulë dhe 1 tabletë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, gjatë ditës, me ushqim dhe lëng. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet! Suplementi ushqimor nuk është zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2216;

-- Product_Id: 2217 (PROTEINI.SI ZERO SYRUP, 320ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ZERO SYRUP, 320ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shurup çokollate me vlerë të ulët kalorike</p></li><li><p>Shije e shkëlqyer</p></li><li><p>Pa yndyrë dhe pa sheqer</p></li><li><p>Pa laktozë dhe pa gluten</p></li><li><p>I përshtatshëm për veganë</p></li></ul><p><strong>Shurup çokollate me energji të ulët, pa sheqer, me ëmbëlsues.</strong></p><p>Proteini.si Zero Syrup është shurup i shijshëm çokollate që mund ta shtoni në çdo vakt që dëshironi ta ëmbëlsoni dhe t’i jepni pak shije çokollate, pa brejtje ndërgjegjeje dhe pa u shqetësuar për numrin e kalorive, sepse ky shurup praktikisht nuk përmban kalori! Mund ta përdorni me shejke, smoothie, produkte qumështi, akullore, petulla, drithëra e të ngjashme. Shurupi përmban më pak se 0,5 g sheqer dhe 0,1 g yndyrë për 100 ml.</p><ul><li><p>Për t’u dhënë shije ëmbëlsirave</p></li><li><p>I përsosur gjatë dietës</p></li><li><p>Ideal për ushqyerje me pak kalori, sheqer dhe yndyrë</p></li><li><p>Shije e shijshme çokollate</p></li><li><p>I përshtatshëm për veganë</p></li><li><p>32 porcione</p></li></ul><p>Një porcion prej 10 ml praktikisht nuk përmban kalori, sepse ka vlerë energjetike të papërfillshme prej 0,9 kcal, prandaj produkti bën pjesë në kategorinë e produkteve me pothuajse zero kalori.</p><p>Sportistët dhe personat që kujdesen për linjën e tyre dhe duan të shtojnë shurupe në produkte qumështi, drithëra ose vakte proteinike, mund ta shijojnë këtë salcë pa brejtje ndërgjegjeje, sepse pothuajse nuk ndikon në marrjen totale të kalorive. Edhe sportistët që ndjekin dietë shumë strikte mund ta shijojnë këtë salcë ëmbëlsire pa asnjë shqetësim.</p><p>Përparësia e Proteini.si Zero Syrup nuk është vetëm vlera e ulët kalorike, por edhe shija e shkëlqyer! Provojeni!</p><p><strong>Sasia neto:</strong> 320 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Paralajmërim: Konsumimi i tepërt mund të ketë efekt laksativ. Produktin e pahapur ruajeni në vend të freskët dhe të thatë. Pas hapjes, ruajeni në frigorifer dhe përdoreni brenda një muaji. Tundeni mirë para përdorimit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2217;

-- Product_Id: 2218 (PROTEINI.SI ZINC, 100 таблети)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ZINC, 100 tableta' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>25 mg zink për kapsulë (250% MRD)</p></li><li><p>Supermineral që merr pjesë në shumë procese të metabolizmit qelizor</p></li><li><p>Për rezistencën e organizmit dhe kocka të shëndetshme</p></li><li><p>Përmban glukonat zinku me cilësi të lartë</p></li><li><p>100 porcione</p></li></ul><p><strong>Suplement ushqimor me zink në tableta.</strong></p><p>Zinku është element esencial që është i rëndësishëm për rritjen dhe zhvillimin normal të organizmit, funksionet neurologjike dhe riprodhuese, shërimin e plagëve dhe funksionimin normal të sistemit imunitar. PROTEINI.SI ZINC në formë tabletash siguron 25 mg zink për kapsulë, që përbën 250% të marrjes së referencës ditore (MRD).</p><p>Burime të pasura me zink janë gocat e detit, mishi, frutat e detit, bishtajoret, frutat e thata dhe farat e ndryshme. Shumica e njerëzve me ushqyerje të larmishme dhe të ekuilibruar mund t’i plotësojnë nevojat për zink. Megjithatë, vegjetarianët duhet t’i kushtojnë vëmendje të veçantë marrjes së mjaftueshme të tij. Meqë organizmi nuk ka aftësi të ruajë zinkun, është e rëndësishme të konsumohen rregullisht ushqime që janë burim i tij ose të sigurohet marrje e duhur përmes suplementeve ushqimore.</p><p>Zinku merr pjesë në shumë procese të metabolizmit qelizor. Është i përfshirë në më shumë se 100 reaksione enzimatike në organizëm dhe luan rol të rëndësishëm në funksionimin e sistemit imunitar, sintezën e proteinave, shërimin e plagëve, mbrojtjen e qelizave nga stresi oksidativ, metabolizmin e makronutrientëve dhe vitaminës A, funksionet njohëse, sintezën e ADN-së dhe ndarjen qelizore. Zinku ka rol të rëndësishëm në rritjen dhe zhvillimin e organizmit, është i domosdoshëm për funksionimin normal të shqisave të shijes dhe nuhatjes dhe ndihmon në ruajtjen e kockave të shëndetshme, shikimit normal, flokëve, thonjve dhe lëkurës së shëndetshme. Gjithashtu merr pjesë në ruajtjen e nivelit normal të testosteronit në gjak dhe kontribuon në pjellorinë dhe funksionet riprodhuese.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 100 tableta (46 g)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 tabletë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë me vakt. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2218;

-- Product_Id: 2219 (RABEKO NON-STICK ZERO COOKING SPRAY)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'RABEKO NON-STICK ZERO COOKING SPRAY' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Vajra në spërkatës me pak kalori, pa sheqer dhe jashtëzakonisht të shijshëm</li><li>Të përshtatshëm për ushqyerje të shëndetshme</li><li>Përdorim i shpejtë, i thjeshtë dhe i pastër</li><li>2 kcal për porcion</li><li>200 ml</li></ul><p><strong>Vaj për gatim dhe erëza në formë spërkatësi.</strong></p><p>Rabeko ju ofron produkte me pak kalori që sjellin më shumë shije në kuzhinën tuaj ose gjatë përgatitjes së ushqimit në skarë. Provoni këta spërkatës të shijshëm, të krijuar për përdorim praktik dhe të kontrolluar në ushqyerjen e përditshme, të disponueshëm në disa variante të shijshme.</p><p><strong>PËRPARËSITË:</strong></p><ul><li>Pak kalori, shije e pasur</li><li>Përdorim i shpejtë dhe i thjeshtë, pa ngjitje</li><li>Dozim praktik për kontroll më të mirë të marrjes</li><li>I shkëlqyer për pjekje, skuqje, gatime në furrë ose sallata</li><li>Katër variante të shijshme – Natural, Garlic, Butter dhe Italian Herbs</li></ul><p><strong>Sasia neto:</strong> 200 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 0,3 ml.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'- Mënyra e përdorimit:
  1. Tundeni lehtë shishen para përdorimit.
  2. Spërkatni rreth 1/3 sekonde nga një distancë prej afërsisht 20 cm mbi ushqimin ose sipërfaqen e ftohtë.

RREZIK:
Enë nën presion. Mund të plasë nëse nxehet. Aerosol jashtëzakonisht i ndezshëm.

Mbajeni larg fëmijëve.
Mbajeni larg nxehtësisë, sipërfaqeve të nxehta, shkëndijave, flakës së hapur dhe burimeve të tjera të ndezjes.
Ndalohet duhani.
Mos spërkatni mbi flakë të hapur ose burim tjetër ndezjeje.
Mos e shponi dhe mos e digjni enën, as pas përdorimit.
Mbrojeni nga drita e diellit.
Mos e ekspozoni ndaj temperaturave mbi 50°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2219;

-- Product_Id: 2223 (USN ATOM BOMB INTENSE PRE-WORKOUT)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN ATOM BOMB INTENSE PRE-WORKOUT' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Nxitje energjie + fokus + stimulim para stërvitjes</p></li><li><p>Me aminoacide, vitamina dhe xhensen</p></li><li><p>200 mg kafeinë për porcion</p></li><li><p>Pa sheqer</p></li></ul><p><strong>Suplement ushqimor me vitamina, aminoacide dhe ekstrakte bimore, me ëmbëlsues.</strong></p><p><strong>Përmbajtje e lartë kafeine (200 mg/60 ml). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</strong></p><p>USN Atom Bomb është shot intensiv para stërvitjes, ideal për ata që duan të përmirësojnë stërvitjen e tyre dhe të nxjerrin maksimumin nga çdo seancë stërvitore.</p><p>Përmban 200 mg kafeinë, 2000 mg beta-alaninë, 2000 mg L-argininë, 1000 mg citrulinë dhe 200 mg L-tirozinë.</p><p>Pa sheqer, gluten dhe laktozë.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 60 ml / 12 × 60 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza e rekomanduar: 1 shishe (60 ml).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 1 porcion (60 ml) për një goditje energjie me kafeinë dhe pa sheqer, që do t’ju ndihmojë të mbështetni stilin e ngarkuar të jetesës. Mos tejkaloni 1 porcion në ditë. Paralajmërim: Përmbajtje e lartë kafeine (200 mg/60 ml). Nuk rekomandohet për fëmijë ose gra shtatzëna ose gra që ushqejnë me gji. Mos tejkaloni 400 mg kafeinë në ditë nga të gjitha burimet (200 mg/ditë për gra shtatzëna ose gra që ushqejnë me gji). Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2223;

-- Product_Id: 2224 (USN B4-BOMB)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN B4-BOMB' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement para stërvitjes i shpërblyer shumë herë</p></li><li><p>Me kafeinë, beta-alaninë, Rhodiola rosea, citrulinë, Zynamite® dhe Bacowize®</p></li><li><p>Me vitamina të grupit B</p></li><li><p>Qëndrueshmëri, energji dhe fokus gjatë stërvitjes</p></li><li><p>12 porcione</p></li></ul><p><strong>Suplement ushqimor me aminoacide, ekstrakte bimore, kafeinë dhe vitamina, me ëmbëlsues.</strong></p><p><strong>Përmbajtje e lartë kafeine (200 mg/15 g; 400 mg/30 g). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</strong></p><p>Përjetoni energji shpërthyese dhe teknologjinë RawPower™¹ me suplementin para stërvitjes USN B4-BOMB. Sfidoni veten dhe arrini performancë maksimale me këtë suplement para stërvitjes të shpërblyer shumë herë. I formuluar shkencërisht për rritjen e energjisë dhe fokusit gjatë stërvitjes.</p><ul><li><p>Rritje e energjisë me kafeinë natyrale</p></li><li><p>Përmban beta-alaninë për efekt shpërthyes para stërvitjes</p></li><li><p>Qëndrueshmëri, energji dhe fokus gjatë stërvitjes</p></li></ul><p>USN B4-BOMB është suplement i fuqishëm para stërvitjes, i formuluar për t’ju ndihmuar të nxirrni maksimumin nga çdo stërvitje dhe të arrini qëllimet tuaja.</p><p><em>¹Vetëm te shija qershi.</em></p><p><strong>Sasia neto:</strong> 180 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Një dozë është 2 lugë matëse (15 g). Doza maksimale ditore është 4 lugë matëse (30 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merreni 30 minuta para stërvitjes. Mos tejkaloni 2 porcione (30 g) në ditë. Konsumojeni brenda 1 muaji pas hapjes. PARALAJMËRIM: Përmbajtje e lartë kafeine (200 mg/15 g; 400 mg/30 g). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji. Vetëm për të rritur. Mos tejkaloni 400 mg kafeinë në ditë nga të gjitha burimet (200 mg në ditë për gra shtatzëna dhe gra që ushqejnë me gji). Si me të gjitha suplementet ushqimore, konsultohuni fillimisht me mjekun tuaj, sidomos nëse keni problem shëndetësor dhe/ose përdorni barna. Siguroni hidratim të duhur. Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! I përshtatshëm për vegjetarianë dhe veganë. Ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 2 lugë matëse (15 g) me 250–300 ml ujë ose 4 lugë matëse (30 g) me 500–600 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2224;

-- Product_Id: 2225 (USN BCAA POWER PUNCH, 400g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN BCAA POWER PUNCH, 400g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Pije me aminoacide që tretet lehtë</p></li><li><p>Kombinim i L-glutaminës dhe aminoacideve BCAA</p></li><li><p>Me vitaminë B6 të shtuar</p></li><li><p>Shije të shijshme frutash</p></li></ul><p><strong>Përzierje për përgatitjen e pijes me aminoacide me vitaminë B6 dhe ëmbëlsues.</strong></p><p>USN BCAA Power Punch ofron shije të shkëlqyer, përzierje të lehtë dhe formulë dinamike. Kombinimi i acidit glutamik dhe aminoacideve me zinxhir të degëzuar (BCAA) krijon një pije të shijshme të projektuar për t’ju dhënë nxitje shtesë, për të ndihmuar në luftën kundër lodhjes dhe për të mbështetur rritjen dhe ruajtjen e masës muskulore.</p><p><strong>Sasia neto:</strong> 400 g</p><p>Burimi: https://uk.usn-sport.com/</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (11 g). Personat me peshë trupore 85 kg ose më shumë duhet të marrin 4 lugë matëse të plota me majë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Pijeni para, gjatë dhe pas stërvitjes. PARALAJMËRIM: Konsultohuni fillimisht me mjekun tuaj, sidomos nëse keni problem shëndetësor. Mos e përdorni produktin nëse jeni shtatzënë, ushqeni me gji ose jeni nën 18 vjeç. Në rast të çfarëdo problemi shëndetësor, konsultohuni me mjekun tuaj para përdorimit të produktit. Produkti nuk është i përshtatshëm për gra shtatzëna, gra që ushqejnë me gji dhe persona nën 18 vjeç. Marrja afatgjatë e më shumë se 10 mg vitaminë B6 në ditë mund të shkaktojë mpirje ose ndjesi të lehtë shpimi. Gjatë përdorimit të produktit, patjetër ruani hidratim të duhur. Pini të paktën 8–10 gota të mëdha ujë në ditë. Sasitë e larta të aminoacideve mund të shkaktojnë shqetësime në stomak te personat e ndjeshëm. Në këtë rast, ulni dozën ose ndërprisni përdorimin. Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk është zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar dhe stil jetese të shëndetshëm.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni një porcion në 500–600 ml ujë të ftohtë në shejker ose shishe dhe tundeni mirë për 30 sekonda.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2225;

-- Product_Id: 2228 (USN PURE CREATINE MONOHYDRATE, 500g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN PURE CREATINE MONOHYDRATE, 500g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Kreatinë monohidrat në formë të mikronizuar</p></li><li><p>Ndihmon në ruajtjen e niveleve të energjisë gjatë kontraktimeve muskulore</p></li><li><p>Ndihmon në rritjen e masës muskulore</p></li><li><p>Thithje dhe rikuperim i shpejtë</p></li></ul><p><strong>Suplement ushqimor me kreatinë monohidrat.</strong></p><p>USN Creatine Monohydrate është kreatinë monohidrat e mikronizuar në formë të pastër, me thithje të lartë. Me marrje ditore prej të paktën 3 g kreatinë, kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Gjatë kontraktimeve muskulore, ndihmon në ruajtjen e ekuilibrit të nivelit të ATP-së.</p><p>Suplementi ushqimor me kreatinë monohidrat është i sigurt dhe i përshtatshëm për të gjithë ata që stërviten me intervale të shkurtra dhe intensive. Rekomandojmë marrjen e 3–5 g kreatinë monohidrat menjëherë pas stërvitjes, së bashku me proteinë whey dhe karbohidrate, për thithje optimale të lëndëve ushqyese dhe rikuperim të përmirësuar.</p><p>Kreatina është përbërje organike azotike që gjendet natyrshëm te të gjithë vertebrorët. Përqendrimet më të larta janë të pranishme në indin muskulor. Kreatina shërben si përbërje me energji të lartë që siguron energji të shpejtë, sidomos për indin muskulor, ku për një periudhë të shkurtër nevojitet të shfrytëzohet sasi relativisht e madhe e ATP-së. Marrja e kreatinës përmes suplementimit rrit përqendrimin e kreatinës në muskuj. Kreatina mund ta rrisë deri në një shkallë forcën muskulore, sidomos gjatë aktiviteteve sportive anaerobe (afatshkurtra). Gjithashtu rrit masën muskulore përmes rritjes së mbajtjes së ujit në muskuj.</p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë çaji (5 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Mos konsumoni më shumë se 4 porcione në ditë (20 g). SHËNIM: Është e rëndësishme të ruhet marrje e duhur ditore e lëngjeve. Marrja maksimale ditore 20 g, e barabartë me 4 porcione. PARALAJMËRIM: Ju lutemi konsultohuni me mjekun tuaj para përdorimit nëse përdorni barna ose ju është diagnostikuar ndonjë gjendje mjekësore. Nuk rekomandohet për gra shtatzëna/gra që ushqejnë me gji dhe persona nën 18 vjeç. Mos e tejkaloni marrjen ditore të rekomanduar. Suplementet ushqimore nuk duhet të zëvendësojnë një ushqyerje të ekuilibruar e të larmishme dhe stil jetese të shëndetshëm. Mbajeni larg fëmijëve! Ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 2 lugë çaji (5 g) me 250 ml ujë të ftohtë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2228;

-- Product_Id: 2231 (USN LIV.SMART COLLAGEN, 330g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN LIV.SMART COLLAGEN, 330g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Proteinë kolagjeni e hidrolizuar premium</p></li><li><p>Mbështetje për shëndetin e nyjeve dhe lëkurës</p></li><li><p>Mbështetje për shëndetin e flokëve dhe lëkurës</p></li><li><p>Mbështetje për krijimin e kolagjenit</p></li><li><p>30 porcione</p></li></ul><p><strong>Suplement ushqimor me kolagjen dhe vitaminë C, me ëmbëlsues.</strong></p><p>Liv.SMART Collagen përmban kolagjen të hidrolizuar. Kolagjeni është proteinë që gjendet në lëkurë, indet lidhëse, kocka, kërc dhe ligamente. Funksioni i tij kryesor është ruajtja e elasticitetit dhe fortësisë së indeve. Megjithatë, prodhimi i kolagjenit në organizëm zvogëlohet me moshën, gjë që mund të çojë në humbjen e fortësisë së lëkurës, shfaqjen e rrudhave dhe dobësimin e nyjeve dhe kockave. Kolagjeni i hidrolizuar përftohet përmes procesit të hidrolizës, gjatë të cilit molekulat e mëdha të proteinave zbërthehen në molekula më të vogla që thithen më lehtë në organizëm. Kolagjeni i hidrolizuar ka biodisponueshmëri më të madhe dhe arrin më shpejt te indet ku nevojitet.</p><p>Liv.SMART Collagen përmban edhe vitaminë C, për të cilën dihet se kontribuon në krijimin normal të kolagjenit, të domosdoshëm për funksionimin normal të enëve të gjakut, kockave, kërcit, mishrave të dhëmbëve, lëkurës dhe dhëmbëve.</p><p>Plotësoni nevojat e organizmit për kolagjen, substancë e domosdoshme për fortësinë e pothuajse të gjitha indeve!</p><p>Produkti nuk përmban gluten, sheqer dhe laktozë.</p><p><strong>Sasia neto:</strong> 330 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (11 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 1 porcion në ditë, mundësisht pas ushtrimeve ose si rostiçeri gjatë ditës.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion (11 g) me 400 ml ujë dhe trazojeni.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2231;

-- Product_Id: 2232 (USN LIV.SMART SLIM SHAKE MEAL REPLACEMENT, 550g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN LIV.SMART SLIM SHAKE MEAL REPLACEMENT, 550g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>“Shape Up” – zëvendësim vakti nga seria Liv. SMART</p></li><li><p>I pasur me lëndë ushqyese, me përmbajtje të ulët sheqeri dhe të lartë fibrash</p></li><li><p>Mbështetje gjatë uljes së peshës trupore</p></li><li><p>Qëllime që lidhen me stilin e jetesës dhe formën trupore**</p></li><li><p>I përshtatshëm për vegjetarianë</p></li><li><p>10 porcione</p></li></ul><p><strong>Zëvendësim vakti për kontrollin e peshës trupore, me ëmbëlsues.</strong>*</p><p><strong>LIV. JETA JOTE MË E MIRË</strong></p><p><strong>Provoni linjën e re Liv. SMART.</strong></p><p>Ky shejk i shijshëm ju siguron lëndët ushqyese të nevojshme për t’ju ndihmuar në arritjen e qëllimeve për uljen e peshës trupore.</p><ul><li><p>I pasur me lëndë ushqyese dhe fibra</p></li><li><p>Vetëm 200 kalori për vakt</p></li><li><p>21 g proteina për vakt</p></li><li><p>Përbërje e plotë vitaminash dhe mineralesh</p></li><li><p>Përmbajtje e ulët sheqeri</p></li><li><p>I përshtatshëm për vegjetarianë</p></li><li><p>Pa ngjyrues, aroma dhe konservues artificialë</p></li><li><p>Tri shije të shijshme për të zgjedhur</p></li></ul><p><strong>Një jetë. Jetoje.</strong></p><p><strong>Udhëzime për përdorim dhe informacione të rëndësishme:</strong></p><p>** Zëvendësimi i njërit prej vakteve kryesore ditore në kuadër të një ushqyerjeje me energji të kufizuar me zëvendësim vakti kontribuon në ruajtjen e peshës trupore pas uljes së saj. Për të arritur efektin e përmendur, një vakt kryesor në ditë duhet të zëvendësohet me zëvendësim vakti. Zëvendësimi i dy prej vakteve kryesore ditore në kuadër të një ushqyerjeje me energji të kufizuar me zëvendësime vakti kontribuon në uljen e peshës trupore. Për të arritur efektin e përmendur, dy vakte kryesore në ditë duhet të zëvendësohen me zëvendësime vakti. Produkti është i dobishëm për qëllimin e parashikuar vetëm si pjesë e një ushqyerjeje me energji të kufizuar, ku edhe produktet e tjera ushqimore duhet të jenë pjesë e domosdoshme e një ushqyerjeje të tillë. Është shumë e rëndësishme që çdo ditë të merret sasi e mjaftueshme lëngjesh. Mbajeni larg fëmijëve!</p><p><strong>Sasia neto:</strong> 550 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (55 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1–2 porcione në ditë si zëvendësim vakti. SHËNIM: I pasur me fibra. Zëvendësimi i dy vakteve ditore të një diete me energji të kufizuar me zëvendësime vakti si liv.smart Slim Shake kontribuon në uljen e peshës. Përmban laktazë, e cila zbërthen laktozën e pranishme në qumësht. I formuluar me krom.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 2 lugë matëse në 250–300 ml ujë të ftohtë dhe përzieni mirë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2232;

-- Product_Id: 2233 (USN PURE CREATINE MONOHYDRATE (SACHET), 500g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN PURE CREATINE MONOHYDRATE (SACHET), 500g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Kreatinë monohidrat e mikronizuar</p></li><li><p>Raport i shkëlqyer çmim-cilësi</p></li><li><p>Ndihmon në rritjen e performancës fizike</p></li><li><p>100 porcione</p></li></ul><p><strong>Suplement ushqimor me kreatinë monohidrat.</strong></p><p>USN Creatine Monohydrate është kreatinë monohidrat e mikronizuar në formë të pastër, me thithje të lartë. Me marrje ditore prej të paktën 3 g kreatinë, kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Gjatë kontraktimeve muskulore, ndihmon në ruajtjen e ekuilibrit të nivelit të ATP-së.</p><p>Suplementi ushqimor me kreatinë monohidrat është i sigurt dhe i përshtatshëm për të gjithë ata që stërviten me intervale të shkurtra dhe intensive. Rekomandojmë marrjen e 3–5 g kreatinë monohidrat menjëherë pas stërvitjes, së bashku me proteinë whey dhe karbohidrate, për thithje optimale të lëndëve ushqyese dhe rikuperim të përmirësuar.</p><p>Kreatina është përbërje organike azotike që gjendet natyrshëm te të gjithë vertebrorët. Përqendrimet më të larta janë të pranishme në indin muskulor. Kreatina shërben si përbërje me energji të lartë që siguron energji të shpejtë, sidomos për indin muskulor, ku për një periudhë të shkurtër nevojitet të shfrytëzohet sasi relativisht e madhe e ATP-së. Marrja e kreatinës përmes suplementimit rrit përqendrimin e kreatinës në muskuj. Kreatina mund ta rrisë deri në një shkallë forcën muskulore, sidomos gjatë aktiviteteve sportive anaerobe (afatshkurtra). Gjithashtu rrit masën muskulore përmes rritjes së mbajtjes së ujit në muskuj.</p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë çaji (5 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'FAZA E NGARKIMIT ME KREATINË: Në 5 ditët e para të përdorimit, merrni 1 lugë çaji 4 herë në ditë me 250 ml lëng frutash ose pijen tuaj të preferuar proteinike. FAZA E MIRËMBAJTJES ME KREATINË: Pas 5 ditëve të njëpasnjëshme të marrjes, merrni 1 lugë çaji 1–2 herë në ditë me 250 ml lëng frutash për një periudhë prej 3 javësh. Ndërprisni plotësisht përdorimin për 3 javë para se ta filloni përsëri ciklin. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2233;

-- Product_Id: 2235 (VAST MAGNESIUM BISGLYCINATE 200)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'VAST MAGNESIUM BISGLYCINATE 200' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Bisglicinat magnezi i kelatuar</p></li><li><p>Biodisponueshmëria më e lartë</p></li><li><p>Ndihmon në uljen e lodhjes dhe rraskapitjes</p></li><li><p>Mbështetje për funksionin normal të muskujve dhe metabolizmin energjetik</p></li><li><p>Produkt 100% vegan</p></li><li><p>Pa laktozë dhe pa gluten</p></li></ul><p><strong>Suplement ushqimor me magnez.</strong></p><p><strong>PËR PERFORMANCË MAKSIMALE</strong></p><p>Magnezi është një nga mineralet më të rëndësishme që i nevojiten organizmit, sepse vepron si kofaktor në qindra enzima dhe procese trupore. Kontribuon në ruajtjen e funksionit normal të muskujve dhe sistemit nervor duke lehtësuar transportin e joneve, si kaliumi dhe kalciumi, përmes membranave qelizore.</p><ul><li><p>Kapsula 100% vegane</p></li><li><p>Mineral esencial për sportistët</p></li></ul><p><strong>BIODISPONUESHMËRIA MË E LARTË</strong></p><p>Asnjë suplement ushqimor nuk ia vlen paratë e investuara nëse nuk jep rezultatet e pritura. Për të arritur biodisponueshmërinë më të lartë të mundshme, shmangëm format më të dobëta të magnezit, si citrati i magnezit ose oksidi i magnezit, dhe zgjodhëm bisglicinatin e magnezit. Sa më e lartë biodisponueshmëria, aq më mirë organizmi e thith përbërësin.</p><ul><li><p>Biodisponueshmëri optimale</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 120 kapsula vegane</p>"]' ELSE DescriptionAl END,
    NutritionValuesIngredientsAl = CASE WHEN ISNULL(NutritionValuesIngredientsAl, N'') = N'' THEN N'PËRBËRËSIT: Bisglicinat magnezi, hidroksipropil metilcelulozë (kapsula).' ELSE NutritionValuesIngredientsAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 kapsula.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë me 200 ml ujë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2235;

-- Product_Id: 2236 (ZzZuper Sleep, 30 кесички)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'ZzZuper Sleep, 30 qeska' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<h2><strong>Gjumi – çelësi i shëndetit dhe mirëqenies suaj</strong></h2><p>A jeni zgjuar ndonjëherë të lodhur, edhe pasi keni kaluar mjaft orë në shtrat? Ose ndoshta keni probleme me pagjumësinë, zgjoheni shpesh gjatë natës ose thjesht ndjeni se gjumi juaj nuk është mjaftueshëm cilësor? <strong>Gjumi është një nga shtyllat themelore të shëndetit tonë dhe ndikon në humorin, imunitetin, qartësinë mendore dhe cilësinë e përgjithshme të jetës.</strong> Megjithatë, stili modern i jetesës, stresi, ushqyerja e paekuilibruar dhe mungesa e aktivitetit fizik shpesh e prishin ciklin natyral të gjumit.</p><p>ZzZuper Sleep është <strong>suplement ushqimor natyral</strong>, i projektuar për përmirësimin e gjumit, që ju ndihmon të bini në gjumë më lehtë, të flini më gjatë dhe të zgjoheni plot energji. Formula e tij unike kombinon <strong>11 përbërës të fuqishëm</strong> që veprojnë në mënyrë sinergjike për të mbështetur të gjitha fazat e gjumit, duke i mundësuar organizmit të rigjenerohet dhe juve të ndiheni të freskët çdo mëngjes.</p><h2><strong>Pse është gjumi kaq i rëndësishëm?</strong></h2><p>Gjumi nuk është vetëm kohë për pushim – ai është <strong>proces rigjenerimi i trupit dhe mendjes</strong>. Ndërsa flemë, truri përpunon informacionet, trupi rinovon qelizat dhe hormonet sillen në ekuilibër. Mungesa e gjumit lidhet me rrezik të shtuar të shumë problemeve shëndetësore, përfshirë:</p><p>✅ <strong>Imunitet më i dobët</strong> – gjumi i keq mund të rrisë ndjeshmërinë ndaj ftohjeve dhe infeksioneve.</p><p>✅ <strong>Probleme me përqendrimin</strong> – gjumi është kyç për funksionet mendore, përfshirë kujtesën dhe marrjen e vendimeve.</p><p>✅ <strong>Stres dhe ankth i shtuar</strong> – mungesa e gjumit rrit nivelin e kortizolit, hormonit të stresit.</p><p>✅ <strong>Çrregullime të humorit</strong> – pagjumësia lidhet me rrezik të shtuar të depresionit.</p><p>✅ <strong>Probleme me metabolizmin</strong> – gjumi i pamjaftueshëm mund të shkaktojë oreks të shtuar dhe rritje të peshës trupore.</p><p>Nëse keni probleme me gjumin, është e rëndësishme <strong>të gjeni një mënyrë natyrale</strong> për ta përmirësuar – dhe këtu vjen <strong>ZzZuper Sleep</strong>.</p><h2><strong>Si vepron ZzZuper Sleep?</strong></h2><p>Falë kombinimit të formuluar shkencërisht të përbërësve, ZzZuper Sleep <strong>vepron në disa nivele</strong>:</p><p>🔹 <strong>Rregullon ritmin cirkadian</strong> – nxit prodhimin natyral të melatoninës, hormonit përgjegjës për gjumin.</p><p>🔹 <strong>Relakson sistemin nervor</strong> – falë aminoacideve dhe neurotransmetuesve si GABA, serotonina dhe dopamina.</p><p>🔹 <strong>Nxit gjumin e thellë</strong> – zgjat fazën NREM të gjumit dhe përmirëson cilësinë e gjumit.</p><p>🔹 <strong>Ul stresin dhe ankthin</strong> – ekstraktet bimore dhe aminoacidet ndihmojnë në qetësimin e mendjes para gjumit.</p><p>🔹 <strong>Përmirëson zgjueshmërinë në mëngjes</strong> – ndryshe nga tabletat sintetike të gjumit, ZzZuper Sleep nuk shkakton përgjumje në mëngjes.</p><h2><strong>Përbërës natyralë për gjumë më të mirë</strong></h2><p>ZzZuper Sleep kombinon <strong>përbërësit më të mirë natyralë</strong> për t’ju mundësuar <strong>gjumë të thellë dhe cilësor</strong>.</p><p>🔹 <strong>L-triptofani</strong> – aminoacid esencial që në organizëm shndërrohet në serotoninë dhe melatoninë. Ndihmon në rregullimin e gjumit dhe përmirëson humorin.</p><p>🔹 <strong>Glicina</strong> – ul temperaturën e trupit, gjë që është e rëndësishme për rënien në gjumë dhe ruajtjen e gjumit të thellë. Gjithashtu përmirëson funksionet njohëse pas zgjimit.</p><p>🔹 <strong>Magnezi</strong> – qetëson sistemin nervor, relakson muskujt dhe përmirëson cilësinë e gjumit. Mungesa e tij shpesh lidhet me pagjumësinë.</p><p>🔹 <strong>Taurina</strong> – aminoacid që mbron sistemin nervor, ul stresin dhe mbështet funksionin normal të neurotransmetuesve.</p><p>🔹 <strong>Mio-inozitoli</strong> – mbështet funksionin e serotoninës dhe ndihmon në rregullimin e ciklit të gjumit. Mund të përmirësojë kohëzgjatjen dhe cilësinë e gjumit.</p><p>🔹 <strong>L-teanina</strong> – aminoacid nga çaji jeshil që nxit relaksimin pa shkaktuar përgjumje gjatë ditës.</p><p>🔹 <strong>SAM-e (S-adenozil-L-metionina)</strong> – luan rol të rëndësishëm në sintezën e serotoninës, norepinefrinës dhe dopaminës, që janë të rëndësishme për humorin dhe gjumin.</p><p>🔹 <strong>5-HTP (5-hidroksitriptofani)</strong> – pararendës i serotoninës, që ndihmon në përmirësimin e gjumit dhe uljen e stresit.</p><p>🔹 <strong>Ekstrakt luleje kamomili (apigeninë)</strong> – qetësues natyral që qetëson dhe përmirëson cilësinë e gjumit.</p><p>🔹 <strong>Vitamina B6</strong> – mbështet sintezën e neurotransmetuesve si serotonina dhe përmirëson cilësinë e fazës REM të gjumit.</p><p>🔹 <strong>Vitamina C</strong> – antioksidant i fuqishëm që mbështet shëndetin e trurit dhe rregullon prodhimin e neurotransmetuesve.</p><h2><strong>Si ta përdorni ZzZuper Sleep?</strong></h2><p>Për rezultate më të mira, rekomandohet:</p><p>✔ <strong>1 qeskë</strong> – për relaksim të lehtë para gjumit.</p><p>✔ <strong>2 qeska</strong> – për gjumë më të thellë dhe më të shpejtë, sidomos nëse keni probleme me pagjumësinë.</p><p>Përzieni përmbajtjen e qeskës me ujë të vakët dhe pijeni pijen <strong>30 deri në 60 minuta para se të shkoni në shtrat</strong>.</p><h2><strong>Pse të zgjidhni ZzZuper Sleep?</strong></h2><p>🔹 <strong>Formulë natyrale</strong> – pa shtesa sintetike dhe efekte anësore.</p><p>🔹 <strong>Nuk krijon varësi</strong> – ndryshe nga tabletat e gjumit, nuk shkakton varësi as lodhje në mëngjes.</p><p>🔹 <strong>Veprim i shpejtë</strong> – fillon të veprojë që nga përdorimi i parë.</p><p>🔹 <strong>I mbështetur nga kërkime shkencore</strong> – të gjithë përbërësit kanë efekte të konfirmuara në cilësinë e gjumit.</p><h2><strong>Porositni ZzZuper Sleep tuaj që sot!</strong></h2><p>Mos lejoni që gjumi i keq të ndikojë në përditshmërinë tuaj. Provoni <strong>ZzZuper Sleep</strong> dhe siguroni vetes <strong>netë të qeta dhe mëngjese plot energji</strong>!</p><p>➡ <strong>Porositni tani dhe ndjeni ndryshimin që nga nata e parë!</strong></p><p><strong>Misioni ynë është t’ju ndihmojmë të flini më mirë.</strong></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Udhëzime për përdorimin e ZzZuper Sleep: Për relaksim para gjumit ose menjëherë para një fluturimi, rekomandohet një qeskë ZzZuper Sleep, ndërsa dy qeska janë ideale për rënie më të shpejtë në gjumë. Formula jonë është e thjeshtë dhe e përshtatshme – shtoni sasinë e dëshiruar të ujit të vakët për ta përshtatur shijen sipas dëshirës suaj.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Përgatiteni menjëherë para përdorimit dhe pijeni gjysmë ore deri në një orë para gjumit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2236;

-- Product_Id: 2237 (VAST CREATINE CREAPURE, 300g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'VAST CREATINE CREAPURE, 300g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>100% kreatinë monohidrat Creapure me cilësi premium</p></li><li><p>E pastër, pa shtesa dhe pa shije</p></li><li><p>Performancë fizike dhe forcë</p></li><li><p>Produkt vegan</p></li><li><p>60 porcione</p></li></ul><p><strong>Suplement ushqimor me bazë kreatinë monohidrat. Pluhur pa aromë, i destinuar veçanërisht për sportistë.</strong></p><p><strong>PROCES PRODHIMI I PATENTUAR</strong></p><p>I prodhuar nga kreatina monohidrat Creapure® më cilësore dhe më e pastër, e prodhuar në Gjermani, ideale për sportistë garues.</p><p><strong>I MIKRONIZUAR</strong></p><p>I mikronizuar për tretshmëri të shkëlqyer dhe përzierje të shpejtë e të lehtë në ujë ose shejke.</p><p><strong>PERFORMANCË FIZIKE E PËRMIRËSUAR</strong></p><p>Është vërtetuar se kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë.</p><p><strong>100% I PASTËR DHE PA SHTESA</strong></p><p>I përsosur për të gjitha sportet me ngarkesa me intensitet të lartë, si sportet garuese, bodybuilding-u, ngritja e peshave, fitnesi, futbolli dhe atletika.</p><p><strong>PRODUKT VEGAN</strong></p><p><strong>Sasia neto:</strong> 300 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse (3 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 1 porcion në ditë. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me afërsisht 250 ml ujë. Gjithashtu përzihet lehtë në shejke ose pije të tjera.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2237;

-- Product_Id: 2238 (PROTEINI.SI ENERGY+ SUPERCHARGED ENERGY GEL)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ENERGY+ SUPERCHARGED ENERGY GEL' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Xhel karbohidratesh shumë i përqendruar</p></li><li><p>48 g karbohidrate për xhel</p></li><li><p>Raporti maltodekstrinë : fruktozë = 1 : 0,8</p></li><li><p>Thithje e rritur e karbohidrateve</p></li><li><p>Shqetësime më të pakta tretëse</p></li><li><p>Performancë dhe rikuperim i përmirësuar</p></li></ul><p><strong>Suplement ushqimor me sheqerna.</strong></p><p>Supercharged Energy Gel është burim energjie shumë i përqendruar, i projektuar për rimbushjen e shpejtë të rezervave të harxhuara të energjisë gjatë stërvitjes ose garës. Xheli bazohet në maltodekstrinë dhe fruktozë në raportin optimal 1 : 0,8, i cili është bërë standard te suplementet sportive për performancë të lartë.</p><p><strong>PËRPARËSITË E RAPORTIT MALTODEKSTRINË : FRUKTOZË 1 : 0,8</strong></p><p><strong>Thithje më efikase e karbohidrateve</strong></p><p>Maltodekstrina thithet përmes SGLT1 (transportuesi i glukozës i varur nga natriumi), ndërsa fruktoza thithet përmes transportuesit GLUT5. Raporti 1 : 0,8 mundëson përdorimin e njëkohshëm të të dy mekanizmave të transportit, gjë që mundëson thithje më të madhe totale të karbohidrateve në orë (deri në 90–120 g karbohidrate në orë), pa e mbingarkuar vetëm një mekanizëm transporti.</p><p><strong>Më pak probleme tretëse</strong></p><p>Konsumimi i tepërt i glukozës ose maltodekstrinës pa fruktozë mund ta ngopë transportuesin SGLT1, gjë që mund të çojë në fryrje, ngërçe dhe diarre. Fruktoza në raportin e duhur (pa qenë në sasi të tepërt) e zvogëlon këtë ngarkesë dhe përmirëson tolerancën gastrointestinale.</p><p><strong>Energji e disponueshme më shpejt</strong></p><p>Kombinimi i dy llojeve të karbohidrateve siguron burim energjie të shpejtë dhe të zgjatur gjatë aktivitetit fizik. Maltodekstrina e rrit shpejt nivelin e sheqerit në gjak, ndërsa fruktoza metabolizohet më ngadalë, në mëlçi, duke siguruar energji më të qëndrueshme.</p><p><strong>Rimbushja e rezervave të glikogjenit</strong></p><p>Fruktoza mbështet kryesisht rimbushjen e rezervave të glikogjenit në mëlçi, ndërsa maltodekstrina (glukoza) rimbush rezervat e glikogjenit në muskuj. Kjo kontribuon në rikthimin e plotë të rezervave të glikogjenit pas përpjekjes fizike ose garës.</p><p><strong>Hidratim dhe transport optimal</strong></p><p>Maltodekstrina ka osmolalitet të ulët, gjë që përmirëson hidratimin dhe thithjen e lëngjeve, sidomos në pije. Fruktoza, kur merret në sasi të vogla, nuk e rrit ndjeshëm osmolalitetin, duke ndihmuar që pija të mbetet izotonike ose hipotonike – ideale për përdorim sportiv.</p><p><strong>PËRDORIMI</strong></p><p>Ky xhel rekomandohet veçanërisht për sportet e qëndrueshmërisë (çiklizëm, vrapim, triatlon etj.**), ku rimbushja efikase e glikogjenit dhe ruajtja e energjisë gjatë përpjekjes fizike të zgjatur janë me rëndësi kyçe.</p><ul><li><p><strong>Gjatë aktivitetit fizik të zgjatur (mbi 1,5 orë):</strong> Ndihmon në ruajtjen e nivelit të energjisë. Marrja e rekomanduar është 60–90 g karbohidrate në orë, nga të cilat afërsisht 55% maltodekstrinë dhe 45% fruktozë.</p></li><li><p><strong>Pas aktivitetit fizik (rikuperimi):</strong> Mund të përdoret për përshpejtimin e rikthimit të rezervave të glikogjenit, sidomos kur mbahen disa seanca stërvitore brenda një periudhe të shkurtër kohore.</p></li></ul><p><em>Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</em></p><p><strong>E rëndësishme:</strong> Provojeni xhelin gjatë stërvitjes, jo për herë të parë në garë – reagimi individual ndaj fruktozës mund të ndryshojë.</p><p><strong>Sasia neto:</strong> 75 g / 18 × 75 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 75 g (1 xhel).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni para dhe gjatë aktivitetit fizik, në varësi të nevojave tuaja për energji. Pasi të hapet, produkti është i destinuar për përdorim të menjëhershëm. Doza e rekomanduar ditore nuk duhet të tejkalohet. Mos e përdorni si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2238;

-- Product_Id: 2242 (PROTEINI.SI "HARDCORE ONE" GLOVES)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI "HARDCORE ONE" GLOVES' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>Doreza të reja, të përmirësuara universale për stërvitje!</strong></p><p><strong>Doreza të përmirësuara universale për stërvitje</strong> të punuara nga lëkura më cilësore, e cila vesh sipërfaqen e brendshme dhe pjesën e gishtit të madh. Në vendet që i nënshtrohen tërheqjes ka qepje të dyfishta për qëndrueshmëri më të madhe.</p><p>Lëkura e shpuar te tre gishta mundëson ventilim më të mirë gjatë stërvitjeve intensive. Shiriti elastik mbështetës rreth kyçit siguron përshtatje ideale të dorës.</p><p><strong>Madhësitë:</strong> S, M, L, XL, XXL</p><p><strong>Ngjyra:</strong> e zezë, e verdhë</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2242;

-- Product_Id: 2243 (PROTEINI.SI BACKPACK, black)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI BACKPACK, e zezë' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Çantë shpine praktike dhe shumëfunksionale</p></li><li><p>E qëndrueshme dhe e rehatshme</p></li><li><p>Me disa ndarje dhe xhepa</p></li><li><p>E përshtatshme për sport dhe kohë të lirë</p></li></ul><p>Çantë shpine e zezë praktike, e përshtatshme si për aktivitete sportive ashtu edhe për kohën e lirë. Është e punuar nga material cilësor, i qëndrueshëm dhe i papërshkueshëm nga uji. Përbëhet nga një ndarje kryesore qendrore, në të cilën ka një seksion më të madh për laptop dhe dy xhepa më të vegjël të brendshëm me mbyllje velkro për ruajtjen e sendeve personale (telefon, portofol etj.).</p><p>Nga ana e jashtme ka nga një xhep anësor me rrjetë për ajrosje më të mirë në secilën anë, si dhe një xhep të jashtëm më të madh me zinxhir. Pjesa e pasme e çantës është e punuar nga sfungjer i butë për rehati më të madhe. Në ndarjen kryesore është i shtypur vrapuesi i Proteini.si, ndërsa në rripin e djathtë të shpatullës është vendosur logoja e Proteini.si. Në të dy rripat e shpatullave ka elemente reflektuese për dukshmëri më të mirë në errësirë.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p>E thjeshtë, e qëndrueshme dhe moderne</p></li><li><p>Përdorim shumëfunksional</p></li><li><p>E rehatshme për t’u mbajtur</p></li><li><p>Rripa shpatullash me gjatësi të rregullueshme</p></li><li><p><strong>Materiali:</strong> 70% poliestër, 30% najlon</p></li><li><p><strong>Përmasat:</strong> 46 × 32 × 16,6 cm</p></li><li><p><strong>Ngjyra:</strong> e zezë</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2243;

-- Product_Id: 2244 (PROTEINI.SI BELT)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI BELT' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Rrip fitnesi</p></li><li><p>Për parandalimin e hernies</p></li><li><p>Për mbrojtjen e shtyllës kurrizore gjatë ngritjes së peshave</p></li><li><p>I disponueshëm në version prej lëkure dhe neopreni</p></li></ul><p><strong>Rripi Proteini.si</strong> është i destinuar për përdorim gjatë stërvitjeve intensive në palestër.</p><p>Është i disponueshëm në version prej lëkure dhe neopreni.</p><p><strong>RRIP LËKURE:</strong></p><ul><li><p>I punuar nga lëkurë me cilësi të lartë</p></li><li><p>Skaje të forta me qepje të dyfishta</p></li><li><p>Mbërthim me tokëz metalike me dy gjuhëza dhe mekanizëm rul</p></li><li><p><strong>Madhësitë (perimetri):</strong></p><ul><li><p>S = 70–84 cm</p></li><li><p>M = 80–94 cm</p></li><li><p>L = 90–104 cm</p></li><li><p>XL = 100–114 cm</p></li></ul></li></ul><p><strong>RRIP NEOPRENI:</strong></p><ul><li><p>I punuar nga neopreni</p></li><li><p>I lehtë dhe i rehatshëm</p></li><li><p>Mbërthim velkro me një tokëz</p></li><li><p><strong>Madhësitë (perimetri):</strong></p><ul><li><p>S = 68–86 cm</p></li><li><p>M = 78–96 cm</p></li><li><p>L = 88–106 cm</p></li><li><p>XL = 92–110 cm</p></li></ul></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2244;

-- Product_Id: 2245 (PROTEINI.SI BOOTY HIP BAND, S, PINK)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI BOOTY HIP BAND, S, ROZË' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shirit elastik pëlhure për ushtrime të kofshëve dhe gluteusit</p></li><li><p>Për shtrëngimin e muskujve, formësimin e trupit dhe aktivizimin e shtuar të gluteusit gjatë ushtrimeve</p></li><li><p>I disponueshëm në 3 madhësi të ndryshme, në varësi të zgjedhjes së ushtrimeve dhe intensitetit të dëshiruar</p></li><li><p>I qëndrueshëm dhe i rehatshëm, nuk mblidhet dhe nuk rrëshqet</p></li><li><p>Përdorim shumëfunksional</p></li></ul><p>Proteini.si booty hip band është shirit elastik stërvitor prej pëlhure, që është mjet i pazëvendësueshëm për ushtrime në shtëpi dhe në palestër.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p>3 madhësi të ndryshme, në varësi të zgjedhjes së ushtrimeve dhe intensitetit:</p><ul><li><p><strong>S (rozë)</strong> – 33 × 7,6 cm – vështirësi/rezistencë e lartë: skuat i ngushtë</p></li><li><p><strong>M (bruz)</strong> – 38 × 7,6 cm – vështirësi/rezistencë mesatare: ngritje anësore e këmbës, ushtrimi “guaskë” (clamshell), ecje anësore me shirit</p></li><li><p><strong>L (gri)</strong> – 43 × 7,6 cm – shkallë e ulët vështirësie/rezistence: hap përpara (lunge), skuat i gjerë</p></li></ul></li><li><p><strong>Materiali:</strong> poliestër dhe lateks</p></li></ul><p><strong>PËRPARËSITË:</strong></p><ul><li><p><strong>QËNDRUESHMËRIA:</strong> Pëlhura e fortë është e ndërthurur me fibra të veçanta elastike që mundësojnë gamë të gjerë lëvizjeje. Shiriti është projektuar që të mos griset gjatë përdorimit.</p></li><li><p><strong>REHATIA:</strong> Pëlhura është e fortë, por e butë dhe e këndshme për lëkurën. Nuk pickon, nuk griset, nuk mblidhet dhe nuk rrëshqet, kështu që mund të përqendroheni te stërvitja në vend që ta rregulloni vazhdimisht pajisjen.</p></li><li><p><strong>NUK MBLIDHET:</strong> Gjerësia e madhe dhe shtresa e brendshme ngjitëse prej lateksi e pengojnë shiritin të mblidhet gjatë ushtrimeve.</p></li><li><p><strong>PËRDORIM SHUMËFUNKSIONAL:</strong> Mund të përdoret për Insanity, Pilates, CrossFit, Beachbody dhe stërvitje për gluteusin. Është ideal për fitnes, ushtrime për gluteusin dhe skuate.</p></li></ul><p><strong>PËRFITIMET:</strong></p><ul><li><p><strong>AKTIVIZIM MË I MADH</strong> i muskulit të madh të vitheve (GLUTEUS) – deri në 400%.</p></li><li><p><strong>FORCIMI DHE SHTRËNGIMI:</strong> Këta shirita ndihmojnë në shtrëngimin dhe forcimin e këmbëve, gluteusit, kofshëve, pulpave, kuadricepsit, muskujve të pasmë të kofshës, muskujve të trungut, muskujve rreth ijeve, abduktorëve, ijeve, krahëve dhe shpatullave. Janë të lehtë për t’u përdorur dhe të përshtatshëm për të gjithë, nga fillestarët deri te ushtruesit me përvojë.</p></li><li><p><strong>PËRMIRËSIMI I LËVIZSHMËRISË, FLEKSIBILITETIT DHE FORCËS:</strong> Është i shkëlqyer për shtrirjen e ijeve dhe për ushtrime që përfshijnë gjunjët, muskujt dhe nyjet, me qëllim uljen e rrezikut nga lëndimet e padëshiruara ose për përdorim pas një lëndimi sportiv apo tjetër. Para se të filloni një program ushtrimesh gjatë rikuperimit, është më mirë të konsultoheni me mjekun ose fizioterapeutin. Është ideal për terapi fizikale dhe rehabilitim në kushte shtëpiake.</p></li><li><p><strong>DJEGIA E YNDYRAVE:</strong> Duke stërvitur grupet më të mëdha muskulore, në mënyrë të tërthortë nxitni procesin e djegies së yndyrave.</p></li></ul><p><strong>Sasia neto:</strong> 1 shirit për ushtrime të kofshëve dhe gluteusit / paketim</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2245;

-- Product_Id: 2246 (PROTEINI.SI BOXING GLOVES)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI BOXING GLOVES' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Doreza boksi prej lëkure</p></li><li><p>Dizajn anatomik</p></li><li><p>Thithje e mirë e goditjeve</p></li><li><p>5 hapje për ventilim më të mirë</p></li></ul><p>Dorezat e boksit me logon e bardhë të vrapuesit të Proteini.si janë të punuara nga lëkurë cilësore. Janë të përshtatshme si për sparing ashtu edhe për stërvitje me thes boksi. Falë dizajnit anatomik, mundësojnë pozicion optimal të pëllëmbës dhe grushtit, gjë që ndihmon në përmirësimin e teknikës dhe uljen e rrezikut nga lëndimet e mundshme.</p><p>Dorezat kanë mbushje të mirë mbrojtëse që siguron thithje efikase të goditjeve. Mbërthehen me një sistem të thjeshtë dhe praktik me shirit velkro, që siguron fiksim të qëndrueshëm të kyçit.</p><p>Në anën e brendshme kanë 5 hapje ventilimi, që ndihmojnë në uljen e djersitjes dhe mundësojnë qarkullim më të mirë të ajrit.</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2246;

-- Product_Id: 2247 (PROTEINI.SI CROSSGYM GLOVES)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI CROSSGYM GLOVES' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Doreza për CrossFit dhe stërvitje funksionale</p></li><li><p>Të lehta, të buta dhe që marrin frymë</p></li><li><p>Për stërvitje më të sigurt dhe më të rehatshme</p></li><li><p>Të punuara nga lëkurë dhe najlon</p></li><li><p>Mbërthim me shirit velkro</p></li></ul><p>Dorezat Crossgym janë të destinuara kryesisht për stërvitje CrossFit dhe ushtrime funksionale, duke mundësuar ushtrime më të sigurta dhe më të këndshme. Janë të punuara nga material i butë dhe që merr frymë dhe ofrojnë rehati maksimale gjatë stërvitjes.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p>Të punuara nga lëkurë e butë dhe najlon elastik (ana e sipërme)</p></li><li><p>Mundësojnë kapje më të sigurt dhe rehati më të madhe gjatë ushtrimeve</p></li><li><p>Mbërthim me shirit velkro rreth kyçit</p></li><li><p>Uniseks</p></li><li><p>Dizajn tërheqës</p></li><li><p><strong>Madhësitë:</strong> S–XXL</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2247;

-- Product_Id: 2248 (PROTEINI.SI FITNESS GLOVES WITH GEL)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI FITNESS GLOVES WITH GEL' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>Doreza të reja fitnesi Proteini.si me mbushje xheli!</strong></p><ul><li><p>Mbushje e rehatshme xheli në pëllëmbë dhe te gishtat</p></li><li><p>Qepje të dyfishta të qëndrueshme dhe material i gomuar për kapje të sigurt si në të lagësht ashtu edhe në të thatë</p></li><li><p>Mbyllje e rregullueshme vetëmbërthyese për përshtatje të rehatshme</p></li><li><p>Pëlhurë e veçantë elastike midis gishtave për fleksibilitet më të mirë</p></li></ul><p>Dorezat e fitnesit Proteini.si lahen në lavatriçe dhe nuk lëshojnë ngjyrë në duar. Rekomandohet veçanërisht që të lahen para përdorimit të parë.</p><p><strong>PËRBËRJA:</strong></p><ul><li><p>65% poliestër</p></li><li><p>21% najlon</p></li><li><p>5% pambuk</p></li><li><p>4% poliuretan (PU)</p></li><li><p>3% spandeks</p></li><li><p>2% silikon</p></li></ul><p><strong>Madhësitë e disponueshme:</strong> S, M, L, XL dhe XXL.</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2248;

-- Product_Id: 2249 (PROTEINI.SI GLOVES "SPRINTER", PINK)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI GLOVES "SPRINTER", ROZË' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>Doreza fitnesi për femra me cilësi të lartë</strong></p><p><strong>Doreza Proteini.si “Sprinter” për femra</strong> me buzë tërheqëse me ngjyrë. Materiali elastik në anën e jashtme të dorezave siguron ventilim të mirë dhe përshtatje ideale për duart e femrave. Sipërfaqja e rehatshme prej kamoshi në anën e brendshme mundëson kapje më të mirë dhe ndihmon në mbrojtjen e pëllëmbëve gjatë ushtrimeve. Dorezat kanë gjithashtu gjuhëza të veçanta për veshje dhe zhveshje më të lehtë, si dhe mbyllje velkro prej neopreni me qëndrueshmëri të shtuar.</p><p><strong>Madhësitë:</strong> S, M, L</p><p><strong>Ngjyra:</strong> rozë</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2249;

-- Product_Id: 2250 (PROTEINI.SI GLOVES RAPTOR)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI GLOVES RAPTOR' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>Doreza ekskluzive për stërvitje me përforcim te kyçi!</strong></p><p>Doreza ekskluzive për stërvitje me përforcim te kyçi, të punuara nga kamoshi me cilësinë më të lartë. Fibrat e veçanta sigurojnë elasticitet më të madh midis gishtave. Pjesa e pëllëmbës është e veshur me sfungjer të butë. Në vendet që i nënshtrohen tërheqjes ka qepje të dyfishta për qëndrueshmëri më të madhe. Lëkura e shpuar te tre gishtat mundëson ventilim më të mirë gjatë stërvitjeve intensive. Rripi i dyfishtë i rregullueshëm me mbyllje velkro siguron përshtatje ideale, ndërsa qepjet e veçanta me formë anatomike mundësojnë përshtatje më të mirë të dorës.</p><p><strong>Madhësitë:</strong> S, M, L, XL, XXL</p><p><strong>Ngjyra:</strong> e zezë me qepje të kuqe</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2250;

-- Product_Id: 2251 (PROTEINI.SI HAND GRIP STRENGTHENER RING)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI HAND GRIP STRENGTHENER RING' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Mjet praktik dhe efikas për forcimin e gishtave, pëllëmbëve, kyçeve dhe parakrahëve</p></li><li><p>Mjet për stërvitje ose rehabilitim</p></li><li><p>I disponueshëm në 3 nivele vështirësie (ngjyra të ndryshme)</p></li><li><p><strong>Diametri:</strong> 7,5 cm</p></li></ul><p>Unaza prej gome për forcimin e kapjes është mjet për ushtrime dhe rehabilitim, i destinuar për forcimin e muskujve të gishtave, kyçeve, pëllëmbëve dhe parakrahëve. Unaza ka dizajn ergonomik për përshtatje më të mirë në pëllëmbë dhe nuk rrëshqet gjatë ushtrimeve.</p><p>Është jashtëzakonisht e lehtë për t’u përdorur. Është e përshtatshme për të gjithë – fëmijë, të moshuar, sportistë profesionistë, rekreativë, si dhe fizioterapeutë që e përdorin si mjet për rikuperim dhe terapi pas lëndimeve të duarve.</p><p>Është e vogël dhe praktike, kështu që mund të përdoret pothuajse kurdo dhe kudo.</p><p>Është e disponueshme në nivele të ndryshme vështirësie, të shënuara me ngjyra:</p><ul><li><p><strong>Rezistencë e ulët:</strong> 10 kg – ngjyrë blu</p></li><li><p><strong>Rezistencë mesatare:</strong> 20 kg – ngjyrë portokalli</p></li><li><p><strong>Rezistencë e lartë:</strong> 30 kg – ngjyrë e kuqe</p></li></ul><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li><p>Nivele të ndryshme rezistence</p></li><li><p><strong>Diametri:</strong> 7,5 cm</p></li><li><p><strong>Materiali:</strong> gomë</p></li></ul><p><strong>QËLLIMI:</strong></p><ul><li><p>Stërvitje dhe forcim i muskujve të gishtave, kyçeve, pëllëmbëve dhe parakrahëve në sporte si basketbolli, boksi, mundja, tenisi, ngjitja, ngritja e peshave e të ngjashme</p></li><li><p>Rehabilitim dhe rikuperim pas lëndimeve të gishtave</p></li><li><p>Si pjesë e rehabilitimit pas operacionit</p></li><li><p>Terapi pas lëndimeve të sistemit muskulo-skeletor</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2251;

-- Product_Id: 2252 (PROTEINI.SI HAND WRAPS 3m)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI HAND WRAPS 3m' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Fasha për kyçet (2 copë)</p></li><li><p>Mbrojtje e mirë e kyçeve dhe nyjeve të gishtave</p></li><li><p>Lak për vendosje më të lehtë</p></li><li><p><strong>Gjatësia:</strong> 3 m</p></li></ul><p>Fashat për kyçet Proteini.si janë të punuara nga pëlhurë pambuku gjysmë-elastike, e cila mundëson fleksibilitet dhe përshtatje ideale. Në njërin skaj kanë lak për gishtin e madh për vendosje më të lehtë, ndërsa në tjetrin mbyllje velkro për rregullim më të mirë dhe përshtatje të sigurt. Fashat sigurojnë mbështetje dhe mbrojtje të mirë të kyçeve, nyjeve të gishtave dhe gishtave nga goditjet dhe lëndimet e mundshme.</p><ul><li><p><strong>Gjatësia:</strong> 3 m</p></li><li><p><strong>Gjerësia:</strong> 5 cm</p></li><li><p><strong>Ngjyra:</strong> rozë</p></li><li><p><strong>Paketimi:</strong> 2 fasha</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2252;

-- Product_Id: 2253 (PROTEINI.SI HAND WRAPS 5m)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI HAND WRAPS 5m' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Fasha për kyçet (2 copë)</p></li><li><p>Mbrojtje e mirë e kyçeve dhe nyjeve të gishtave</p></li><li><p>Lak për vendosje më të lehtë</p></li><li><p><strong>Gjatësia:</strong> 5 m</p></li></ul><p>Fashat për kyçet Proteini.si janë të punuara nga pëlhurë pambuku gjysmë-elastike, e cila mundëson fleksibilitet dhe përshtatje ideale. Në njërin skaj kanë lak për gishtin e madh për vendosje më të lehtë, ndërsa në tjetrin mbyllje velkro për rregullim më të mirë dhe përshtatje të sigurt. Fashat sigurojnë mbështetje dhe mbrojtje të mirë të kyçeve, nyjeve të gishtave dhe gishtave nga goditjet dhe lëndimet e mundshme.</p><ul><li><p><strong>Gjatësia:</strong> 5 m</p></li><li><p><strong>Gjerësia:</strong> 5 cm</p></li><li><p><strong>Ngjyra:</strong> e zezë</p></li><li><p><strong>Paketimi:</strong> 2 fasha</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2253;

-- Product_Id: 2254 (PROTEINI.SI KNEE WRAPS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI KNEE WRAPS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Material elastik me cilësi të lartë, që siguron mbrojtje të gjunjëve, mbështetje shtesë dhe rehati gjatë ushtrimeve</p></li><li><p>Të rregullueshme – madhësi universale</p></li><li><p>Shiten në çift!</p></li></ul><p>Fashat për gjunjë janë projektuar për të siguruar mbështetje të gjunjëve gjatë ushtrimeve me pesha, si skuatet dhe ngritja e vdekur (deadlift).</p><p>Të punuara nga pambuk i qëndrueshëm, këto fasha elastike janë plotësisht të rregullueshme dhe mbërthehen me mbyllje velkro.</p><p>Shiten në çift. Fashat janë 1,5 metra të gjata dhe 8 cm të gjera, ndërsa kur tërhiqen mund të arrijnë gjatësi prej afërsisht 3 metrash.</p><ul><li><p>Material elastik me cilësi të lartë për mbrojtjen e gjunjëve, mbështetje shtesë dhe rehati gjatë ushtrimeve</p></li><li><p>Të rregullueshme – madhësi universale</p></li><li><p>Mbyllje velkro</p></li><li><p>Shiten në çift</p></li><li><p><strong>Gjatësia:</strong> 150 cm</p></li><li><p><strong>Gjerësia:</strong> 8 cm</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2254;

-- Product_Id: 2255 (PROTEINI.SI LADY SPORT BAG)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI LADY SPORT BAG' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Çantë sportive e gjerë – e përshtatshme për fitnes, aktivitete sportive dhe udhëtime</p></li><li><p>Ndarje kryesore shumë e gjerë me zinxhir për qasje të lehtë</p></li><li><p>Rrip shpatulle i heqshëm dhe i mbushur</p></li><li><p>Mund të mbahet edhe si çantë shpine</p></li></ul><p>Çanta e gjerë <strong>sportive rozë-zezë Proteini.si</strong> është e punuar nga poliestër i qëndrueshëm. Është e përshtatshme për fitnes, aktivitete të tjera sportive dhe udhëtime. Çanta ka ndarje kryesore të gjerë me zinxhir dhe dy ndarje anësore, të përshtatshme për ruajtjen e rrobave të lagura dhe këpucëve. Rripi i shpatullës është i mbushur për rehati më të madhe dhe gjatësia e tij mund të rregullohet. Çanta ka edhe dy doreza për mbajtje. Pjesa e poshtme është e mbushur për mbrojtje shtesë.</p><p><strong>Përveç kësaj</strong>, çanta ka dy rripa shpatullash të rregullueshëm, të fshehur në xhepin e pjesës së poshtme, kështu që mund të përdoret edhe si çantë shpine.</p><p><strong>Materiali:</strong> 100% poliestër</p><p><strong>Përmasat:</strong> 50 × 28 × 30 cm</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2255;

-- Product_Id: 2256 (PROTEINI.SI LADY SPORT BAG, pink)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI LADY SPORT BAG, rozë' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Çantë sportive shumëfunksionale me përmasa mesatare dhe formë cilindrike</p></li><li><p>Motiv tërheqës në ngjyrë rozë, vjollcë dhe të kuqe</p></li><li><p>E punuar nga poliestër i qëndrueshëm</p></li><li><p>Me xhepa praktikë të madhësive të ndryshme dhe rripa për mbajtje</p></li></ul><p><strong>Çanta sportive për femra Proteini.si</strong> është çantë praktike, e qëndrueshme, me përmasa mesatare dhe formë cilindrike. Është e punuar nga poliestër i qëndrueshëm me motiv në formë diamantesh, në të cilin ngjyrat shkrihen me njëra-tjetrën. Në të dyja anët ka mbishkrimin “Proteini.si women”.</p><p>Çanta është e përshtatshme për fitnes, sporte të tjera dhe udhëtime. Ka ndarje kryesore me zinxhir, dy ndarje anësore prej pëlhure me rrjetë, të përshtatshme për ruajtjen e rrobave të lagura dhe këpucëve, si dhe dy xhepa të vegjël të jashtëm me zinxhir për ruajtjen e sendeve të vogla, portofolit, telefonit e të ngjashme.</p><p>Rripi për mbajtje mbi shpatull është i mbushur për rehati më të madhe dhe gjatësia e tij mund të rregullohet. Çanta ka edhe dy doreza për mbajtje. Pjesa e poshtme është e mbushur për mbrojtje shtesë.</p><p><strong>Materiali:</strong> poliestër, najlon</p><p><strong>Përmasat:</strong></p><ul><li><p><strong>Gjatësia:</strong> 47 cm</p></li><li><p><strong>Diametri:</strong> 26 cm</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2256;

-- Product_Id: 2257 (PROTEINI.SI LIFTING STRAPS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI LIFTING STRAPS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Rripa që ndihmojnë gjatë ngritjes së peshave</p></li><li><p>Ulin ngarkesën mbi gishtat dhe kyçet e duarve</p></li><li><p>Për ushtrime si ngritja e vdekur (deadlift), tërheqja në makinën lat dhe vozitja</p></li></ul><p><strong>Rripat për ngritjen e peshave (Lifting Straps)</strong> janë shirita që sigurojnë mbështetje shtesë gjatë ngritjes së peshave.</p><p>Janë të punuar nga material i butë dhe kanë formë laku, gjë që mundëson kapje më të rehatshme dhe më të sigurt gjatë ngritjes.</p><p>Janë veçanërisht të dobishëm dhe pothuajse të pazëvendësueshëm për ngritjen e vdekur, tërheqjen në makinën lat dhe ushtrimet e vozitjes.</p><p><strong>Madhësia:</strong> universale</p><p><strong>Përmasat:</strong> 57 × 4–4,5 cm</p><p><strong>Ngjyra:</strong> e zezë</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2257;

-- Product_Id: 2258 (PROTEINI.SI PILL BOX)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PILL BOX' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Organizues për ruajtjen e tabletave dhe kapsulave</p></li><li><p>5 ndarje</p></li><li><p>Hapje e lehtë dhe mbyllje e sigurt</p></li><li><p><strong>Përmasat:</strong> 11 × 9,5 × 3 cm</p></li></ul><p><strong>PROTEINI.SI PILL BOX</strong> është kuti praktike me <strong>pesë ndarje</strong> (2 më të mëdha dhe 3 më të vogla), në të cilën mund t’i <strong>ruani suplementet tuaja</strong> në formë tabletash dhe kapsulash.</p><p>Kutia ka dizajn <strong>tërheqës</strong> dhe <strong>modern</strong>, është e punuar nga <strong>plastikë pa BPA</strong> dhe është e disponueshme në tri ngjyra – <strong>e verdhë</strong> dhe <strong>rozë</strong> tërheqëse, si dhe <strong>e zezë</strong> klasike.</p><p><strong>Karakteristikat kryesore:</strong></p><ul><li><p>5 ndarje për organizimin e suplementeve ushqimore</p></li><li><p>Dizajn tërheqës dhe modern</p></li><li><p>E punuar nga plastikë pa BPA</p></li><li><p>E sigurt për larje në enëlarëse</p></li><li><p>Mbyllës me buton për hapje të lehtë dhe mbyllje të sigurt</p></li><li><p>E përshtatshme për përdorim të përditshëm dhe udhëtime</p></li><li><p><strong>Përmasat:</strong> 11 × 9,5 × 3 cm</p></li></ul><p>Tani mund t’i keni pa merak të gjitha suplementet e nevojshme gjithmonë pranë, për të plotësuar nevojat ditore për aminoacide, vitamina dhe minerale.</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2258;

-- Product_Id: 2259 (PROTEINI.SI PUSH-UP BARS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PUSH-UP BARS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Doreza për kryerjen e pompave</p></li><li><p>Për forcimin e pjesës së sipërme të trupit (gjoksi, tricepsi dhe shpatullat)</p></li><li><p>Intensitet më i madh dhe rezultate më të shpejta</p></li><li><p>Sigurojnë siguri dhe rehati më të madhe gjatë ushtrimeve</p></li></ul><p>Dorezat për pompa janë mjet shumë efikas për forcimin e pjesës së sipërme të trupit (gjoksi, tricepsi dhe shpatullat). Ato janë alternativë më e mirë e pompave klasike, sepse mundësojnë intensitet më të madh dhe rehati më të madhe gjatë ushtrimeve, pa presion të drejtpërdrejtë mbi kyçet dhe pëllëmbët. Me to mund të bëni më shumë përsëritje sesa me pompat klasike.</p><p>Përveç kësaj, dorezat mundësojnë gamë më të madhe lëvizjeje gjatë kryerjes së pompave, duke e bërë ushtrimin më sfidues dhe duke nxitur zhvillimin më të shpejtë të muskujve. Mund të përdoren në mënyra të ndryshme, në varësi të qëllimit dhe grupit muskulor që dëshironi të aktivizoni (gjoks, triceps ose shpatulla). Nëse dorezat i vendosni më afër njëra-tjetrës, do të aktivizoni tricepsin, ndërsa me vendosje më të gjerë – në gjerësinë e shpatullave ose më gjerë – përfshini më shumë edhe muskujt e shpatullave.</p><p>Nëse bëni rregullisht pompa, këto doreza do t’ju mundësojnë ta rritni më tej forcën dhe gamën e lëvizjes, duke mbrojtur njëkohësisht kyçet dhe pëllëmbët. Kështu do të mund të përqendroheni më shumë te gjoksi, shpatullat dhe tricepsi.</p><p>Dorezat janë të veshura me sfungjer për kapje më të mirë dhe rehati më të madhe. Veshja gjithashtu mbron dyshemenë dhe parandalon rrëshqitjen gjatë ushtrimeve.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p><strong>Përmasat:</strong> 18 × 13 × 11 cm</p></li><li><p><strong>Materiali:</strong> metal, sfungjer</p></li><li><p><strong>Ngjyra:</strong> e zezë</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2259;

-- Product_Id: 2260 (PROTEINI.SI GRAB PADS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI GRAB PADS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Mbështetëse për kapje më të lehtë dhe më të sigurt gjatë stërvitjes</p></li><li><p>Sigurojnë mbrojtje dhe rehati</p></li><li><p>Parandalojnë shfaqjen e flluskave</p></li></ul><p><strong>Grab Pads</strong> janë mbështetëse që mundësojnë kapje më të mirë gjatë ngritjes së peshave.</p><p>Sigurojnë mbrojtje dhe rehati të duhur për pëllëmbët gjatë ngritjes së peshave të rënda.</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2260;

-- Product_Id: 2261 (PROTEINI.SI RESISTANCE BAND, 70cm, light difficulty (yellow))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI RESISTANCE BAND, 70cm, vështirësi e lehtë (e verdhë)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shirit elastik rezistence në formë rrethi të mbyllur, me perimetër 70 cm</p></li><li><p>I përshtatshëm për ushtrime të të gjithë trupit</p></li><li><p>Mjet ushtrimesh i njohur te femrat</p></li><li><p>Mundëson ushtrime efikase për forcimin e kofshëve dhe gluteusit</p></li><li><p><strong>Vështirësia:</strong> e lehtë (e verdhë)</p></li></ul><p>Shiriti elastik rezistence prej poliestri në formë rrethi të mbyllur mundëson ushtrime të të gjithë trupit. Mund të përdoret edhe për simulimin e ushtrimeve në pajisjet e fitnesit në palestër. Shiriti krijon rezistencë të mirë muskulore në çdo ushtrim dhe në të dy drejtimet e lëvizjes. Mundëson lëvizje në të gjitha drejtimet, shpërndarje më të mirë të përpjekjes muskulore dhe kryerje të saktë të ushtrimeve.</p><p>Mund të përdoret për forcimin e shumicës së grupeve muskulore, për pilates, formësimin e muskujve, rehabilitim mjekësor ose shtrirje në shtëpi dhe në palestër. Është veçanërisht i njohur te femrat, sepse mundëson kryerjen e ushtrimeve shumë efikase për kofshët dhe gluteusin.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p><strong>Rezistenca:</strong> e lehtë</p></li><li><p><strong>Përmasat:</strong> perimetri 70 cm, gjerësia 5,5 cm</p></li><li><p><strong>Materiali:</strong> poliestër</p></li><li><p><strong>Ngjyra:</strong> e verdhë</p></li></ul><p><strong>PËRPARËSITË:</strong></p><ul><li><p>Përdorim shumëfunksional</p></li><li><p>I lehtë dhe praktik për t’u mbajtur</p></li><li><p>I rehatshëm për përdorim</p></li><li><p>Nuk rrëshqet lart ose poshtë gjatë ushtrimeve</p></li><li><p>Përmirëson cilësinë e stërvitjes dhe fleksibilitetin e muskujve</p></li></ul><p><strong>Sasia neto:</strong> 1 shirit elastik rezistence / paketim</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2261;

-- Product_Id: 2262 (PROTEINI.SI SPEED JUMP ROPE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI SPEED JUMP ROPE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Litar kërcimi për shpejtësi me sistem kushinetash për rrotullim më të shpejtë</p></li><li><p>Për ngrohje, ushtrime kardio, forcimin e muskujve të këmbëve dhe kryerjen e “Double Under” (kërcim i dyfishtë)</p></li><li><p>Gjatësi e rregullueshme e litarit (deri në 3 m)</p></li></ul><p><strong>Litari i kërcimit për shpejtësi</strong> është mjet stërvitor i thjeshtë dhe efikas që kontribuon në zhvillimin e shpejtësisë, shkathtësisë dhe koordinimit. Mundëson rrotullim të papenguar dhe të shpejtë në ajër dhe është i njohur për ngrohje, ushtrime kardio dhe forcimin e muskujve të këmbëve. Falë rrotullimit të shpejtë, përdoret edhe në CrossFit për kryerjen e “Double Under” (dy kalime të litarit gjatë një kërcimi).</p><p><strong>Litari i kërcimit për shpejtësi</strong> është i punuar nga kabllo çeliku me gjatësi 3 metra dhe veshje plastike, gjë që mundëson kërcim me shpejtësi të madhe.</p><p>Sistemi me kushineta mundëson rrotullim të papenguar dhe të shpejtë pa ngatërrim, gjë që kontribuon në rezultate më të mira dhe ngrohje më të shpejtë të muskujve. Litari rrotullohet në kënd 90°, gjë që mundëson rehati dhe siguri më të madhe gjatë ushtrimeve, ndërsa dorezat më të gjata e lehtësojnë rrotullimin.</p><p>Kablloja e çelikut mund të rregullohet deri në gjatësi prej 3 metrash – thjesht shkurtojeni në gjatësinë e dëshiruar dhe fiksojeni përsëri me vidën. Është i përshtatshëm për të gjithë.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p><strong>Gjatësia e litarit:</strong> 3 m</p></li><li><p><strong>Materiali:</strong> çelik i veshur me PVC (litari), çelik (dorezat)</p></li><li><p><strong>Ngjyra:</strong> argjendtë dhe e zezë</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2262;

-- Product_Id: 2263 (PROTEINI.SI WOMEN'S FITNESS BELT, PINK)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI WOMEN''S FITNESS BELT, ROZË' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Rrip fitnesi prej poliestri dhe lëkure</p></li><li><p>Për parandalimin e hernies</p></li><li><p>Për mbrojtjen e shtyllës kurrizore gjatë ngritjes së peshave</p></li><li><p>I projektuar për femra</p></li></ul><p><strong>Rripi i fitnesit për femra Proteini.si</strong>, i punuar nga poliestër dhe neopren, është i destinuar për ushtrues më me përvojë që ngrenë pesha. Siguron mbështetje dhe ndihmon në mbrojtjen e shpinës gjatë përdorimit të peshave më të mëdha.</p><ul><li><p>Ideal për ngritjen e peshave të rënda</p></li><li><p>Siguron mbështetje dhe mbrojtje të shpinës</p></li><li><p>Përshtatje universale</p></li><li><p><strong>Madhësitë e disponueshme:</strong> S, M</p></li></ul><p><strong>MASAT:</strong></p><ul><li><p>S = 74–87 cm</p></li><li><p>M = 84–97 cm</p></li></ul><p><strong>MATERIALI:</strong></p><ul><li><p>Poliestër: 50%</p></li><li><p>Neopren: 40%</p></li><li><p>Materiale të tjera (metal, najlon): 10%</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2263;

-- Product_Id: 2267 (DEDICATED UNSTOPPABLE PUMP)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'DEDICATED UNSTOPPABLE PUMP' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement legjendar para stërvitjes për efekt më të mirë “pump”</p></li><li><p>Përbërës premium</p></li><li><p>PA STIMULUES</p></li><li><p>Efekt i pastër “pump”, pa rënie energjie dhe pa thumbim</p></li><li><p>Shije të shpërblyera shumë herë</p></li><li><p>30 porcione</p></li></ul><p><strong>Suplement ushqimor me ëmbëlsues.</strong></p><p>UNSTOPPABLE PUMP™ përmban përbërës jashtëzakonisht të fuqishëm, sasitë e të cilëve janë plotësisht të deklaruara dhe të dozuara në nivelin më të lartë të mundshëm për rezultate legjendare. Pa mbushës, sheqerna ose përbërës të padobishëm.</p><p>Ndjeni vetë, vetëm pak minuta pas konsumimit të UNSTOPPABLE PUMP™, pse mban pikërisht këtë emër.</p><p><strong>PA STIMULUES, PA RËNIE ENERGJIE, PA THUMBIM</strong></p><p>UNSTOPPABLE PUMP™ nuk përmban përbërës stimulues as përbërës që shkaktojnë thumbim, gjë që ju mundëson të bini lehtë në gjumë natën. Është i ekuilibruar në mënyrë të përsosur për t’ju ndihmuar t’i përfundoni stërvitjet pa ndjesinë e stimulimit të tepërt kur të ktheheni në shtëpi. Të gjitha përfitimet për performancën fizike dhe një efekt “pump” edhe më i mirë – pa stimulues!</p><p><strong>DOZA ULTRA TË LARTA</strong></p><p>UNSTOPPABLE PUMP™ përmban përbërës jashtëzakonisht të fuqishëm në doza që vendosin standarde të larta në industri dhe që rrallë do t’i gjeni te produktet e tjera, për rezultate legjendare. Sa të fuqishëm? Çfarë thoni për plot 27.000 mg përbërës aktivë! Nuk kursejmë në dozim, që ju të mos keni nevojë të bëni kompromis me performancën tuaj.</p><p><strong>FORMULË PLOTËSISHT TRANSPARENTE</strong></p><p>Të gjitha formulat tona janë plotësisht të deklaruara. Nuk kemi nevojë të fshihemi pas emrave tingëllues si “përzierje pronësore”, të cilat në thelb nuk japin informacione të sakta për përbërësit e vërtetë dhe sasitë e tyre.</p><p><strong>SHIJE TË SHPËRBLYERA SHUMË HERË</strong></p><p>Edhe pse UNSTOPPABLE PUMP™ përmban sasi të mëdha përbërësish të fuqishëm, u kujdesëm që edhe një ekip ekspertësh të shijeve ta kryejë punën e vet. Rezultati është një suplement para stërvitjes pa stimulues që vërtet do të gëzoheni ta pini.</p><p><strong>PËRVOJË MAKSIMALE</strong></p><p>Sinergjia midis të gjithë përbërësve është ajo që vërtet e dallon UNSTOPPABLE PUMP™ nga produktet e tjera. Çdo përbërës është i pranishëm në dozë maksimale, jashtëzakonisht të lartë dhe vepron në harmoni të përsosur me përbërësit e tjerë. UNSTOPPABLE PUMP™ funksionon ndryshe nga të gjitha produktet që keni përdorur deri tani.</p><p>Asnjë suplement tjetër para stërvitjes pa stimulues nuk do t’ju ofrojë rezultatet e njëjta mbresëlënëse që mund t’i ofrojë vetëm UNSTOPPABLE PUMP™. Ky produkt revolucionar është vërtet i vetmi i këtij lloji dhe, si të gjitha produktet DEDICATED®, është krijuar për rezultate të shpejta. Sa të shpejta? Për vetëm 5 minuta!</p><p><strong>Sasia neto:</strong> 405 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza është 1/2 lugë matëse (13,5 g) për fillestarët dhe 1 lugë matëse e plotë (27 g) për përdoruesit e avancuar.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'FILLESTARËT: Merrni 1/2 lugë matëse 30 minuta para stërvitjes. TË AVANCUARIT: Merrni 1 lugë matëse të plotë 30 minuta para stërvitjes. PARALAJMËRIM: Ushqyerja e larmishme dhe e ekuilibruar dhe stili i shëndetshëm i jetesës janë të rëndësishme. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të larmishme. Ju lutemi konsultohuni me mjekun tuaj para përdorimit nëse keni ndonjë gjendje mjekësore. Nuk rekomandohet nëse jeni shtatzënë ose ushqeni me gji. Mos e përdorni nëse fleta mbrojtëse është e dëmtuar ose mungon. Përdoreni vetëm sipas udhëzimeve. Ruajeni në vend të freskët dhe të thatë. MBAJENI LARG FËMIJËVE. Lexoni të gjithë etiketën para përdorimit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1/2 lugë matëse në 250 ml dhe 1 lugë matëse në 200–300 ml ujë të ftohtë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2267;

-- Product_Id: 2268 (DEDICATED UNSTOPPABLE PRE-WORKOUT)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'DEDICATED UNSTOPPABLE PRE-WORKOUT' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement legjendar para stërvitjes për përmirësimin e performancës</p></li><li><p>Përbërës premium</p></li><li><p>“Pump” muskulor, performancë, energji, fokus dhe shije – TË GJITHA NË NJË</p></li><li><p>Shije të shpërblyera shumë herë</p></li><li><p>30 porcione</p></li></ul><p><strong>UNSTOPPABLE™ – Formulë legjendare nga gjenerata e re e suplementeve para stërvitjes!</strong></p><p><strong>Suplement ushqimor me ëmbëlsues.</strong></p><p><strong>Përmban kafeinë (195 mg/14 g; 390 mg/28 g). Nuk rekomandohet për fëmijë dhe gra shtatzëna.</strong></p><p>Suplementi legjendar para stërvitjes për përmirësim të menjëhershëm të performancës është avancuar në të gjitha aspektet – “pump” muskulor, performancë, energji, fokus DHE shije!</p><p>Thyerja e rekordeve, zbulimi i potencialit tuaj të vërtetë dhe tejkalimi i kufijve tuaj – pikërisht për këtë është krijuar UNSTOPPABLE™.</p><ul><li><p><strong>I FORMULUAR ME PËRBËRËS PREMIUM</strong></p></li><li><p><strong>DOZA TË LARTA DHE EFIKASITET</strong></p></li></ul><p>UNSTOPPABLE™ përmban përbërës jashtëzakonisht të fuqishëm, plotësisht të deklaruar dhe të dozuar në nivelin më të lartë të mundshëm për rezultate legjendare.</p><p><strong>Ndjejeni vetë, vetëm pak minuta pas konsumimit të UNSTOPPABLE™.</strong></p><p><strong>ENERGJI PA RËNIE TË NIVELEVE ENERGJETIKE</strong></p><p>Unstoppable™ përmban një kombinim të fuqishëm përbërësish stimulues që ju ndihmojnë të jepni maksimumin dhe t’i çoni stërvitjet deri në fund. Është i ekuilibruar në mënyrë të përsosur për të siguruar një nxitje energjie të njëtrajtshme dhe të qëndrueshme, pa ju lënë të rraskapitur pas stërvitjes.</p><p><strong>DOZA TË LARTA</strong></p><p>Unstoppable™ përmban përbërës jashtëzakonisht të fuqishëm në dozat më të larta të mundshme për rezultate legjendare. Nuk kursejmë në dozim, që ju të mos keni nevojë të bëni kompromis me performancën tuaj.</p><p><strong>FORMULË PLOTËSISHT TRANSPARENTE</strong></p><p>Të gjitha formulat tona janë plotësisht të deklaruara. Nuk kemi nevojë të fshihemi pas emrave tingëllues si “përzierje pronësore”, të cilat në thelb nuk japin informacione të vërteta për përbërësit dhe sasitë e tyre. 100% pa premtime boshe marketingu!</p><p><strong>SHIJE TË SHPËRBLYERA SHUMË HERË</strong></p><p>Edhe pse Unstoppable™ përmban sasi të mëdha përbërësish të fuqishëm, u kujdesëm që edhe një ekip ekspertësh të shijeve ta kryejë punën e vet. Rezultati është një suplement para stërvitjes që vërtet do të gëzoheni ta pini.</p><p><strong>BËHUNI TË PANDALSHËM</strong></p><p>Falë përbërësve të provuar dhe efikasë, të pranishëm në dozat më të larta të mundshme, Unstoppable™ ju ofron një përvojë intensive që do t’ju motivojë të thyeni rekorde dhe të tejkaloni kufijtë tuaj.</p><p>Nuk keni nevojë të na besoni vetëm neve – Unstoppable™ është shpërblyer shumë herë nga ekspertë dhe faqe interneti udhëheqëse të industrisë, që e njohin si suplement vërtet efikas para stërvitjes për thyerjen e rekordeve!</p><p>Unstoppable™ është krijuar me një qëllim të vetëm – të ofrojë përvojën maksimale para stërvitjes... SI ASNJË QË KENI PASUR DERI TANI!</p><p><strong>PËRVOJË MAKSIMALE</strong></p><p>Sinergjia midis të gjithë përbërësve është ajo që vërtet e dallon UNSTOPPABLE™ nga produktet e tjera. Çdo përbërës është i pranishëm në një dozë maksimale saktësisht të përcaktuar dhe vepron në harmoni të përsosur me përbërësit e tjerë.</p><p>UNSTOPPABLE™ funksionon ndryshe nga të gjitha produktet që keni përdorur deri tani. Asnjë suplement tjetër para stërvitjes nuk do t’ju ofrojë rezultatet e njëjta mbresëlënëse që mund t’i ofrojë vetëm UNSTOPPABLE™.</p><p>UNSTOPPABLE™ është produkt vërtet unik dhe revolucionar që, si të gjitha produktet DEDICATED®, siguron rezultate të shpejta!</p><p><strong>Ndjejeni efektin vetë. Është koha të bëheni TË PANDALSHËM!</strong></p><p><strong>PËRBËRËSIT AKTIVË:</strong></p><ul><li><p>L-citrulinë</p></li><li><p>Beta-alaninë</p></li><li><p>Betainë anhidre</p></li><li><p>Kafeinë anhidre – kafeinë e mjaftueshme për rritjen e energjisë, pa stimulim të tepërt</p></li><li><p>Ekstrakt gjethesh mango (Zynamite™) – ekstrakt i ri revolucionar stimulues, për të cilin thuhet se nuk shkakton efekte anësore</p></li><li><p>L-tirozinë</p></li><li><p>Vitamina B3 (niacinë)</p></li><li><p>Kalium dhe natrium – për hidratim optimal</p></li><li><p>Vitamina C</p></li><li><p>AstraGin® – përbërës që mund të rrisë thithjen, e me këtë edhe efikasitetin e të gjithë përbërësve në UNSTOPPABLE™, duke i ndihmuar të veprojnë më efikasisht.</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 420 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Doza është 1/2 lugë matëse (14 g) për fillestarët dhe 1 lugë matëse e plotë (28 g) për përdoruesit e avancuar.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'FILLESTARËT: Merrni 1/2 lugë matëse 30 minuta para stërvitjes. TË AVANCUARIT: Merrni 1 lugë matëse të plotë 30 minuta para stërvitjes. PARALAJMËRIM: Ushqyerja e larmishme dhe e ekuilibruar dhe stili i shëndetshëm i jetesës janë të rëndësishme. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të larmishme. Ju lutemi konsultohuni me mjekun tuaj para përdorimit nëse keni ndonjë gjendje mjekësore. Nuk rekomandohet nëse jeni shtatzënë ose ushqeni me gji. Mos e përdorni nëse fleta mbrojtëse është e dëmtuar ose mungon. Përdoreni vetëm sipas udhëzimeve. Ruajeni në vend të freskët dhe të thatë. MBAJENI LARG FËMIJËVE. Lexoni të gjithë etiketën para përdorimit. Përmban kafeinë (195 mg për 14 g; 390 mg për 28 g). Ky produkt nuk duhet të përdoret në kombinim me kafeinë ose stimulues nga burime të tjera. Marrja ditore prej 400 mg kafeinë nuk duhet të tejkalohet.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1/2 lugë matëse në 250 ml dhe 1 lugë matëse në 200–300 ml ujë të ftohtë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2268;

-- Product_Id: 2270 (BODY ATTACK 100% PURE CREATINE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BODY ATTACK 100% PURE CREATINE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Kreatinë monohidrat</p></li><li><p>Pluhur mikro-i imët pa shtesa</p></li><li><p>Produkt i Cologne List</p></li></ul><p><strong>Suplement ushqimor me kreatinë monohidrat, i destinuar për të rriturit që praktikojnë aktivitet fizik me intensitet të lartë.</strong></p><p><strong>Rritni forcën tuaj maksimale!</strong></p><p>Pavarësisht nëse bëhet fjalë për sprintin përfundimtar apo përsëritjen e fundit në stërvitje, me Body Attack 100% Pure Creatine Powder mund t’i shtyni kufijtë dhe të arrini performancat tuaja më të mira fizike! Pluhuri mikro-i imët i kreatinës monohidrat mahnit me përbërjen e tij të pastër, pa shtesa, dhe tretet shkëlqyeshëm në lëng frutash ose ujë, duke ju ndihmuar të jeni një hap përpara të tjerëve.</p><p>100% Pure Creatine është zgjedhje e shkëlqyer për mbështetjen e qëllimeve të mëposhtme:</p><ul><li><p>Rritja e forcës</p></li><li><p>Seanca stërvitore më intensive</p></li><li><p>Ruajtja e masës muskulore</p></li><li><p>Rikuperim më i shpejtë</p></li></ul><p><strong>Për kë është i përshtatshëm 100% Pure Creatine?</strong></p><ul><li><p>Ushtrues fitnesi</p></li><li><p>Sportistë</p></li><li><p>Sportistë në sportet e forcës</p></li><li><p>Sportistë në sportet e qëndrueshmërisë dhe lojërat sportive</p></li><li><p>Persona që duan të shtojnë peshën trupore</p></li></ul><p><strong>Kreatina – ari i bardhë</strong></p><p>Kreatina është substancë natyrale që trupi e prodhon vetë nga aminoacidet glicinë, argininë dhe metioninë, në mëlçi, veshka dhe pankreas. Ekzistojnë disa forma të kreatinës, por monohidrati thithet veçanërisht lehtë në organizëm dhe për këtë arsye është përbërësi aktiv në 100% Pure Creatine. Shfrytëzojeni këtë përparësi për të përmirësuar performancën fizike gjatë stërvitjes.</p><p><strong>Përfitime të qarta</strong></p><p>Rritni forcën maksimale gjatë stërvitjes dhe përmirësoni shpejtësinë gjatë stërvitjeve intensive të qëndrueshmërisë. 100% Pure Creatine është produkt vërtet i gjithanshëm dhe partner i shkëlqyer për të gjithë.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 300 g / 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 2 lugë matëse (3,4 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion dy herë në ditë me lëng të mjaftueshëm (300 ml), mundësisht para dhe pas stërvitjes intensive. Në ditët kur nuk stërviteni, merrni 1 porcion dy herë në ditë me lëng të mjaftueshëm (300 ml) – herën e parë në mëngjes menjëherë pas zgjimit, dhe herën e dytë para gjumit. PARALAJMËRIM: Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Pas hapjes, përdoreni produktin sa më shpejt të jetë e mundur. Mbajeni larg nxehtësisë dhe dritës së drejtpërdrejtë.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2270;

-- Product_Id: 2272 (OPTIMUM ELECTROLYTE POWDER)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OPTIMUM ELECTROLYTE POWDER' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Përzierje efikase elektrolitesh (natrium, magnez, kalium) që mbështet hidratimin dhe nivelin e energjisë</p></li><li><p>Për stërvitje intensive ose të qëndrueshmërisë</p></li><li><p>Pa sheqer dhe shtesa të panevojshme</p></li><li><p>Tretet lehtë dhe freskon</p></li></ul><p><strong>Suplement ushqimor me elektrolite, në formë pluhuri me ëmbëlsues, i destinuar për përgatitjen e pijes.</strong></p><p><strong>Çfarë janë elektrolitet?</strong></p><p>Elektrolitet janë minerale esenciale, ndër të cilat natriumi, kaliumi dhe magnezi, që luajnë rol të rëndësishëm në funksione të ndryshme fiziologjike. Ky pluhur freskues elektrolitesh është formuluar për të siguruar minerale kyçe në sasi të sakta, duke ju ndihmuar të jeni gati para, gjatë ose pas aktivitetit fizik të lodhshëm.</p><p><strong>Përfitimet për performancën:</strong></p><ul><li><p>Siguron 400 mg natrium, 300 mg kalium** dhe 113 mg magnez* për porcion</p></li><li><p>Kaliumi kontribuon në funksionin normal të muskujve**</p></li><li><p>Magnezi kontribuon në ruajtjen e ekuilibrit të elektroliteve dhe ndihmon në uljen e lodhjes dhe rraskapitjes*</p></li><li><p>Pa sheqer dhe shtesa të panevojshme</p></li></ul><p><strong>Kur ta përdorni këtë produkt?</strong></p><ul><li><p><strong>Para stërvitjes:</strong> Përgatitni organizmin me elektrolite esenciale.</p></li><li><p><strong>Gjatë stërvitjes:</strong> Mbështetni marrjen e mineraleve gjatë stërvitjeve të gjata ose intensive.</p></li><li><p><strong>Pas stërvitjes:</strong> Rikuperoni mineralet e humbura përmes djersitjes.</p></li></ul><p><strong>Pse ta zgjidhni këtë produkt?</strong></p><p>Me më shumë se 35 vjet përvojë në ushqyerjen sportive dhe prani në më shumë se 90 vende, Optimum Nutrition ofron cilësi të lartë mbi të cilën mund të mbështeteni. Kjo formulë me elektrolite tretet shpejt, përzihet lehtë dhe është e disponueshme në shije freskuese limoni dhe frutash pyjore. Është projektuar për të mbështetur stilin tuaj aktiv të jetesës, pa sheqer të shtuar dhe përbërës të panevojshëm.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 33 porcione (264 g)</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 8 g (~1 lugë matëse e plotë).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Përdorimi i rekomanduar: 1 porcion në ditë. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk është zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Nëse përdorni barna ose keni ndonjë gjendje shëndetësore, konsultohuni me një punonjës shëndetësor para përdorimit. Mos e përdorni gjatë shtatzënisë dhe ushqyerjes me gji. MËNYRA E RUAJTJES: Ruajeni në vend të freskët dhe të thatë, të mbrojtur nga drita e drejtpërdrejtë e diellit.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Shtoni 1 porcion në 450 ml ujë të ftohtë dhe përzieni derisa pluhuri të tretet plotësisht.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2272;

-- Product_Id: 2273 (OLIMP GOLD-VIT B FORTE, 60 tabs)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP GOLD-VIT B FORTE, 60 tableta' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Kompleks vitaminash të grupit B</li><li>Mbështet metabolizmin e lëndëve ushqyese dhe prodhimin e energjisë</li><li>I destinuar për sportistë dhe persona me stil jetese stresues</li></ul><h3>.</h3><p>GOLD-VIT B FORTE është suplement ushqimor në formë tabletash, me kompleks vitaminash të grupit B, të domosdoshme për zhvillimin e duhur të shumë proceseve në organizëm. Vitamina B2, niacina dhe biotina kontribuojnë në funksionimin normal të sistemit nervor, si dhe në ruajtjen e lëkurës normale. Përveç kësaj, biotina kontribuon në metabolizmin normal të makronutrientëve.</p><p>Vitaminat B6 dhe B12 kontribuojnë në formimin normal të qelizave të kuqe të gjakut. Folati kontribuon në formimin normal të gjakut, si dhe në sintezën normale të aminoacideve, gjë që është veçanërisht e rëndësishme gjatë aktivitetit fizik intensiv.</p><p>Burimi: https://en.olimp-labs.com/</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 tabletë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë. PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2273;

-- Product_Id: 2274 (CH Alpha)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'CH Alpha' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<h3>ch</h3><p>CH-ALPHA<br>Degjenerimi i kërcit në nyje mund të jetë shkak i humbjes së elasticitetit dhe ngurtësisë së shtuar në ato nyje që mbajnë ngarkesën më të madhe, si gjunjët dhe ijet. Kjo mund të shkaktohet nga ushtrimet e tepërta, lëvizjet përsëritëse ose pesha trupore e shtuar, si dhe nga jeta joaktive me pak lëvizje. Zakonisht fillon në dekadën e tretë të jetës dhe përparon me kalimin e viteve.</p><p>Çfarë është kërci?</p><p>Kërci është ind i fortë dhe elastik që mbulon të gjitha nyjet dhe i mbron kockat nga fërkimi me njëra-tjetrën. Kërci është sipërfaqe e lëmuar që mundëson rrëshqitjen e butë të kockave kur lëvizin dhe ndihmon në thithjen e presionit gjatë aktivitetit fizik.</p><p>Kërci i nyjeve përmban kolagjen të tipit II dhe proteoglikane në substancën ndërqelizore, përgjegjëse për fortësinë dhe elasticitetin.</p><p>Kjo substancë ndërqelizore përbëhet kryesisht nga uji, kolagjeni i tipit II (që siguron fortësi dhe njëkohësisht lubrifikim) dhe proteoglikanet (që parandalojnë shtypjen).</p><p>Është me rëndësi jetike të ruhet niveli normal i kolagjenit në indet e kockave, kërcit, ligamenteve dhe nyjeve! Lëvizja e shëndetshme dhe normale e trupit është themelore!</p><p>Kur procesi natyral rigjenerues nuk mund t’i plotësojë nevojat ditore të organizmit, për shkak të lëndimeve, peshës së tepërt ose ushtrimeve të tepërta, atëherë indi lidhor dëmtohet.</p><p>Ndërsa indi lidhor humbet, humbet edhe lëngu, fërkimi rritet, gjë që çon në elasticitet të zvogëluar dhe rritje graduale të ndjesisë së shqetësimit dhe dhimbjes.</p><p>Qelizat e veçanta, kondrocitet, kontrollojnë nivelin e rigjenerimit të kërcit në nyje dhe njohin ndryshimet në strukturën e kërcit. Kur gjendja ndryshon, kondrocitet reagojnë duke e rindërtuar kërcin e konsumuar.</p><p>Në mënyrë jo tipike për çdo ind tjetër të trupit, kërci nuk përmban nerva ose enë gjaku. Kjo kontribuon në rigjenerim shumë të ngadaltë, si dhe në trajtim më të vështirë. Kërci është ind që rritet në mënyrë aktive dhe ka nevojë për rigjenerim të vazhdueshëm, për të mund ta kryejë funksionin e tij si mbrojtës i nyjeve.</p><p>Kush përfiton nga CH-ALPHA?</p><p>Shumë thjesht, kushdo që është i interesuar të përmirësojë lëvizshmërinë dhe cilësinë e jetës.</p><p>Njerëzit që përfitojnë nga CH-ALPHA:</p><p>Ata që punojnë me ngritjen e ngarkesave të rënda.</p><p>Njerëzit që bëjnë punë përsëritëse dhe rraskapitëse.</p><p>Njerëzit me peshë trupore të tepërt.</p><p>Njerëzit fizikisht joaktivë.</p><p>Sportistët.</p><p>A është CH-ALPHA i sigurt për përdorim?</p><p>Sipas studimeve mjekësore, nuk ka ndërveprime të njohura me barna të tjera ose me çfarëdo ushqimi.</p><p>Nuk ka raportime për reaksione alergjike.</p><p>30 ampula<br>Dozimi: 1 ampulë në ditë</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Dozimi: 1 ampulë në ditë' ELSE InstructionsForUseAl END
WHERE Product_Id = 2274;

-- Product_Id: 2275 (VAST V8 ULTRA)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'VAST V8 ULTRA' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Përforcues 4-në-1 para stërvitjes për performancë të lartë</p></li><li><p>Me 7 përbërës të patentuar</p></li><li><p>Me TriBsyn™ – beta-alaninë pa ndjesi thumbimi</p></li><li><p>I përsosur për stërvitje të gjata dhe ngarkesa të mëdha fizike</p></li><li><p>Pije e shijshme pa sheqer</p></li><li><p>20 porcione</p></li></ul><p><strong>Suplement ushqimor, i destinuar veçanërisht për sportistë. Pluhur për përgatitjen e pijes me aminoacide dhe ekstrakte bimore, me ëmbëlsues.</strong></p><p><strong>Përmbajtje e lartë kafeine (300 mg/18,2 g). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</strong></p><p>V8 ULTRA shënon fillimin e një epoke të re në stërvitje. Me 7 përbërës aktivë të patentuar, doza të provuara klinikisht dhe veprim pa kompromis, është i destinuar për të gjithë ata që duan të tejkalojnë kufijtë standardë.</p><p>V8 ULTRA është suplementi i parë para stërvitjes në Evropë që përmban TriBsyn™ – formë e re e beta-alaninës me teknologji hidro-oleo, e cila mundëson thithje të mirë pa ndjesinë tipike të thumbimit.</p><p><strong>FORMULË 4-NË-1 PARA STËRVITJES</strong></p><p><strong>Performancë. Fokus. “Pump” muskulor. Hidratim.</strong></p><p>V8 ULTRA kombinon teknologjitë më të reja në një formulë për performancë të lartë. Është projektuar për të siguruar pikërisht ato përfitime që janë të rëndësishme në çdo fazë të stërvitjes.</p><p>Nga ngrohja deri te përsëritja e fundit, formula 4-në-1 ju siguron energjinë, qartësinë mendore dhe qëndrueshmërinë e nevojshme për të nxjerrë maksimumin nga çdo stërvitje.</p><p><strong>Arrini maksimumin. Çdo herë.</strong></p><p><strong>PËRPARËSITË KYÇE:</strong></p><ul><li><p>Përforcues premium 4-në-1 para stërvitjes për performancë të lartë</p></li><li><p>Formula e parë në treg me 7 përbërës të patentuar</p></li><li><p>Me TriBsyn™ – beta-alaninë e gjeneratës më të re që nuk shkakton ndjesi thumbimi</p></li><li><p>Peak ATP®</p></li><li><p>300 mg PurCaf® – kafeinë natyrale nga kokrrat e gjelbra të kafesë¹</p></li><li><p>8 g citrulinë malat, 2,5 g BetaPower® dhe S7® – aminoacide dhe ekstrakte bimore</p></li><li><p>50 mg Senactiv® – kompleks ekstraktesh bimore</p></li><li><p>1600 mg VitaCholine™</p></li><li><p>Matricë elektrolitesh nga kripa rozë e Himalajeve, magnezi dhe kaliumi</p></li><li><p>I përsosur për stërvitje intensive me pesha, ngritje peshash për forcë, Hyrox dhe HIIT. Ideal për stërvitje të gjata dhe ngarkesa të mëdha fizike.</p></li><li><p>3 variante të shijshme pa sheqer: qershi e zezë dhe limetë, mjedër blu, limonadë rozë</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 364 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 lugë matëse (18,2 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 1 porcion 20–30 minuta para stërvitjes ose aktivitetit sportiv. Përdorimi i rekomanduar ditor: 1 porcion. PARALAJMËRIM: Përmbajtje e lartë kafeine (300 mg/18,2 g). Nuk rekomandohet për fëmijë, gra shtatzëna ose gra që ushqejnë me gji. Rekomandohet të mos merren më shumë se 400 mg kafeinë në ditë. Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion me 300 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2275;

-- Product_Id: 2276 (SPORTNAHRUNG SUPER BOOST)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'SPORTNAHRUNG SUPER BOOST' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Përforcues 4-në-1 para stërvitjes për performancë të lartë</p></li><li><p>Me 7 përbërës të patentuar</p></li><li><p>Me TriBsyn™ – beta-alaninë pa ndjesi thumbimi</p></li><li><p>I përsosur për stërvitje të gjata dhe ngarkesa të mëdha fizike</p></li><li><p>Pije e shijshme pa sheqer</p></li><li><p>20 porcione</p></li></ul><p><strong>Suplement ushqimor, i destinuar veçanërisht për sportistë. Pluhur për përgatitjen e pijes me aminoacide dhe ekstrakte bimore, me ëmbëlsues.</strong></p><p><strong>Përmbajtje e lartë kafeine (300 mg/18,2 g). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</strong></p><p>V8 ULTRA shënon fillimin e një epoke të re në stërvitje. Me 7 përbërës aktivë të patentuar, doza të provuara klinikisht dhe veprim pa kompromis, është i destinuar për të gjithë ata që duan të tejkalojnë kufijtë standardë.</p><p>V8 ULTRA është suplementi i parë para stërvitjes në Evropë që përmban TriBsyn™ – formë e re e beta-alaninës me teknologji hidro-oleo, e cila mundëson thithje të mirë pa ndjesinë tipike të thumbimit.</p><p><strong>FORMULË 4-NË-1 PARA STËRVITJES</strong></p><p><strong>Performancë. Fokus. “Pump” muskulor. Hidratim.</strong></p><p>V8 ULTRA kombinon teknologjitë më të reja në një formulë për performancë të lartë. Është projektuar për të siguruar pikërisht ato përfitime që janë të rëndësishme në çdo fazë të stërvitjes.</p><p>Nga ngrohja deri te përsëritja e fundit, formula 4-në-1 ju siguron energjinë, qartësinë mendore dhe qëndrueshmërinë e nevojshme për të nxjerrë maksimumin nga çdo stërvitje.</p><p><strong>Arrini maksimumin. Çdo herë.</strong></p><p><strong>PËRPARËSITË KYÇE:</strong></p><ul><li><p>Përforcues premium 4-në-1 para stërvitjes për performancë të lartë</p></li><li><p>Formula e parë në treg me 7 përbërës të patentuar</p></li><li><p>Me TriBsyn™ – beta-alaninë e gjeneratës më të re që nuk shkakton ndjesi thumbimi</p></li><li><p>Peak ATP®</p></li><li><p>300 mg PurCaf® – kafeinë natyrale nga kokrrat e gjelbra të kafesë¹</p></li><li><p>8 g citrulinë malat, 2,5 g BetaPower® dhe S7® – aminoacide dhe ekstrakte bimore</p></li><li><p>50 mg Senactiv® – kompleks ekstraktesh bimore</p></li><li><p>1600 mg VitaCholine™</p></li><li><p>Matricë elektrolitesh nga kripa rozë e Himalajeve, magnezi dhe kaliumi</p></li><li><p>I përsosur për stërvitje intensive me pesha, ngritje peshash për forcë, Hyrox dhe HIIT. Ideal për stërvitje të gjata dhe ngarkesa të mëdha fizike.</p></li><li><p>3 variante të shijshme pa sheqer: qershi e zezë dhe limetë, mjedër blu, limonadë rozë</p></li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 364 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 3 lugë matëse (20 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni 30 minuta para stërvitjes. Nuk duhet të konsumohet me stomak bosh. Sasia maksimale ditore është 1 porcion (20 g). PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve të vegjël. Nuk duhet ta konsumojnë gratë shtatzëna, gratë që ushqejnë me gji, personat nën 18 vjeç dhe personat me çrregullime kardiovaskulare. MËNYRA E RUAJTJES: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion (20 g) në 500 ml ujë të ftohtë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2276;

-- Product_Id: 2277 (SPORTNAHRUNG EAA LOADED)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'SPORTNAHRUNG EAA LOADED' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p></p><ul><li>7,4 g aminoacide për porcion (15 g)</li><li>Të 9 aminoacidet esenciale (EAA) + L-glutaminë dhe taurinë</li><li>Me magnez dhe vitaminë B6 të shtuar për uljen e lodhjes dhe metabolizëm normal energjetik</li><li>Shije freskuese frutash</li><li>22 porcione</li></ul><p><strong>EAA Loaded – 7,4 g aminoacide. Një formulë. Shije freskuese frutash.</strong></p><p>Kur doni më shumë nga formula juaj me aminoacide, zgjidhni EAA Loaded.</p><p>EAA Loaded kombinon të <strong>9 aminoacidet esenciale</strong> me aminoacidet shtesë <strong>L-glutaminë</strong> dhe <strong>taurinë</strong>. Kështu, një porcion prej 15 g siguron gjithsej <strong>7.469 mg aminoacide.</strong></p><p>Aminoacidet janë njësitë themelore ndërtuese të proteinave dhe kanë rol të rëndësishëm në ushqyerjen sportive. Ndër to janë edhe <strong>aminoacidet esenciale (EAA)</strong>, të cilat trupi i njeriut nuk mund t’i prodhojë vetë në sasi të mjaftueshme dhe për këtë arsye duhet të merren përmes ushqyerjes. Aminoacidet esenciale janë: <strong>leucina, izoleucina, valina, lizina, treonina, metionina, fenilalanina, triptofani dhe histidina.</strong></p><p>Për vlerë shtesë, formula është e pasuruar me <strong>magnez</strong> dhe <strong>vitaminë B6</strong>. Magnezi kontribuon në funksionimin normal të muskujve dhe sistemit nervor, si dhe në uljen e lodhjes dhe rraskapitjes, ndërsa vitamina B6 kontribuon në metabolizmin normal energjetik dhe në uljen e lodhjes dhe rraskapitjes.</p><p>E gjithë kjo plotësohet me shije të këndshme pjeshke ose luleshtrydhe/qershie, që mundëson përvojë freskuese me çdo porcion. EAA Loaded është i destinuar për të gjithë ata që kërkojnë një kombinim cilësor dhe praktik aminoacidesh dhe mikronutrientësh të përzgjedhur në një formulë.</p><p><strong>Pse të zgjidhni EAA Loaded?</strong></p><ul><li>7.469 mg aminoacide për porcion</li><li>Të 9 aminoacidet esenciale (EAA)</li><li>L-glutaminë dhe taurinë shtesë</li><li>191 mg magnez për porcion (51% MRD)</li><li>1,62 mg vitaminë B6 për porcion (116% MRD)</li><li>Shije freskuese frutash</li><li>22 porcione</li></ul><p><em>Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</em></p><p><strong>Sasia neto:</strong> 330 g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 2 lugë matëse (15 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni gjatë aktivitetit fizik. Lëreni pijen të qëndrojë pak që pluhuri të tretet më mirë. Doza maksimale ditore është 1 porcion (15 g). PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! MËNYRA E RUAJTJES: Ruajeni në vend të errët dhe të thatë, në temperaturë deri në 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 600–800 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2277;

-- Product_Id: 2278 (OLIMP CHELA-MAG B6 CRAMP, 20 шумливи таблети)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'OLIMP CHELA-MAG B6 CRAMP, 20 tableta shkumëzuese' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>100 mg magnez dhe 300 mg kalium për tabletë shkumëzuese</p></li><li><p>Për funksionimin normal të muskujve dhe sistemit nervor</p></li><li><p>Thithje e shkëlqyer</p></li><li><p>Me vitamina B1, B2, B3, B6, B12 dhe biotinë të shtuara</p></li></ul><p><strong>PËR FUNKSIONIMIN NORMAL TË MUSKUJVE</strong></p><p>Chela-Mag B6 Cramp është suplement ushqimor në formë tabletash shkumëzuese, që përmban formë me thithje të lartë të magnezit në trajtën e kelatit aminoacid Albion (bisglicinat magnezi), si dhe formë me thithje të lartë të kaliumit. Këta përbërës kontribuojnë në funksionimin normal të muskujve, dhe së bashku me vitaminat B1, B2, B3, B6, B12 dhe biotinën mbështesin funksionimin normal të sistemit nervor.</p><p>Kërkimet shkencore kanë treguar se <strong>magnezi</strong> është mineral i domosdoshëm për jetën e njeriut dhe merr pjesë pothuajse në të gjitha proceset që zhvillohen në organizëm. Është i rëndësishëm për funksionimin normal të muskujve dhe sistemit nervor, ndihmon në ruajtjen e ekuilibrit të elektroliteve dhe kontribuon në sintezën e proteinave. Gjithashtu kontribuon në uljen e lodhjes dhe rraskapitjes. Prania e tij është e domosdoshme edhe për ruajtjen e strukturës normale të kockave dhe dhëmbëve.</p><p><strong>Vitamina B6</strong> merr pjesë në thithjen e magnezit nga trakti gastrointestinal dhe së bashku me magnezin merr pjesë në shumë procese që zhvillohen në organizëm.</p><p><strong>Kaliumi</strong> ka rol të rëndësishëm në funksionimin e muskujve dhe sistemit nervor. Gjithashtu kontribuon në ruajtjen e presionit normal të gjakut.</p><p>Burimi: https://en.olimp-labs.com/</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 tabletë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar. Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm. Mbajeni larg fëmijëve. Mos e përdorni në rast mbindjeshmërie ndaj ndonjërit prej përbërësve.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 200 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2278;

-- Product_Id: 2279 (SPORTNAHRUNG CREATINE CHEWABLE TABLETS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'SPORTNAHRUNG CREATINE CHEWABLE TABLETS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Tableta të shijshme për përtypje me kreatinë, me shije portokalli ose qershie</p></li><li><p>Mbështesin rritjen dhe ruajtjen e masës muskulore</p></li><li><p>Rrisin performancën fizike</p></li><li><p>Ideale për përdorim në lëvizje</p></li></ul><p><strong>Suplement ushqimor me kreatinë, sheqerna dhe ëmbëlsues.</strong></p><p>Tabletat e reja për përtypje me kreatinë nga sportnahrung.at janë ideale për të gjithë sportistët që duan mbështetje shtesë për arritjen e qëllimeve të tyre sportive. Kreatina mbështet rritjen e muskujve, kontribuon në ruajtjen e masës muskulore dhe rrit performancën fizike.</p><p>Forma praktike e tabletave për përtypje, me shije të shkëlqyer portokalli ose qershie, ju mundëson ta mbani lehtë kreatinën me vete kudo që të shkoni.</p><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 200 tableta</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 4 tableta.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 1 porcion në ditë, ndërmjet vakteve ose menjëherë pas stërvitjes. Gjatë përdorimit të kreatinës siguroni marrje të mjaftueshme ditore të lëngjeve. PARALAJMËRIM: Përdorimi rekomandohet vetëm për të rriturit që janë fizikisht aktivë dhe duhet të kufizohet në maksimum 8 javë, pas të cilave nevojitet një pushim prej të paktën 4 javësh. Kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet shumë të lartë (efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë). Mos e tejkaloni dozën e rekomanduar ditore. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve! Ruajeni në vend të freskët dhe të thatë. Mos e ekspozoni ndaj dritës së drejtpërdrejtë të diellit.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2279;

-- Product_Id: 2280 (PROTEINI.SI PROTEIN BROWNIE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI PROTEIN BROWNIE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Brownie i pasur dhe i lëngshëm me çokollatë të zezë</li><li>Përmbajtje e lartë proteinash</li><li>Teksturë e butë dhe e lëngshme</li><li>Përmbajtje e ulët sheqernash</li><li>Ideal si rostiçeri praktike në lëvizje</li></ul><p><strong>Produkt furre me përmbajtje të lartë proteinash, me sheqer dhe ëmbëlsues.</strong></p><p>Shijoni shijen e pasur të çokollatës së zezë dhe njëkohësisht merrni një sasi shtesë proteinash. Protein Brownie ynë kombinon teksturë të butë dhe të lëngshme me shije intensive çokollate, gjë që e bën rostiçerinë ideale për stil jetese aktiv, pas stërvitjes ose sa herë që dëshironi diçka të ëmbël pa bërë kompromis me ushqyerjen.</p><p>I prodhuar me të bardhë veze, proteinë whey dhe miell bajameje, çdo brownie siguron 17 g proteina për 100 g dhe kontribuon në ruajtjen dhe rikuperimin e muskujve. Është i ëmbëlsuar me një kombinim sheqeri dhe ëmbëlsuesish dhe ofron shije të shkëlqyer me vetëm 2 g sheqerna për 100 g.</p><p><strong>Pse do t’ju pëlqejë:</strong></p><ul><li>Shije e pasur çokollate të zezë</li><li>Përmbajtje e lartë proteinash – 17 g për 100 g</li><li>Vetëm 2 g sheqerna për 100 g</li><li>Teksturë e butë dhe e lëngshme</li><li>Me copa çokollate</li><li>I shkëlqyer si rostiçeri, ëmbëlsirë ose pas stërvitjes</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 60 g / 15 x 60 g</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2280;

-- Product_Id: 2281 (USN CREATINE MONOHYDRATE - RED FRUIT PUNCH)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN CREATINE MONOHYDRATE - RED FRUIT PUNCH' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Kreatinë monohidrat në formë të mikronizuar</p></li><li><p>Version me shije – i disponueshëm në dy shije të shijshme frutash</p></li><li><p>Ndihmon në ruajtjen e niveleve të energjisë gjatë kontraktimeve muskulore</p></li><li><p>Ndihmon në rritjen e masës muskulore</p></li><li><p>Thithje dhe rikuperim i shpejtë</p></li></ul><p><strong>Suplement ushqimor me kreatinë monohidrat, me ëmbëlsues.</strong></p><p>Kreatina monohidrat e mikronizuar e USN, në formë të pastër dhe me thithje të lartë, <strong>tani është e disponueshme edhe në version me shije</strong>, në <strong>dy shije të lëngshme frutash</strong> – punç frutash të kuqe dhe shije tropikale.</p><p>Me marrje ditore prej të paktën 3 g kreatinë, kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Gjatë kontraktimeve muskulore, ndihmon në ruajtjen e ekuilibrit të nivelit të ATP-së.</p><p>Suplementi ushqimor me kreatinë monohidrat është i sigurt dhe i përshtatshëm për të gjithë ata që stërviten me intervale të shkurtra dhe intensive. Rekomandojmë marrjen e 3–5 g kreatinë monohidrat menjëherë pas stërvitjes, së bashku me proteinë whey dhe karbohidrate, për thithje optimale të lëndëve ushqyese dhe rikuperim të përmirësuar.</p><p>Kreatina është komponim organik azotik që gjendet natyrshëm te të gjithë vertebrorët. Përqendrimet më të larta janë të pranishme në indin muskulor. Kreatina shërben si komponim me energji të lartë që siguron energji të shpejtë, veçanërisht për indin muskulor, ku në një periudhë të shkurtër duhet të shfrytëzohet një sasi relativisht e madhe ATP. Marrja e kreatinës përmes suplementimit rrit përqendrimin e kreatinës në muskuj. Kreatina mund, deri në një shkallë të caktuar, të rrisë forcën muskulore, veçanërisht gjatë aktiviteteve sportive anaerobe (afatshkurtra). Gjithashtu rrit masën muskulore përmes rritjes së mbajtjes së ujit në muskuj.</p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit është 1 lugë matëse (6,3 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Mos konsumoni më shumë se 4 porcione në ditë. Është e rëndësishme të merrni çdo ditë lëngje të mjaftueshme. PARALAJMËRIM: Konsultohuni me mjekun tuaj para përdorimit nëse përdorni barna ose ju është diagnostikuar ndonjë gjendje shëndetësore. Nuk rekomandohet për gra shtatzëna, gra që ushqejnë me gji dhe persona nën 18 vjeç. Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk duhet të përdoren si zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe stil jetese të shëndetshëm. Mbajeni larg fëmijëve! Ruajeni në vend të freskët dhe të thatë.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 porcion (6,3 g) me 250 ml ujë të ftohtë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2281;

-- Product_Id: 2283 (PROTEINI.SI RESISTANCE BAND, 70cm, medium difficulty (green))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI RESISTANCE BAND, 70cm, vështirësi mesatare (e gjelbër)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shirit elastik rezistence në formë rrethi të mbyllur, me perimetër 70 cm</p></li><li><p>I përshtatshëm për stërvitjen e të gjithë trupit</p></li><li><p>Mjet i popullarizuar stërvitjeje te femrat</p></li><li><p>Mundëson ushtrime efikase për forcimin e kofshëve dhe gluteusëve</p></li><li><p><strong>Rezistenca:</strong> mesatare (e gjelbër)</p></li></ul><p>Shiriti elastik rezistence prej poliestri, në formë rrethi të mbyllur, mundëson stërvitjen e të gjithë trupit. Mund të përdoret edhe për simulimin e ushtrimeve në pajisjet e fitnesit në palestër. Shiriti siguron rezistencë të mirë gjatë aktivizimit të muskujve në të dy drejtimet e lëvizjes. Mundëson lëvizje në të gjitha drejtimet, shpërndarje më të mirë të përpjekjes muskulore dhe kryerje të saktë të ushtrimeve.</p><p>Mund të përdoret për forcimin e shumicës së grupeve muskulore, për pilates, formësimin e muskujve, rehabilitim mjekësor ose shtrirje në shtëpi dhe në palestër. Është veçanërisht i popullarizuar te femrat sepse mundëson kryerjen e ushtrimeve shumë efikase për kofshët dhe gluteusët.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p><strong>Rezistenca:</strong> mesatare</p></li><li><p><strong>Përmasat:</strong> perimetri 70 cm, gjerësia 5,5 cm</p></li><li><p><strong>Materiali:</strong> poliestër</p></li><li><p><strong>Ngjyra:</strong> e gjelbër</p></li></ul><p><strong>PËRPARËSITË:</strong></p><ul><li><p>Përdorim shumëqëllimësh</p></li><li><p>I lehtë dhe praktik për t’u mbajtur</p></li><li><p>I rehatshëm për përdorim</p></li><li><p>Nuk rrëshqet lart ose poshtë gjatë ushtrimit</p></li><li><p>Përmirëson cilësinë e stërvitjes dhe fleksibilitetin e muskujve</p></li></ul><p><strong>Sasia neto:</strong> 1 shirit elastik rezistence / paketim</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2283;

-- Product_Id: 2284 (PROTEINI.SI RESISTANCE BAND, 70cm, X-heavy difficulty (black))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI RESISTANCE BAND, 70cm, vështirësi ekstra e lartë (e zezë)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shirit elastik rezistence në formë rrethi të mbyllur, me perimetër 70 cm</p></li><li><p>I përshtatshëm për stërvitjen e të gjithë trupit</p></li><li><p>Mjet i popullarizuar stërvitjeje te femrat</p></li><li><p>Mundëson ushtrime efikase për forcimin e kofshëve dhe gluteusëve</p></li><li><p><strong>Rezistenca:</strong> ekstra e fortë (e zezë)</p></li></ul><p>Shiriti elastik rezistence prej poliestri, në formë rrethi të mbyllur, mundëson stërvitjen e të gjithë trupit. Mund të përdoret edhe për simulimin e ushtrimeve në pajisjet e fitnesit në palestër. Shiriti krijon rezistencë të mirë muskulore në çdo ushtrim dhe në të dy drejtimet e lëvizjes. Mundëson lëvizje në të gjitha drejtimet, shpërndarje më të mirë të përpjekjes muskulore dhe kryerje të saktë të ushtrimeve.</p><p>Mund të përdoret për forcimin e shumicës së grupeve muskulore, për pilates, formësimin e muskujve, rehabilitim mjekësor ose shtrirje në shtëpi dhe në palestër. Është veçanërisht i popullarizuar te femrat sepse mundëson kryerjen e ushtrimeve shumë efikase për kofshët dhe gluteusët.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p><strong>Rezistenca:</strong> ekstra e fortë</p></li><li><p><strong>Përmasat:</strong> perimetri 70 cm, gjerësia 5,5 cm</p></li><li><p><strong>Materiali:</strong> poliestër</p></li><li><p><strong>Ngjyra:</strong> e zezë</p></li></ul><p><strong>PËRPARËSITË:</strong></p><ul><li><p>Përdorim shumëqëllimësh</p></li><li><p>I lehtë dhe praktik për t’u mbajtur</p></li><li><p>I rehatshëm për përdorim</p></li><li><p>Nuk rrëshqet lart ose poshtë gjatë ushtrimit</p></li><li><p>Përmirëson cilësinë e stërvitjes dhe fleksibilitetin e muskujve</p></li></ul><p><strong>Sasia neto:</strong> 1 shirit elastik rezistence / paketim</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2284;

-- Product_Id: 2285 (PROTEINI.SI BOOTY HIP BAND, M, TURQUOISE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI BOOTY HIP BAND, M, BRUZ' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shirit elastik prej pëlhure për stërvitjen e ijeve dhe gluteusëve</p></li><li><p>Për tonifikimin e muskujve, formësimin e trupit dhe aktivizim më të madh të gluteusëve gjatë ushtrimit</p></li><li><p>I disponueshëm në 3 madhësi të ndryshme, sipas zgjedhjes së ushtrimeve dhe intensitetit të dëshiruar</p></li><li><p>I qëndrueshëm dhe i rehatshëm, nuk mblidhet dhe nuk rrëshqet</p></li><li><p>Përdorim shumëqëllimësh</p></li></ul><p>Proteini.si booty hip band është shirit elastik stërvitjeje prej pëlhure, mjet i pazëvendësueshëm për ushtrime në shtëpi dhe në palestër.</p><p><strong>KARAKTERISTIKAT:</strong></p><ul><li><p>3 madhësi të ndryshme, sipas zgjedhjes së ushtrimeve dhe intensitetit:</p><ul><li><p><strong>S (rozë)</strong> – 33 × 7,6 cm – rezistencë e lartë: squat i ngushtë</p></li><li><p><strong>M (bruz)</strong> – 38 × 7,6 cm – rezistencë mesatare: ngritje anësore e këmbës, ushtrimi “guaskë” (clamshell), ecje anësore me shirit</p></li><li><p><strong>L (gri)</strong> – 43 × 7,6 cm – rezistencë e ulët: hap përpara (lunge), squat i gjerë</p></li></ul></li><li><p><strong>Materiali:</strong> poliestër dhe lateks</p></li></ul><p><strong>PËRPARËSITË:</strong></p><ul><li><p><strong>QËNDRUESHMËRIA:</strong> Pëlhura e fortë është e ndërthurur me fibra të veçanta elastike që mundësojnë një gamë të gjerë lëvizjesh. Shiritat janë projektuar të mos grisen gjatë përdorimit.</p></li><li><p><strong>REHATIA:</strong> Pëlhura është e fortë, por e butë dhe e këndshme për lëkurën. Nuk shtrëngon, nuk griset, nuk mblidhet dhe nuk rrëshqet, kështu që mund të përqendroheni te stërvitja në vend që ta rregulloni vazhdimisht pajisjen.</p></li><li><p><strong>NUK MBLIDHET:</strong> Gjerësia e madhe dhe shtresa e brendshme ngjitëse prej lateksi parandalojnë mbledhjen e shiritit gjatë ushtrimit.</p></li><li><p><strong>PËRDORIM SHUMËQËLLIMËSH:</strong> Mund të përdoret për Insanity, Pilates, CrossFit, Beachbody dhe stërvitje për gluteusët. Është ideal për fitnes, ushtrime për gluteusët dhe squat.</p></li></ul><p><strong>PËRFITIMET:</strong></p><ul><li><p><strong>AKTIVIZIM MË I MADH I GLUTEUSËVE</strong> – deri në 400%.</p></li><li><p><strong>FORCIM DHE TONIFIKIM:</strong> Shiritat ndihmojnë në tonifikimin dhe forcimin e këmbëve, gluteusëve, kofshëve, pulpave, kuadricepsit, muskujve të pasmë të kofshës, muskujve të trungut, muskujve rreth ijeve, abduktorëve, krahëve dhe shpatullave. Janë të lehtë për përdorim dhe të përshtatshëm për të gjithë, nga fillestarët deri te ushtruesit me përvojë.</p></li><li><p><strong>PËRMIRËSIM I LËVIZSHMËRISË, FLEKSIBILITETIT DHE FORCËS:</strong> Është i shkëlqyer për shtrirjen e ijeve dhe për ushtrime që përfshijnë gjunjët, muskujt dhe nyjet. Mund të ndihmojë në uljen e rrezikut nga lëndimet ose të përdoret pas një lëndimi sportiv ose tjetër. Para se të filloni një program ushtrimesh gjatë rikuperimit, është më mirë të konsultoheni me mjekun ose fizioterapeutin. Është ideal për terapi fizikale dhe rehabilitim në kushte shtëpiake.</p></li><li><p><strong>DJEGIE YNDYRASH:</strong> Duke stërvitur grupet më të mëdha muskulore, mund të nxitet në mënyrë indirekte procesi i djegies së yndyrave.</p></li></ul><p><strong>Sasia neto:</strong> 1 shirit për stërvitjen e ijeve dhe gluteusëve / paketim</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2285;

-- Product_Id: 2286 (PROTEINI.SI BOOTY HIP BAND, L, GRAY)
