-- Product_Id: 2294 (PROTEINI.SI SHAKER TRANSPARENT-BLACK, 700ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI SHAKER TRANSPARENT-BLACK, 700ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shejker me cilësi të lartë</p></li><li><p>I tejdukshëm me kapak të zi</p></li><li><p>I lehtë për përdorim, pa BPA</p></li><li><p><strong>Kapaciteti:</strong> 700 ml</p></li></ul><p>Kompania Proteini.si krijoi një shejker të ri për përgatitjen e shejkeve tuaja të preferuara.</p><ul><li><p><strong>Kapaciteti:</strong> 700 ml</p></li><li><p>Shkallë matëse në ml dhe oz</p></li><li><p>Mbyllje me kapak me vidë</p></li><li><p>Ngjyra moderne</p></li><li><p>I punuar nga polipropileni (PP) me cilësi të lartë</p></li><li><p>Në përputhje me rregulloret për materialet në kontakt me ushqimin</p></li><li><p>Rezistent ndaj thyerjes dhe i sigurt për larje në makinë enësh</p></li><li><p>Ideal për të gjitha llojet e pijeve të përziera</p></li><li><p>Pa BPA dhe nga plastikë jotoksike</p></li><li><p>Përshtatet në mbajtëset e gotave në makinë</p></li><li><p>Produkt plastik i prodhuar në Evropë</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2294;

-- Product_Id: 2295 (PROTEINI.SI SHAKER TRANSPARENT-PINK, 700ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI SHAKER TRANSPARENT-PINK, 700ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shejker me cilësi të lartë</p></li><li><p>I tejdukshëm me kapak rozë</p></li><li><p>I lehtë për përdorim, pa BPA</p></li><li><p><strong>Kapaciteti:</strong> 700 ml</p></li></ul><p><strong>Shejker me cilësi të lartë për përgatitjen e shejkeve proteinike, pijeve për hidratim dhe pijeve të tjera.</strong></p><p>Shejkeri më i popullarizuar evropian është përsosur më tej nga prodhuesi. Është i besueshëm dhe jashtëzakonisht praktik për përdorim të përditshëm.</p><ul><li><p>Një nga shejkerët me cilësinë më të lartë në treg</p></li><li><p>Dizajn tërheqës</p></li><li><p>I lehtë për përdorim</p></li><li><p><strong>Kapaciteti minimal:</strong> 700 ml</p></li><li><p>Ngjyra moderne</p></li><li><p>Mbyllje e shkëlqyer hermetike</p></li><li><p>Mbyllje me kapak me vidë (“TWIST LID”)</p></li><li><p>Përzierje e shkëlqyer</p></li><li><p>Nuk është i përshtatshëm për larje në makinë enësh</p></li><li><p>I punuar nga materiale me cilësi të lartë</p></li><li><p>Pa BPA</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2295;

-- Product_Id: 2296 (PROTEINI.SI BIDON "ACTIVE LIFESTYLE", 650ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI BIDON "ACTIVE LIFESTYLE", 650ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Shishe plastike 650 ml për ujë dhe pije të tjera</p></li><li><p>Me mbishkrimin “ACTIVE LIFESTYLE”</p></li><li><p>Me shkallë matëse</p></li><li><p>Pa BPA dhe DEHP</p></li></ul><p><strong>Shishe cilësore për përgatitjen e pijeve izotonike, energjetike, rigjeneruese dhe të tjera.</strong></p><ul><li><p>Me mbishkrimin “ACTIVE LIFESTYLE”</p></li><li><p>Dizajn ergonomik për mbajtje dhe pirje më të lehtë</p></li><li><p>Me shkallë matëse</p></li><li><p>Me grykë pirjeje prej gome</p></li><li><p>Nuk rrjedh</p></li><li><p>Pa BPA dhe DEHP</p></li><li><p>E prodhuar në Evropë</p></li><li><p>Përshtatet në shumicën e mbajtëseve të gotave në makinë dhe në biçikletë</p></li><li><p><strong>Kapaciteti:</strong> 650 ml</p></li><li><p><strong>Ngjyra:</strong> e tejdukshme</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2296;

-- Product_Id: 2299 (BATTERY SUPERCHARGED PUMP)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY SUPERCHARGED PUMP' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Pije freskuese me shije tropikale</p></li><li><p>Kombinim aminoacidesh, kreatine dhe kafeine – të gjitha në një pije</p></li><li><p>Përmban kreatinë për mbështetjen e performancës fizike gjatë ushtrimeve me intensitet të lartë</p></li><li><p>Përgatitje e shpejtë dhe e thjeshtë</p></li><li><p>I përshtatshëm për përdorim si pjesë e stilit aktiv të jetesës</p></li></ul><p><strong>Suplement ushqimor me ëmbëlsues.</strong></p><p>Përmban kafeinë (150 mg për porcion). Nuk rekomandohet për fëmijë dhe gra shtatzëna.</p><p>Ky suplement ushqimor në pluhur me shije freskuese tropikale është i destinuar për të gjithë ata që duan ta avancojnë rutinën e tyre sportive. Kombinimi i avancuar i aminoacideve, kreatinës dhe kafeinës mundëson një pije praktike dhe të shijshme para stërvitjes ose gjatë pjesës aktive të ditës.</p><p>Përmban kreatinë e cila, me marrje ditore prej 3 g, kontribuon në rritjen e performancës fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë. Kafeina e shtuar siguron ndjesinë karakteristike para stërvitjes, duke ju përgatitur për stërvitje.</p><p><strong>PËRPARËSITË KRYESORE:</strong></p><ul><li><p>Formulë e avancuar para stërvitjes me aminoacide, kreatinë dhe kafeinë</p></li><li><p>Shije freskuese tropikale: portokall, limon dhe ananas</p></li><li><p>Kreatina kontribuon në përmirësimin e performancës fizike gjatë ushtrimeve afatshkurtra me intensitet të lartë (me marrje ditore prej 3 g)</p></li><li><p>Zgjedhje ideale para stërvitjes ose si pjesë e stilit aktiv të jetesës</p></li><li><p>Përgatitje e shpejtë dhe e thjeshtë e një pijeje të shijshme</p></li></ul><p><strong>PËRBËRËSIT KRYESORË:</strong></p><ul><li><p>Kreatina kontribuon në përmirësimin e performancës fizike gjatë aktivitetit fizik intensiv (me marrje ditore prej 3 g)</p></li><li><p>Kafeina kontribuon në rritjen e vigjilencës dhe përmirësimin e përqendrimit gjatë stërvitjes</p></li><li><p>Aminoacidet L-citrulinë, beta-alaninë, L-tirozinë dhe L-argininë janë shpesh pjesë e formulave para stërvitjes të destinuara për persona aktivë</p></li><li><p>Sinefrinë – komponim natyral i përftuar nga portokalli i hidhur (<em>Citrus aurantium</em>)</p></li></ul><p><em>Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</em></p><p><strong>Sasia neto:</strong> 300 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 2 lugë matëse (10 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 1 porcion 30 minuta para stërvitjes. Mos e konsumoni me stomak bosh. Sasia maksimale ditore është 1 porcion (10 g). PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve të vegjël. Nuk rekomandohet për gra shtatzëna, gra që ushqejnë me gji, persona nën 18 vjeç dhe persona me sëmundje kardiovaskulare. Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 500 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2299;

-- Product_Id: 2300 (BATTERY STIM-FREE PUMP)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY STIM-FREE PUMP' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement “i pastër” para stërvitjes për stërvitje serioze</p></li><li><p>100% pa stimulues – pa kafeinë dhe pa rënie energjie</p></li><li><p>Formulë me aminoacide dhe kreatinë</p></li><li><p>Shije freskuese agrumesh (portokall dhe limon)</p></li><li><p>Përgatitje e lehtë dhe gatishmëri maksimale për stërvitje</p></li></ul><p><strong>Suplement ushqimor me ëmbëlsues.</strong></p><p>Stim-Free Pump është zgjedhja e duhur kur doni stërvitje maksimale pa kompromis dhe pa stimulues. Pa kafeinë, pa rënie të papritur të energjisë – vetëm fokus te stërvitja dhe ndjesia se mund të jepni edhe më shumë nga vetja, në çdo kohë të ditës, madje edhe në mbrëmje.</p><p>Kombinimi i avancuar i citrulinës, beta-alaninës, argininës, tirozinës dhe kreatinës është projektuar për të gjithë ata që i qasen seriozisht stërvitjes. Ky është suplement para stërvitjes me formulë “të pastër” – pa shtesa të panevojshme, vetëm me përbërës të provuar si ata që përdoren në formulat më të mira.</p><p>Kur nuk doni stimulim, por megjithatë doni një përvojë të vërtetë para stërvitjes, Stim-Free Pump është zgjedhja e duhur.</p><p>Përmban kreatinë e cila, me marrje ditore prej 3 g, kontribuon në rritjen e performancës fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë.</p><p><strong>PËRPARËSITË:</strong></p><ul><li><p>Pa kafeinë – formulë pa stimulues</p></li><li><p>Alternativë e suplementeve klasike para stërvitjes, e përshtatshme për përdorim në çdo kohë të ditës</p></li><li><p>Shije freskuese agrumesh (portokall dhe limon)</p></li><li><p>Përmban kreatinë monohidrat</p></li><li><p>Përgatitje e shpejtë dhe e thjeshtë e pijes</p></li></ul><p><strong>PËRBËRËSIT KYÇ:</strong></p><ul><li><p>L-citrulinë DL-malat – përbërës bazë në formulat e avancuara para stërvitjes</p></li><li><p>Beta-alaninë – zgjedhje e popullarizuar për stërvitje intensive</p></li><li><p>Kreatinë monohidrat – për mbështetjen e performancës fizike gjatë ushtrimeve me intensitet të lartë (me marrje ditore prej 3 g)</p></li><li><p>L-argininë – aminoacid që shpesh përfshihet në suplementet sportive</p></li><li><p>L-tirozinë – aminoacid i lidhur me stilin aktiv të jetesës</p></li></ul><p>Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</p><p><strong>Sasia neto:</strong> 300 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 2 lugë matëse (10 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumoni 1 porcion 30 minuta para stërvitjes. Sasia maksimale ditore është 1 porcion (10 g).

PARALAJMËRIM: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme. Mbajeni larg fëmijëve të vegjël. Nuk rekomandohet për gra shtatzëna, gra që ushqejnë me gji dhe fëmijë nën 18 vjeç.

RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 500 ml ujë.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2300;

-- Product_Id: 2301 (T-SHIRT LELY,)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'T-SHIRT LELY,' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Bluzë për meshkuj LELY</p></li><li><p>E disponueshme në 9 ngjyra të ndryshme</p></li><li><p>100% pambuk</p></li></ul><p>Bluza për meshkuj LELY është e punuar nga pambuku dhe ka stampë me logon e Proteini.si. Është shumë e butë dhe e rehatshme për t’u veshur, prandaj është e përshtatshme si për aktivitete sportive ashtu edhe për kohën e lirë.</p><p>E disponueshme në 9 ngjyra të ndryshme.</p><p><strong>PËRBËRJA:</strong> 100% pambuk</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2301;

-- Product_Id: 2302 (USN QHUSH PRE-WORKOUT, 220g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN QHUSH PRE-WORKOUT, 220g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement para dhe gjatë stërvitjes me përmbajtje të lartë kafeine</p></li><li><p><strong>250 mg kafeinë për porcion</strong></p></li><li><p>Me vitamina, beta-alaninë, L-argininë dhe L-citrulinë</p></li><li><p>Për fokus dhe performancë fizike më të mirë</p></li><li><p>20 porcione</p></li></ul><p><strong>Suplement ushqimor me aminoacide, ekstrakte bimore, kafeinë dhe vitamina, me ëmbëlsues.</strong></p><p>Përmban kafeinë (250 mg/11 g). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</p><p>Përmirësoni performancën tuaj në stërvitje me një pije të shkëlqyer para stërvitjes, të projektuar për ta ngritur energjinë dhe përqendrimin tuaj në një nivel më të lartë.</p><p>USN QHUSH Black është pluhur para stërvitjes që siguron mbështetje të shkëlqyer për stërvitje intensive në palestër, në shtëpi ose para vrapimit.</p><p><strong>NIVEL I LARTË STIMULIMI</strong></p><p>QHUSH Black përmban 250 mg kafeinë në çdo porcion, duke siguruar një nxitje të fortë energjie para stërvitjes së radhës.</p><p><strong>FOKUS KUR JU NEVOJITET MË SHUMË</strong></p><p>QHUSH jo vetëm që siguron nxitje të fortë energjie, por përmban edhe L-teaninë (nga ekstrakti i çajit jeshil), e cila ndihmon në ruajtjen e nivelit të lartë të përqendrimit ndërsa punoni për arritjen e qëllimeve tuaja.</p><p><strong>FORMULË E AVANCUAR</strong></p><p>Kjo nuk është pije e zakonshme energjetike me përmbajtje të lartë kafeine, por një formulë e avancuar para stërvitjes. Shijoni një kombinim përbërësish që mbështesin stërvitjen, përfshirë beta-alaninë, L-argininë dhe L-citrulinë, si dhe vitaminat B6 dhe B12, të cilat kontribuojnë në uljen e lodhjes dhe rraskapitjes.</p><p>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</p><p><strong>Sasia neto:</strong> 220 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 lugë matëse (11 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Për rezultate më të mira, konsumojeni 30 minuta para stërvitjes. Pas hapjes, përdoreni produktin brenda 1 muaji.

PARALAJMËRIME: Përmban kafeinë (250 mg/11 g). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji. Vetëm për të rritur. Mos tejkaloni 400 mg kafeinë në ditë nga të gjitha burimet (200 mg në ditë për gra shtatzëna dhe gra që ushqejnë me gji). Si me të gjitha suplementet ushqimore, konsultohuni me mjekun para përdorimit, veçanërisht nëse keni probleme shëndetësore dhe/ose përdorni barna. Mos tejkaloni 1 porcion (11 g) në ditë. Ruani hidratimin e duhur. I përshtatshëm për vegjetarianë dhe veganë. Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Përzieni 1 lugë matëse (11 g) me 250 ml ujë. Tundeni mirë për 30 sekonda.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2302;

-- Product_Id: 2303 (USN QHUSH ENERGY)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'USN QHUSH ENERGY' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Pije energjetike me PËRMBAJTJE TË LARTË KAFEINE (150 mg për kanaçe)</p></li><li><p>Me vitamina, aminoacide dhe ekstrakte bimore</p></li><li><p>Për më shumë energji, fokus dhe motivim</p></li><li><p>Për përballim më të lehtë të lodhjes psikofizike</p></li></ul><p>Pije e gazuar joalkoolike me vitamina, aminoacide, ekstrakte bimore dhe kafeinë, me ëmbëlsues. Përmbajtje e lartë kafeine (30 mg/100 ml). Nuk rekomandohet për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji.</p><p>QHUSH Energy, me 150 mg kafeinë për kanaçe, siguron një nxitje të jashtëzakonshme energjie në formën e një pijeje të shijshme të gazuar pa sheqer, karbohidrate dhe kalori. Shijojeni sa herë që ju nevojiten energji, fokus dhe motivim, pavarësisht nëse stërviteni, punoni në zyrë, mësoni ose luani lojëra video. Pija është e përshtatshme për persona me stil jetese aktiv.</p><p>Përveç kafeinës, pija përmban:</p><ul><li><p>Vitamina të grupit B (niacinë, B6, B12 dhe acid pantotenik), që kontribuojnë në funksionimin normal të sistemit nervor dhe funksionin normal psikologjik, në uljen e lodhjes dhe rraskapitjes, si dhe në performancën normale mendore.</p></li><li><p>Taurinë</p></li><li><p>Karnitinë</p></li><li><p>Teaninë</p></li><li><p>Xhensen</p></li></ul><p>Në disa shije të pijes janë shtuar edhe:</p><ul><li><p>Vitamina C (shija Electric Blue Gaming) – kontribuon në funksionin normal psikologjik, në uljen e lodhjes dhe rraskapitjes, si dhe në funksionimin normal të sistemit imunitar gjatë dhe pas aktivitetit fizik intensiv. Efekti i dobishëm arrihet me marrje ditore prej 200 mg, përveç marrjes së rekomanduar ditore të vitaminës C.</p></li><li><p>Tirozinë dhe fosfatidilserinë (shija Glacier)</p></li></ul><p>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</p><p>Përbërja varet nga shija.</p><p>Sasia neto: 500 ml / 24 × 500 ml</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 kanaçe (500 ml).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni kur ju nevojiten energji dhe përqendrim. Konsumojeni me masë. Mos e tejkaloni dozën maksimale të rekomanduar ditore (1 kanaçe). Shërbejeni të ftohtë. Pas hapjes, ruajeni në frigorifer dhe konsumojeni brenda 48 orëve. PARALAJMËRIM: Nuk rekomandohet për persona të ndjeshëm ndaj kafeinës. Mos tejkaloni 400 mg kafeinë në ditë nga të gjitha burimet (200 mg në ditë për gra shtatzëna dhe gra që ushqejnë me gji). Konsumojeni si pjesë e një stili jetese të ekuilibruar dhe të shëndetshëm. Ruajeni në vend të freskët.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2303;

-- Product_Id: 2304 (SPORTNAHRUNG MAGNESIUM BISGLYCINATE (NEW))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'SPORTNAHRUNG MAGNESIUM BISGLYCINATE (I RI)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement ushqimor me magnez</p></li><li><p>Për shëndetin e kockave, rikuperimin e muskujve, prodhimin e energjisë dhe funksionimin normal të sistemit nervor</p></li><li><p>Furnizim për 30 ditë</p></li></ul><p><strong>Suplement ushqimor.</strong></p><p>Magnezi siguron mbështetje gjithëpërfshirëse për shëndetin e kockave, rikuperimin e muskujve, prodhimin e energjisë dhe ekuilibrin e sistemit nervor.</p><p><strong>PËRFITIMET E MAGNEZIT:</strong></p><ul><li><p>Ndihmon në ruajtjen e kockave të shëndetshme dhe funksionimin normal të sistemit imunitar.</p></li><li><p>Ndihmon në relaksimin e muskujve, uljen e ngërçeve dhe lehtësimin e tensionit.</p></li><li><p>Mbështet hidratimin e duhur dhe ndihmon në ruajtjen e presionit normal të gjakut.</p></li><li><p>Kontribuon në shëndetin e sistemit kardiovaskular, ndihmon në stabilizimin e nivelit të energjisë, uljen e lodhjes dhe përmirësimin e funksionit të sistemit nervor.</p></li></ul><p>Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</p><p><strong>Sasia neto:</strong> 120 kapsula</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 4 kapsula.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 4 kapsula me një gotë ujë pas stërvitjes ose para gjumit.

PARALAJMËRIME: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe stil jetese të shëndetshëm. Mbajeni larg fëmijëve të vegjël.

RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2304;

-- Product_Id: 2305 (BATTERY MAGNESIUM BISGLYCINATE)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY MAGNESIUM BISGLYCINATE' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Bisglicinat magnezi – formë organike e magnezit me cilësi të lartë</p></li><li><p>Thithje e mirë dhe efekt i butë në stomak</p></li><li><p>Mbështet muskujt pas ushtrimeve dhe lodhjes fizike</p></li><li><p>Ndihmon në uljen e lodhjes dhe rraskapitjes</p></li><li><p>Për persona aktivë, sportistë dhe mirëqenie të përditshme</p></li><li><p>Furnizim për 1 muaj</p></li></ul><p><strong>Suplement ushqimor.</strong></p><p>Magnezi është mineral esencial për personat aktivë, sepse kontribuon në funksionimin normal të muskujve, ndihmon në uljen e lodhjes dhe rraskapitjes dhe mbështet rikuperimin pas lodhjes fizike. Është i përshtatshëm për të gjithë ata që duan ta mbështesin organizmin e tyre në aktivitetet e përditshme, sport dhe relaksim.</p><p>Produkti përmban magnez në formën e bisglicinatit të magnezit, në të cilën magnezi është i lidhur me aminoacidin glicinë. Kjo formë organike e magnezit vlerësohet për thithjen e mirë dhe veprimin e butë në sistemin tretës. Nuk shkakton efekt laksativ dhe nuk e irriton traktin tretës, prandaj është zgjedhje e shkëlqyer për persona me stomak të ndjeshëm dhe për të gjithë ata që duan të shmangin problemet e zakonshme tretëse të lidhura me format e tjera të magnezit.</p><p><strong>PSE TË ZGJIDHNI BISGLICINAT MAGNEZI?</strong></p><ul><li><p>Formë organike e magnezit me biodisponueshmëri të mirë</p></li><li><p>I përshtatshëm për plotësimin e përditshëm të marrjes së magnezit</p></li><li><p>Kontribuon në funksionimin normal të muskujve dhe sistemit nervor</p></li><li><p>Ndihmon në uljen e lodhjes dhe rraskapitjes</p></li><li><p>Merr pjesë në metabolizmin energjetik</p></li><li><p>Kontribuon në ruajtjen e kockave të shëndetshme dhe ekuilibrit të elektroliteve</p></li></ul><p>Rekomandohen ushqyerje e larmishme dhe e ekuilibruar dhe stil jetese i shëndetshëm.</p><p><strong>Sasia neto:</strong> 120 kapsula</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 4 kapsula.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Merrni 4 kapsula me një gotë ujë pas stërvitjes ose para gjumit.

PARALAJMËRIME: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe stil jetese të shëndetshëm. Mbajeni larg fëmijëve të vegjël.

RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2305;

-- Product_Id: 2306 (T-SHIRT NOEL)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'T-SHIRT NOEL' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Bluzë e zezë për meshkuj</p></li><li><p>Me motivin e evolucionit dhe mbishkrimin “EVOLUTION GYM”</p></li><li><p>100% pambuk</p></li></ul><p>Bluzë e zezë pambuku për meshkuj me logo të vogël të Proteini.si në pjesën e përparme dhe motivin e evolucionit me mbishkrimin “EVOLUTION GYM” në pjesën e pasme. Bluza është e lehtë dhe e rehatshme për t’u veshur, e përshtatshme për aktivitete sportive dhe kohën e lirë.</p><p>Përbërja: 100% pambuk</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2306;

-- Product_Id: 2307 (LONG LEGGINGS, TAJA)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'LONG LEGGINGS, TAJA' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Tajca për femra TAJA nga pëlhurë moderne me brinjë</p></li><li><p>Për rehati të plotë dhe pamje tërheqëse</p></li><li><p>Të punuara nga pëlhurë pak më e trashë</p></li><li><p>Të padukshme gjatë squat (squat-proof)</p></li><li><p>Të disponueshme në 2 ngjyra të ndryshme</p></li><li><p>Të disponueshme janë edhe topi sportiv, topi me mëngë të shkurtra dhe të gjata, si dhe tajcat e shkurtra Taja</p></li></ul><p>Tajcat për femra TAJA janë të përshtatshme për t’u veshur gjatë stërvitjes ose në kohën e lirë. Janë të punuara nga pëlhurë moderne me brinjë, e cila është pak më e trashë dhe siguron rehati të plotë gjatë veshjes, e njëkohësisht edhe pamje tërheqëse. Beli i lartë dhe buza elastike në pjesën e poshtme të këmbëve sigurojnë rehati gjatë ushtrimit dhe parandalojnë rrëshqitjen e tajcave poshtë, duke u mundësuar të qëndrojnë në vend. Pëlhura nuk është e tejdukshme (squat-proof), gjë që mundëson kryerjen e squat pa shqetësim. Pamja e tajcave theksohet edhe më shumë me një kordon lidhës në pjesën e belit.</p><p>Modelja në fotografi është 173 cm e gjatë dhe vesh madhësinë M.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li><p>Të punuara nga pëlhurë moderne me brinjë për pamje tërheqëse</p></li><li><p>Të buta dhe të rehatshme</p></li><li><p>Jashtëzakonisht elastike</p></li><li><p>Të punuara nga pëlhurë pak më e trashë</p></li><li><p>Të padukshme gjatë squat (squat-proof)</p></li><li><p>Bel mesatarisht i lartë</p></li><li><p>Me kordon lidhës në pjesën e belit</p></li><li><p><strong>Përbërja:</strong> 90% najlon, 10% spandeks</p></li><li><p><strong>Ngjyrat e disponueshme:</strong> e zezë, blu</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2307;

-- Product_Id: 2308 (SPORTS TOP WITH ZIPPER (LONG SLEEVES) TYRA)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'SPORTS TOP WITH ZIPPER (LONG SLEEVES) TYRA' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Top sportiv me mëngë të gjata dhe zinxhir TYRA</p></li><li><p>Prerje e rehatshme dhe e ngushtë</p></li><li><p>Me vrima për gishtat e mëdhenj në mëngë dhe dy xhepa anësorë me zinxhir</p></li><li><p>Mund të vishet si shtresë bazë ose e mesme</p></li><li><p>I disponueshëm në 2 ngjyra</p></li><li><p>Të disponueshme janë edhe tajcat e gjata dhe gjoksorja sportive TYRA</p></li></ul><p>Topi i shkurtër sportiv TYRA me mëngë të gjata, zinxhir dhe xhepa është i përshtatshëm për stërvitje dhe për kohën e lirë. Mëngët kanë vrima për gishtat e mëdhenj, ndërsa xhepat anësorë mbyllen me zinxhir.</p><p>Modelja në fotografi është 168 cm e gjatë dhe vesh madhësinë S.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li><p>Top sportiv praktik dhe i rehatshëm me zinxhir</p></li><li><p>Mund të vishet si shtresë bazë ose e mesme</p></li><li><p>Material i lehtë dhe prerje e ngushtë</p></li><li><p>Me vrima për gishtat e mëdhenj</p></li><li><p>Me dy xhepa anësorë me zinxhir</p></li><li><p><strong>Përbërja:</strong> 78% najlon, 22% spandeks</p></li><li><p><strong>Ngjyrat:</strong> e zezë, vjollcë</p></li><li><p>Të disponueshme janë edhe tajcat e gjata dhe gjoksorja sportive TYRA</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2308;

