-- Product_Id: 2311 (WOMEN T-SHIRT OUTSIDE THE BOX)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'WOMEN T-SHIRT OUTSIDE THE BOX' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Bluzë për femra OUTSIDE THE BOX</p></li><li><p>E disponueshme në 1 ngjyrë</p></li><li><p>100% pambuk</p></li></ul><p>Bluza për femra OUTSIDE THE BOX është e punuar nga 100% pambuk dhe ka stampë me logon e Proteini.si si dhe mbishkrimin THINK OUTSIDE THE BOX. Ka prerje që i përshtatet trupit, ndërsa materiali është shumë i butë dhe i rehatshëm për t’u veshur, prandaj është e përshtatshme si për aktivitete sportive ashtu edhe për kohën e lirë.</p><p>Përbërja: 100% pambuk</p>"]' ELSE DescriptionAl END
