-- Product_Id: 2312 (LONG LEGGINGS TYRA)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'LONG LEGGINGS TYRA' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Tajca të gjata për femra TYRA</p></li><li><p>Me efekt scrunch për theksimin e gluteusëve</p></li><li><p>Të lehta dhe që marrin frymë</p></li><li><p>Të disponueshme në 2 ngjyra</p></li><li><p>Të disponueshme janë edhe gjoksorja sportive dhe topi sportiv me mëngë të gjata TYRA</p></li></ul><p>Tajcat e gjata për femra TYRA janë të punuara nga pëlhurë e lëmuar dhe elastike që siguron rehati të plotë dhe lehtësi gjatë veshjes. Beli i lartë parandalon rrëshqitjen e tajcave poshtë gjatë ushtrimit dhe ndihmon që të qëndrojnë në vend. Pëlhura prej najloni dhe elastani largon në mënyrë efikase djersën gjatë aktiviteteve sportive, duke mundësuar liri lëvizjeje, rehati dhe freski gjatë gjithë ditës. Nuk janë të tejdukshme gjatë squat (squat-proof), për ushtrime pa shqetësim.</p><p>Modelja në fotografi është 168 cm e gjatë dhe vesh madhësinë S.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li><p>Efekt scrunch për theksimin e gluteusëve</p></li><li><p>Bel i lartë</p></li><li><p>Të padukshme gjatë squat (squat-proof)</p></li><li><p>Për rehati të plotë dhe pamje tërheqëse</p></li><li><p><strong>Përbërja:</strong> 78% najlon, 22% spandeks</p></li><li><p><strong>Ngjyrat:</strong> e zezë, vjollcë</p></li><li><p>Të disponueshme janë edhe gjoksorja sportive dhe topi sportiv me mëngë të gjata TYRA</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2312;

