-- Product_Id: 2317 (SPORTS BRA NELLY)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'SPORTS BRA NELLY' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Gjoksore sportive për femra NELLY</p></li><li><p>Përshtatje e përsosur dhe mbështetje për gjoksin</p></li><li><p>Me rripa të hollë</p></li><li><p>Përdorim shumëqëllimësh</p></li><li><p>E disponueshme në 3 ngjyra</p></li><li><p>Të disponueshme janë edhe tajcat e shkurtra dhe të gjata NELLY</p></li></ul><p>Gjoksorja sportive për femra NELLY është e punuar nga pëlhurë e butë dhe elastike që mundëson liri të jashtëzakonshme lëvizjeje, edhe gjatë aktiviteteve sportive më intensive. Është e përshtatshme për t’u veshur si të brendshme ose si top më vete. Ka mbushje të buta dhe të holla që e formësojnë bukur gjoksin dhe mund të hiqen për ndjesi edhe më të madhe lehtësie. Ndryshe nga topat e tjerë sportivë, rripat janë më të hollë dhe të bashkuar në pjesën e pasme.</p><p>Modelja në fotografi është 168 cm e gjatë dhe vesh madhësinë S.</p><p><strong>KARAKTERISTIKAT KRYESORE:</strong></p><ul><li><p>E përshtatshme për aktivitete sportive dhe kohën e lirë</p></li><li><p>Pëlhura me dy shtresa dhe shiriti më i gjerë elastik nën gjoks sigurojnë mbështetje shtesë</p></li><li><p>Pëlhura pa qepje mundëson rehati të plotë</p></li><li><p>Largon në mënyrë efikase djersën dhe mundëson ndjesinë e lëkurës së thatë</p></li><li><p>E punuar nga material që mundëson liri maksimale lëvizjeje</p></li><li><p>Me rripa të hollë, gjatësia e të cilëve mund të rregullohet</p></li><li><p><strong>Përbërja:</strong> 90% najlon, 10% spandeks</p></li><li><p><strong>Ngjyrat e disponueshme:</strong> bruz, portokalli</p></li><li><p>Të disponueshme janë edhe tajcat e shkurtra dhe të gjata NELLY</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2317;

-- Product_Id: 2318 (BATTERY CREATINE, 250g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BATTERY CREATINE, 250g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>100% kreatinë e pastër</li><li>Pa shije</li><li>Rrit performancën fizike</li><li>Një nga suplementet ushqimore më të popullarizuara ndër sportistët</li><li>E prodhuar në kapacitetet tona prodhuese në BE</li></ul><p><strong>Kreatinë në pluhur. Suplement ushqimor. Pa shije.</strong></p><p>Battery Creatine përbëhet nga 100% kreatinë e pastër, e cila është një nga suplementet ushqimore më të popullarizuara ndër sportistët. Një nga sfidat më të mëdha me të cilat përballemi gjatë stërvitjes është ulja e rezervave tona energjetike, gjë që mund të kufizojë performancën tonë. Kreatina rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë (efekti i dobishëm arrihet me marrje ditore prej 3 g kreatinë).</p><p><strong>E sigurt dhe me cilësi të lartë – e prodhuar në kapacitetet tona prodhuese në BE</strong></p><ul><li>Përbërës të verifikuar, pa aditivë të panevojshëm.</li><li>E prodhuar në BE sipas standardeve të larta të cilësisë dhe sigurisë.</li></ul><p><em>Ushqyerja e ekuilibruar dhe e larmishme, si dhe stili i shëndetshëm i jetesës, janë të rëndësishme.</em></p><p><strong>Sasia neto:</strong> 500 g</p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 lugë matëse e plotë (3,4 g). Përdorni peshore për matje të saktë.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni 20 minuta para stërvitjes. Në ditët kur nuk stërviteni, konsumojeni në mëngjes me stomak bosh. Sasia maksimale ditore është 1 porcion. Produkti është i destinuar për të rriturit që praktikojnë aktivitet fizik me intensitet të lartë.

PARALAJMËRIME: Doza e rekomanduar ditore nuk duhet të tejkalohet. Produkti nuk duhet të përdoret si zëvendësim për një ushqyerje të ekuilibruar. Mbajeni larg fëmijëve!

RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 250 ml ujë të vakët.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2318;

-- Product_Id: 2319 (PROTEINI.SI 100% PURE CREATINE (FLAVOURED))
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI 100% PURE CREATINE (ME SHIJE)' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Suplement ushqimor me kreatinë i thjeshtë, efikas dhe i sigurt</p></li><li><p>3000 mg kreatinë e pastër për porcion</p></li><li><p>Për të gjithë ata që duan më shumë forcë dhe përparim të dukshëm</p></li><li><p>I zhvilluar dhe i prodhuar në kapacitetet tona prodhuese në BE</p></li><li><p>58 porcione për mbështetje afatgjatë të stërvitjes dhe përparim të vazhdueshëm</p></li></ul><p><strong>Përmirësoni performancën tuaj me pastërti pa kompromis tek e cila mund të besoni.</strong></p><p><strong>Gati ta ngrini stërvitjen në nivelin tjetër?</strong></p><p>Proteini.si 100% Pure Creatine me shije freskuese limoni është i destinuar për të gjithë ata që presin më shumë nga trupi i tyre. Çdo porcion siguron 3000 mg kreatinë të pastër, e cila rrit performancën fizike gjatë përpjekjeve fizike të njëpasnjëshme, afatshkurtra dhe me intensitet të lartë – pikërisht në momentet që çojnë drejt përparimit të vërtetë.</p><p>Falë përgatitjes së shpejtë dhe të thjeshtë, është ideal për t’u konsumuar para stërvitjes, por edhe në ditët kur nuk stërviteni, kur ende ju nevojiten energji dhe fokus.</p><p>Pastërtia e plotë e përbërësve dhe prodhimi i verifikuar në BE sigurojnë cilësi të lartë që mund ta ndjeni në çdo përsëritje.</p><p><strong>PSE TË ZGJIDHNI PROTEINI.SI 100% PURE CREATINE?</strong></p><ul><li><p>3000 mg kreatinë e pastër për porcion – sasia optimale për mbështetjen e performancës fizike gjatë përpjekjeve intensive</p></li><li><p>Shije freskuese limoni dhe përgatitje për vetëm pak sekonda</p></li><li><p>I zhvilluar dhe i prodhuar në kapacitetet tona prodhuese në BE – për cilësi të sigurt dhe pastërti të përbërësve</p></li></ul><p>Nëse stërviteni fort, zgjidhni një suplement që mbështet performancën tuaj.</p><p><strong>Proteini.si 100% Pure Creatine – mbështetja juaj për forcë, shpërthim dhe përparim.</strong></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 4,2 g (1 lugë matëse e plotë – përdorni peshore për matje të saktë).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Konsumojeni 20 minuta para stërvitjes. Në ditët kur nuk stërviteni, konsumojeni në mëngjes me stomak bosh. Sasia maksimale ditore është 1 porcion (4,2 g). Produkti është i destinuar për të rriturit që praktikojnë aktivitet fizik me intensitet të lartë.

PARALAJMËRIME: Mos e tejkaloni dozën e rekomanduar ditore. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të ekuilibruar dhe të larmishme dhe stil jetese të shëndetshëm. Mbajeni larg fëmijëve të vegjël!

RUAJTJA: Ruajeni në vend të errët dhe të thatë, në temperaturë nën 25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 4,2 g pluhur në 250 ml ujë të vakët.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2319;

-- Product_Id: 2320 (LONG LEGGINS NELLY)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'LONG LEGGINS NELLY' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Tajca të gjata për femra NELLY</p></li><li><p>Me efekt scrunch për theksimin e gluteusëve</p></li><li><p>Të punuara nga pëlhurë pak më e trashë</p></li><li><p>Të padukshme gjatë squat (squat-proof)</p></li><li><p>Të disponueshme në 3 ngjyra</p></li><li><p>Të disponueshme janë edhe tajcat e shkurtra dhe topi sportiv NELLY</p></li></ul><p>Tajcat e gjata për femra NELLY janë të përshtatshme për aktivitete sportive dhe për kohën e lirë, duke siguruar rehati të plotë dhe lehtësi gjatë veshjes. Beli i lartë parandalon rrëshqitjen e tajcave poshtë gjatë ushtrimit dhe ndihmon që të qëndrojnë në vend. Pëlhura prej najloni dhe spandeksi largon në mënyrë efikase djersën gjatë aktiviteteve sportive, duke mundësuar liri të pakufizuar lëvizjeje, rehati dhe freski gjatë gjithë ditës. Tajcat nuk janë të tejdukshme gjatë squat (squat-proof), për ushtrime pa shqetësim.</p><p>Modelja në fotografi është 168 cm e gjatë dhe vesh madhësinë S.</p><p>KARAKTERISTIKAT KRYESORE:</p><ul><li><p>Efekt scrunch për theksimin e gluteusëve</p></li><li><p>Të punuara nga pëlhurë pak më e trashë</p></li><li><p>Të padukshme gjatë squat (squat-proof)</p></li><li><p>Elastike dhe të rehatshme</p></li><li><p>Për rehati të plotë dhe pamje tërheqëse</p></li><li><p>Përbërja: 90% najlon, 10% spandeks</p></li><li><p>Ngjyrat: gri e hapur, vjollcë, e zezë</p></li><li><p>Të disponueshme janë edhe tajcat e shkurtra dhe topi sportiv NELLY</p></li></ul>"]' ELSE DescriptionAl END
WHERE Product_Id = 2320;

-- Product_Id: 2322 (NUTREND CARNITINE DRINK, 750ml, LEMON)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'NUTREND CARNITINE DRINK, 750ml, LIMON' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li>Pije freskuese e gatshme për konsum të drejtpërdrejtë</li><li>Pa sheqer</li><li>1000 mg L-karnitinë për porcion</li><li>Me kafeinë dhe taurinë</li></ul><p><strong>Pije joalkoolike e aromatizuar me ëmbëlsues, me L-karnitinë, taurinë dhe kafeinë të shtuar.</strong></p><p><strong>Pije joalkoolike e gazuar dhe e aromatizuar me ëmbëlsues, me L-karnitinë, taurinë dhe kafeinë të shtuar.</strong><br>(shijet: Mjedër, Kola, Mojito, Mango &amp; Kokos, Livando, Luleshtrydhe &amp; Mente)</p><p>Pije freskuese e gatshme pa sheqer që përmban 1000 mg L-karnitinë, me përbërës stimulues të shtuar si kafeina dhe taurina. Pija është zgjedhje e shkëlqyer për mbështetjen e performancës fizike dhe ndihmon në ruajtjen e hidratimit të duhur gjatë stërvitjes. Falë shijes së lehtë dhe freskuese, përshtatet lehtë në rutinën e stërvitjes dhe ju ndihmon të merrni rregullisht lëngje.</p><ul><li>1000 mg L-karnitinë</li><li>1000 mg taurinë</li><li>40 mg kafeinë</li><li>Pa sheqer</li></ul><p><strong>PËRDORIMI I REKOMANDUAR:</strong> 1 shishe në ditë. Konsumoni 20–30 minuta para aktivitetit fizik. Mund të përdoret edhe gjatë stërvitjes.</p><p><strong>PËRDORIMI:</strong> Pas hapjes, produkti duhet të konsumohet brenda 24 orëve.</p><p><strong>I përshtatshëm për sportistë, me ëmbëlsues.</strong> I destinuar për nevoja të veçanta ushqyese. Nuk është i destinuar për fëmijë, gra shtatzëna dhe gra që ushqejnë me gji. Mbajeni larg fëmijëve! Ruajeni në vend të thatë, në temperaturë deri në 25°C dhe të mbrojtur nga drita e drejtpërdrejtë e diellit. Mos e ngrini. Përmban kafeinë. Nuk është i përshtatshëm për sportistë të regjistruar. Prodhuesi nuk mban përgjegjësi për dëmet e shkaktuara nga përdorimi ose ruajtja e gabuar.</p><p><strong>Sasia neto:</strong> 750 ml</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2322;

-- Product_Id: 2325 (DYMATIZE CREATINE MONOHYDRATE 300g)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'DYMATIZE CREATINE MONOHYDRATE 300g' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p>Tejkaloni kufijtë tuaj në stërvitje! Kërkoni një nxitje shtesë për performancë më të mirë gjatë stërvitjeve intensive? Kreatina rrit performancën fizike gjatë aktiviteteve fizike afatshkurtra me intensitet të lartë, si stërvitja e forcës.<br><br>Ashtu si ju, Dymatize nuk bën kompromis me cilësinë dhe përdor vetëm Creapure® – kreatinë monohidrat me cilësi të lartë.<br><br>Kreatina është substancë natyrale që gjendet në organizëm. Ajo ka rol kyç në transportin dhe ruajtjen e energjisë në të gjitha qelizat. Marrja ditore prej 3 g kreatinë për një periudhë prej të paktën 4 javësh tregon rritje të përmbajtjes së kreatinës në muskuj.<br><br>Pa shije dhe me pastërti të lartë, Dymatize® CREATINE MONOHYDRATE, i përzier me ujë ose pije tjetër pa kafeinë, është zgjedhja e përsosur për periudhat e stërvitjeve intensive.</p><p><br></p><p>Sasia neto: 300g</p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'2 lugë matëse në ditë. Të konsumohet si pjesë e një ushqyerjeje të larmishme dhe të ekuilibruar dhe stili të shëndetshëm jetese.' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'Kreatina nuk është e përshtatshme për fëmijë dhe adoleshentë. Është e destinuar vetëm për të rriturit që praktikojnë aktivitet fizik intensiv. Suplementet ushqimore nuk janë zëvendësim për një ushqyerje të larmishme dhe të ekuilibruar dhe stil jetese të shëndetshëm. Mos e tejkaloni dozën e rekomanduar ditore. Mbajeni larg fëmijëve.' ELSE InstructionsForUseDescriptionAl END
WHERE Product_Id = 2325;

-- Product_Id: 2326 (APPLIED NUTRITION CREATINE MONOHYDRATE, 250G)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'APPLIED NUTRITION CREATINE MONOHYDRATE, 250G' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p>Applied Nutrition Creatine Monohydrate është kreatinë e mikronizuar në pluhur. Varianti pa aromë përmban 100% kreatinë monohidrat, me 5 g kreatinë për porcion.</p><p><br>I disponueshëm në paketime prej:<br>- 250 g (50 porcione)<br>- 500 g (100 porcione)<br>- 1 kg (200 porcione)<br></p><p>&nbsp;Përdorni regjistrin e serive të testuara të Informed Sport për Applied Nutrition Creatine Monohydrate Professional për të kontrolluar numrin e serisë të shtypur në paketim: https://sport.wetestyoutrust.com/ja/node/1146294&nbsp;&nbsp;</p><p>PËRPARËSITË KYÇE:<br><br>- Forcë dhe fuqi e shtuar: Ndihmon në ngritjen e peshave më të rënda dhe kryerjen e më shumë përsëritjeve, duke kontribuar në rritje më të madhe muskulore me kalimin e kohës.<br>- Performancë sportive e përmirësuar: Ideal për sporte dhe aktivitete me intensitet të lartë, për përmirësimin e performancës së përgjithshme dhe qëndrueshmërisë.<br>- Rikuperim muskulor i përmirësuar: Ndihmon në uljen e dhimbjes muskulore dhe përshpejtimin e rikuperimit, duke mundësuar stërvitje më të shpeshta.<br>- Mbështetje për masë muskulore të pastër: Nxit rritjen e indit muskulor të pastër pa shtim të panevojshëm të yndyrës trupore.<br>- Përzihet lehtë me ujë.<br>- I testuar për sportistë nga Informed Sport.<br>- Produkt me certifikatë hallall.</p><p></p><p></p>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Shtoni 1 porcion (5 g) në ujë, tundeni dhe konsumojeni. Përdoreni 1–2 herë në ditë, mundësisht menjëherë para dhe pas aktivitetit fizik. Pas 8 javësh përdorimi të vazhdueshëm, bëni një pushim 1-javor, e më pas përsëriteni ciklin.' ELSE InstructionsForUseAl END
WHERE Product_Id = 2326;

