    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Shtoni 1 porcion (5 g) në ujë, tundeni dhe konsumojeni. Përdoreni 1–2 herë në ditë, mundësisht menjëherë para dhe pas aktivitetit fizik. Pas 8 javësh përdorimi të vazhdueshëm, bëni një pushim 1-javor, e më pas përsëriteni ciklin.' ELSE InstructionsForUseAl END
WHERE Product_Id = 2327;

-- Product_Id: 2330 (RABEKO SAUCE, 350ml)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'RABEKO SAUCE, 350ml' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<p><strong>Salcat Rabeko Zero – shije e shkëlqyer pa kompromise të panevojshme</strong></p><p>Doni t’i pasuroni vaktet tuaja të preferuara me salca të shijshme, pa marrje të panevojshme kalorish, sheqernash dhe yndyrash? Atëherë salcat Rabeko Zero janë zgjedhja e duhur! Me shije të ndryshme dhe përbërje të lehtë, ato janë një mënyrë e shkëlqyer për të shijuar vaktet e preferuara pa kompromis me mënyrën tuaj të ushqyerjes.</p><p><strong>ÇFARË I BËN ZGJEDHJE KAQ TË MIRË?</strong></p><ul><li><p>Vlerë e ulët kalorike</p></li><li><p>Përmbajtje e reduktuar sheqernash krahasuar me salcat klasike</p></li><li><p>Përbërje e lehtë, pa shtesa të panevojshme</p></li><li><p>Pa ngjyrues artificialë</p></li><li><p>Përshtaten në mënyrë të përsosur në një stil jetese të ekuilibruar dhe të vetëdijshëm</p></li></ul><p><strong>TË PËRSOSURA ME:</strong></p><ul><li><p>Patate të skuqura dhe rostiçeri të përgatitura në friteze me ajër të nxehtë</p></li><li><p>Burgera, tortilja, tost dhe omëleta</p></li><li><p>Zgarë dhe pjata të ndryshme kryesore</p></li><li><p>Si shtesë ose dip për rostiçeritë e preferuara</p></li></ul><p>Pavarësisht nëse stërviteni, kujdeseni për ushqyerjen ose thjesht doni të bëni zgjedhje më të vetëdijshme, salcat Rabeko Zero ju mundësojnë të shijoni shijet e preferuara pa kompromise. Të shijshme, të lehta dhe ideale për çdo ditë!</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2330;

-- Product_Id: 2331 (PROTEINI.SI ULTIMATE GRIPS)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'PROTEINI.SI ULTIMATE GRIPS' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>E lehtëson ngritjen e peshave</p></li><li><p>Siguron kapje më të sigurt</p></li><li><p>Ofron mbështetje për kyçet e duarve</p></li><li><p>Të lehta për përdorim</p></li></ul><p><strong>Proteini.si Ultimate Grips</strong> janë aksesor i avancuar stërvitjeje, i projektuar për të përmirësuar kapjen dhe për të maksimizuar performancën dhe rezultatet e stërvitjes.</p><p><strong>Proteini.si Ultimate Grips</strong> kanë sipërfaqe të qëndrueshme prej gome që siguron kapje të qëndrueshme dhe të sigurt. Sipërfaqja unike prej gome mbështillet rreth shufrës dhe i përshtatet formës së saj, duke mundësuar mbajtje të fortë gjatë ngritjes së peshave. Rripi i rregullueshëm me velkro siguron mbrojtje dhe rehati shtesë për pëllëmbët dhe kyçet e duarve.</p>"]' ELSE DescriptionAl END
WHERE Product_Id = 2331;

-- Product_Id: 2334 (BOLERO)
UPDATE dbo.Products SET
    NameAl = CASE WHEN ISNULL(NameAl, N'') = N'' THEN N'BOLERO' ELSE NameAl END,
    DescriptionAl = CASE WHEN ISNULL(DescriptionAl, N'') = N'' THEN N'["<ul><li><p>Pije e menjëhershme frutash me shije</p></li><li><p>Zgjedhje e madhe shijesh</p></li><li><p>Me vitaminë C të shtuar</p></li><li><p>Pa sheqer, gluten dhe laktozë</p></li><li><p>1 qeskë = 1,5 L pije</p></li><li><p>Varianti ENERGY: 1 qeskë = 500 ml pije</p></li></ul><p>Freskohuni nga brenda me BOLERO CLASSIC. Shijoni zgjedhjen e gjerë të shijeve në çdo kohë të ditës.</p><p><strong>BOLERO CLASSIC:</strong></p><ul><li><p>Me vitaminë C të shtuar</p></li><li><p>Pa sheqer, gluten dhe laktozë</p></li><li><p>Pa ngjyrues dhe konservues artificialë</p></li><li><p>1 qeskë = 1,5 L pije</p></li></ul><p><strong>BOLERO ENERGY:</strong></p><ul><li><p>Me kafeinë dhe taurinë të shtuar për më shumë energji</p></li><li><p>Pa sheqer, gluten dhe laktozë</p></li><li><p>Pa ngjyrues dhe konservues artificialë</p></li><li><p>1 qeskë = 500 ml pije</p></li></ul><p><strong>A E DINIT SE PIJET BOLERO:</strong></p><ul><li><p>Nuk përmbajnë sheqer</p></li><li><p>Janë me çmim të përballueshëm dhe ofrojnë zgjedhje të gjerë shijesh</p></li><li><p>Mund të përgatiten me ujë të gazuar ose ujë të zakonshëm rubineti</p></li><li><p>Kanë vlerë të ulët kalorike</p></li><li><p>Ju mundësojnë ta rregulloni vetë sasinë e ujit, sipas intensitetit të shijes që dëshironi</p></li><li><p>Janë zgjedhje e shijshme për të gjithë ata që kujdesen për ushqyerjen</p></li><li><p>Janë të paketuara në mënyrë praktike, që t’i merrni me vete kudo që të shkoni – në punë, stërvitje ose pushime</p></li><li><p>Ju mundësojnë të krijoni kombinime të pafundme shijesh duke përzier dy ose më shumë shije të ndryshme</p></li></ul>"]' ELSE DescriptionAl END,
    InstructionsForUseAl = CASE WHEN ISNULL(InstructionsForUseAl, N'') = N'' THEN N'Madhësia e porcionit: 1 qeskë (9 g / 8 g).' ELSE InstructionsForUseAl END,
    InstructionsForUseDescriptionAl = CASE WHEN ISNULL(InstructionsForUseDescriptionAl, N'') = N'' THEN N'RUAJTJA: Ruajeni në vend të thatë, në temperaturë 15–25°C.' ELSE InstructionsForUseDescriptionAl END,
    InstructionsOnHowToUseItAl = CASE WHEN ISNULL(InstructionsOnHowToUseItAl, N'') = N'' THEN N'Tretni 1 porcion në 1,5 L ujë të ftohtë (shijen ENERGY tretni në 250 ml ujë të ftohtë). Sasinë e ujit mund ta rregulloni sipas intensitetit të dëshiruar të shijes.' ELSE InstructionsOnHowToUseItAl END
WHERE Product_Id = 2334;

COMMIT TRANSACTION;
